// ═══════════════════════════════════════════════════════════════
// Router v3: Audio / Text / Button-Klick (callback_query)
// ═══════════════════════════════════════════════════════════════
// CHANGELOG ggü. v2:
//   Zusätzliche callback_data-Pattern für die Vorschau-Buttons:
//
//     confirm  →  text "OK"
//     correct  →  text "Korrektur"
//     redo     →  text "Neu diktieren"
//     edit:<n> →  text "/preise <n>"
//
//   Die einfachen Buttons werden 1:1 als Text durchgereicht, sodass
//   der nachgelagerte Session Handler sie exakt wie eine getippte
//   Antwort interpretiert (matched auf seine bestehenden Regex).
//
// CHANGELOG ggü. v1:
//   callback_query Events erkennen, answerCallbackQuery senden.
//
// WICHTIG: Im Telegram-Trigger müssen Updates "message" UND
//          "callback_query" aktiviert sein.
// ═══════════════════════════════════════════════════════════════
const BOT_TOKEN = '8612931190:AAEydMS-p9FH7fwiym80Ur7sgRHNrSaWUSw';

// Mapping einfacher Buttons → Text-Antwort (wie wenn User getippt hätte)
const SIMPLE_BUTTONS = {
  'confirm': 'OK',
  'correct': 'Korrektur',
  'redo':    'Neu diktieren'
};

const body = $input.first().json.body ?? $input.first().json;

// ─── Button-Klick (callback_query)? ─────────────────────────────
const callback = body.callback_query;
if (callback) {
  const chat_id = callback.message?.chat?.id ?? null;
  const from_user = callback.from?.username ?? callback.from?.first_name ?? 'unbekannt';
  const callback_id = callback.id;
  const callback_data = callback.data || '';

  // answerCallbackQuery: stoppt Loading-Animation im Telegram-UI.
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${BOT_TOKEN}/answerCallbackQuery`,
      body: { callback_query_id: callback_id },
      json: true
    });
  } catch (e) {
    console.error('answerCallbackQuery fehlgeschlagen:', e.message);
  }

  // Einfache Buttons (OK / Korrektur / Neu diktieren)
  if (SIMPLE_BUTTONS[callback_data]) {
    return [{
      json: {
        is_text_response: true,
        text_content: SIMPLE_BUTTONS[callback_data],
        chat_id,
        from_user,
        bot_token: BOT_TOKEN,
        download_base: `https://api.telegram.org/file/bot${BOT_TOKEN}/`,
        from_callback: true
      }
    }];
  }

  // Bearbeiten-Button mit Angebotsnummer
  if (callback_data.startsWith('edit:')) {
    const angebotsnummer = callback_data.substring(5).trim();
    return [{
      json: {
        is_text_response: true,
        text_content: `/preise ${angebotsnummer}`,
        chat_id,
        from_user,
        bot_token: BOT_TOKEN,
        download_base: `https://api.telegram.org/file/bot${BOT_TOKEN}/`,
        from_callback: true
      }
    }];
  }

  throw new Error(`Unbekannter Button-Callback: ${callback_data}`);
}

// ─── Standard: message Event ────────────────────────────────────
const msg = body.message ?? body;

const chat_id = msg.chat?.id ?? null;
const from_user = msg.from?.username ?? msg.from?.first_name ?? 'unbekannt';

if (msg.text && !msg.voice && !msg.audio && !(msg.document?.mime_type?.startsWith('audio/'))) {
  return [{
    json: {
      is_text_response: true,
      text_content: msg.text.trim(),
      chat_id,
      from_user,
      bot_token: BOT_TOKEN,
      download_base: `https://api.telegram.org/file/bot${BOT_TOKEN}/`
    }
  }];
}

let file_id = null;
let file_type = null;

if (msg.voice) {
  file_id = msg.voice.file_id;
  file_type = 'voice';
} else if (msg.audio) {
  file_id = msg.audio.file_id;
  file_type = 'audio';
} else if (msg.document && msg.document.mime_type?.startsWith('audio/')) {
  file_id = msg.document.file_id;
  file_type = 'document';
}

if (!file_id) {
  throw new Error('Keine Audio-/Textnachricht erkannt.');
}

return [{
  json: {
    is_text_response: false,
    file_id,
    file_type,
    chat_id,
    from_user,
    bot_token: BOT_TOKEN,
    get_file_url: `https://api.telegram.org/bot${BOT_TOKEN}/getFile?file_id=${file_id}`,
    download_base: `https://api.telegram.org/file/bot${BOT_TOKEN}/`
  }
}];

// ═══════════════════════════════════════════════════════════════
// Session-Lookup & Confirmation-Handler v3
// + Slash-Command-Erkennung für /preise YYYY-NNNNNN
// + Send-State-Erkennung (Senden / Korrektur im awaiting_send_confirmation)
// ═══════════════════════════════════════════════════════════════
const { text_content, chat_id, bot_token } = $input.first().json;

// ─── Slash-Command zuerst (braucht keine aktive Session) ────────
if (text_content.startsWith('/')) {
  const preiseMatch = text_content.match(/^\/preise\s+(\d{4}-\d+)\s*$/i);
  if (preiseMatch) {
    return [{
      json: {
        action: 'load_for_prices',
        chat_id,
        bot_token,
        angebotsnummer: preiseMatch[1].trim()
      }
    }];
  }
  if (/^\/preise\b/i.test(text_content)) {
    return [{
      json: {
        action: 'error',
        chat_id,
        bot_token,
        message: 'Syntax: `/preise YYYY-NNNNNN`\n\nBeispiel: `/preise 2026-100006`'
      }
    }];
  }
  return [{
    json: {
      action: 'error',
      chat_id,
      bot_token,
      message: 'Unbekannter Befehl. Verfügbar:\n• `/preise 2026-NNNNNN` – Preise zu bestehendem Angebot ergänzen'
    }
  }];
}

// ─── Session-Logik ──────────────────────────────────────────────
const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
const session = staticData[sessionKey];

if (!session) {
  return [{
    json: {
      action: 'no_session',
      chat_id,
      bot_token,
      message: 'Keine aktive Session. Bitte ein Sprachdiktat senden um ein neues Angebot zu starten, oder `/preise YYYY-NNNNNN` um Preise zu einem bestehenden Angebot zu ergänzen.'
    }
  }];
}

const sessionAgeMs = Date.now() - (session.created_at || 0);
if (sessionAgeMs > 30 * 60 * 1000) {
  delete staticData[sessionKey];
  return [{
    json: {
      action: 'expired',
      chat_id,
      bot_token,
      message: 'Deine letzte Session ist abgelaufen (älter als 30 Minuten). Bitte neu starten.'
    }
  }];
}

const txt = text_content.toLowerCase().trim();

// ─── State-spezifische Routing ──────────────────────────────────

// State: awaiting_send_confirmation (nach Finalisiert-Insert)
if (session.state === 'awaiting_send_confirmation') {
  // Senden-Befehl
  if (/^(senden|sende|send|versenden)\b/i.test(txt)) {
    return [{
      json: {
        action: 'send_now',
        chat_id,
        bot_token,
        session
      }
    }];
  }
  // Abbruch
  if (/^(neu\s+diktieren|abbruch|abbrechen|stopp|stop|cancel)/i.test(txt)) {
    return [{
      json: {
        action: 'send_cancel',
        chat_id,
        bot_token
      }
    }];
  }
  // Korrektur (begrenzte Felder)
  if (/^(korrektur|ändern|fix|korrigieren)/i.test(txt)) {
    return [{
      json: {
        action: 'send_correct',
        chat_id,
        bot_token,
        correction_text: text_content,
        session
      }
    }];
  }
  // Unbekannte Antwort
  return [{
    json: {
      action: 'unknown',
      chat_id,
      bot_token,
      message: 'Antwort-Optionen für Versand:\n✅ `Senden`\n✏️ `Korrektur: feld wert`\n❌ `Abbruch`'
    }
  }];
}

// State: awaiting_confirmation (nach Direkt-Diktat-Preview)
if (/^(ok|passt|ja|freigabe|freigegeben|\u2713)\b/i.test(txt)) {
  return [{
    json: {
      action: 'confirm',
      chat_id,
      bot_token,
      session
    }
  }];
}

if (/^(neu\s+diktieren|abbruch|abbrechen|stopp|stop|cancel)/i.test(txt)) {
  delete staticData[sessionKey];
  return [{
    json: {
      action: 'cancel',
      chat_id,
      bot_token,
      message: 'Okay, Session beendet.'
    }
  }];
}

if (/^(korrektur|ändern|fix|korrigieren)/i.test(txt)) {
  return [{
    json: {
      action: 'correct',
      chat_id,
      bot_token,
      correction_text: text_content,
      session
    }
  }];
}

return [{
  json: {
    action: 'unknown',
    chat_id,
    bot_token,
    message: 'Unbekannte Antwort. Bitte antworte mit "OK", "Korrektur: [Feld] [Wert]" oder "Neu diktieren".'
  }
}];

// ═══════════════════════════════════════════════════════════════
// Session Save + Preview v4 (nur OK-Button)
//
// ÄNDERUNG ggü. v3:
//   reply_markup enthält jetzt NUR den OK-Button. Die Buttons für
//   "Korrektur" und "Neu diktieren" wurden entfernt, weil beide
//   im Workflow ohnehin ein Text-Diktat oder Text-Eingabe nötig
//   machen (Button-Klick allein führte zu Fehlermeldung).
//
//   Die Antwort-Optionen-Liste im Nachrichten-Text bleibt
//   unverändert mit allen drei Optionen — der User sieht weiter
//   alle Wege, kann aber nur OK direkt anklicken.
// ═══════════════════════════════════════════════════════════════

const data = $input.first().json;
const kd = data.kundendaten;
const chat_id = $('Message Router').first().json.chat_id;

// ─── Briefkopf-Preview aufbauen ─────────────────────────────────
const anredeZeile = kd.anrede === 'Herr' ? 'Herrn'
                  : kd.anrede === 'Frau' ? 'Frau'
                  : kd.anrede === 'Firma' ? 'Firma'
                  : kd.anrede;

let briefkopf = '```\n';
briefkopf += anredeZeile + '\n';
if (kd.firmenname) {
  briefkopf += kd.firmenname + '\n';
} else if (kd.vorname || kd.nachname) {
  briefkopf += [kd.vorname, kd.nachname].filter(Boolean).join(' ') + '\n';
}
briefkopf += [kd.strasse, kd.hausnummer].filter(Boolean).join(' ') + '\n';
briefkopf += [kd.plz, kd.ort].filter(Boolean).join(' ') + '\n\n';
briefkopf += (kd.telefon ? 'Tel.:   ' + kd.telefon + '\n' : '');
briefkopf += (kd.mail ? 'Mail:   ' + kd.mail + '\n' : '');
briefkopf += (kd.kundennummer ? 'Kd.-Nr.: ' + kd.kundennummer + '\n' : '');
briefkopf += (kd.uid ? 'UID:    ' + kd.uid + '\n' : '');
briefkopf += '```';

let baustellenBlock = '';
if (kd.baustelle) {
  baustellenBlock = '\n\n🏗 *Baustelle:*\n```\n';
  if (kd.baustelle.plz_ort) baustellenBlock += kd.baustelle.plz_ort + '\n';
  if (kd.baustelle.strasse) baustellenBlock += kd.baustelle.strasse + '\n';
  if (kd.baustelle.hinweis) baustellenBlock += kd.baustelle.hinweis + '\n';
  baustellenBlock += '```';
}

let metaBlock = '\n\n';
metaBlock += '📄 *Betreff:* ' + (kd.betreff || '_(wird automatisch aus Gewerken ermittelt)_') + '\n';
metaBlock += '👤 *Sachbearbeiter:* ' + (kd.sachbearbeiter || '_Ing. Ernst Baumeister (Standard)_') + '\n';

let previewMessage = '📋 *So wird der Briefkopf im Angebot aussehen:*\n\n' + briefkopf;
previewMessage += baustellenBlock;
previewMessage += metaBlock;

if (kd.warnings && kd.warnings.length > 0) {
  previewMessage += '\n⚠️ *Hinweise:*\n';
  for (const w of kd.warnings) previewMessage += '• ' + w + '\n';
}

if (kd.pflichtfehler && kd.pflichtfehler.length > 0) {
  previewMessage += '\n❌ *Pflichtfelder fehlen - bitte neu diktieren!*\n';
}

previewMessage += '\n*Antwort-Optionen:*\n';
previewMessage += '✅ `OK` → Angebot wird erstellt\n';
previewMessage += '✏️ `Korrektur: [Feld] [neuer Wert]` → einzelnes Feld\n';
previewMessage += '🔁 `Neu diktieren` → Abbruch';

const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
staticData[sessionKey] = {
  created_at: Date.now(),
  state: 'awaiting_confirmation',
  kundendaten: kd,
  rest_transkript: data.rest_transkript,
  original_transkript: data.original_transkript
};

// Nur OK-Button
const replyMarkup = JSON.stringify({
  inline_keyboard: [
    [{ text: '✅ OK', callback_data: 'confirm' }]
  ]
});

return [{
  json: {
    chat_id,
    bot_token: $('Message Router').first().json.bot_token,
    preview_message: previewMessage,
    has_pflichtfehler: (kd.pflichtfehler && kd.pflichtfehler.length > 0),
    reply_markup: replyMarkup
  }
}];

// ═══════════════════════════════════════════════════════════════
// Nach OK-Bestätigung: Session laden, Position-Pipeline starten
// ═══════════════════════════════════════════════════════════════
// FIX: original_transkript wird als whisper_transkript mitgegeben,
// damit es im Confirm-Run für SeaTable verfügbar ist (Whisper-Node
// läuft in einem anderen n8n-Run und ist hier nicht erreichbar).
const { chat_id, bot_token, session } = $input.first().json;

// Session aus Static Data entfernen (wird jetzt konsumiert)
const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
delete staticData[sessionKey];

return [{
  json: {
    chat_id,
    bot_token,
    kundendaten: session.kundendaten,
    text: session.rest_transkript,                         // emuliert Whisper-Output für Position-Parser
    whisper_transkript: session.original_transkript || ''  // NEU: für SeaTable-Persistierung
  }
}];

// ═══════════════════════════════════════════════════════════════
// Merge Position Data v2 (ALL ITEMS) — mit Beschreibungs-Cleanup
//
// Verarbeitet ALLE Items aus dem LLM-Output in einem Durchlauf.
// Zippt sie mit den Metadaten aus "Split Positions" zusammen.
//
// ÄNDERUNG ggü. v1:
//   cleanBeschreibung() entfernt die Verrechnungsmenge+Einheit aus
//   beschreibung_normalisiert, wenn sie dort redundant zu den
//   separaten Feldern menge/einheit steht.
//
//   Beispiel:
//     LLM-Output: "Rasenmähen 55 m²" + menge=55, einheit=m²
//     Nach Cleanup: "Rasenmähen"
//
//   Damit wird verhindert, dass bei späteren Mengen-Korrekturen
//   (per /preise) der alte Wert in der Beschreibungsspalte stehen
//   bleibt während die separate Mengen-Spalte schon aktualisiert ist.
//
//   Produktdimensionen wie "30 x 60" bleiben unangetastet, weil das
//   "x" oder "mal" zwischen den Zahlen das Pattern nicht matched.
// ═══════════════════════════════════════════════════════════════

const llmItems = $input.all();
const splitItems = $('Split Positions').all();

if (llmItems.length !== splitItems.length) {
  throw new Error(`Anzahl-Mismatch: ${llmItems.length} LLM-Items vs. ${splitItems.length} Position-Items. Pipeline gebrochen.`);
}

// ─── Cleanup: Verrechnungsmenge+Einheit aus Beschreibung entfernen ───
const EINHEIT_ROH = {
  'm²':    ['m²', 'm2', 'qm', 'quadratmeter'],
  'lfm':   ['lfm', 'lm', 'laufmeter', 'meter'],
  'Stück': ['stück', 'stk', 'stueck'],
  'h':     ['h', 'stunde', 'stunden'],
  'Tage':  ['tag', 'tage', 'tagen'],
  'Monate':['monat', 'monate', 'monaten'],
  'kg':    ['kg', 'kilo', 'kilogramm'],
  'm³':    ['m³', 'm3', 'kubikmeter', 'kubik']
};

// Zahlen 1-12 als Wort (für Treffer wie "drei Stück" wenn menge=3)
const ZAHLWORT_REVERSE = ['', 'ein', 'zwei', 'drei', 'vier', 'fünf',
                          'sechs', 'sieben', 'acht', 'neun', 'zehn', 'elf', 'zwölf'];

function escRe(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function cleanBeschreibung(text, menge, einheit) {
  if (!text || typeof text !== 'string') return text;
  if (menge === null || menge === undefined || !einheit) return text;

  // Sonderfall Pauschal: "pauschal" / "komplett" / "einmal pauschal" als
  // alleinstehendes Token entfernen, egal wo im Text. Menge ist hier
  // immer 1 und wird nicht im Text gesucht.
  if (einheit === 'Pauschal') {
    let r = text.replace(/\b(?:einmal\s+pauschal|pauschal|komplett)\b/gi, '');
    r = r.replace(/\s+/g, ' ').trim();
    r = r.replace(/^[\s,.;:]+|[\s,.;:]+$/g, '').trim();
    return r || text;
  }

  const rohWoerter = EINHEIT_ROH[einheit];
  if (!rohWoerter || rohWoerter.length === 0) return text;

  // Mengen-Repräsentationen: direkte Zahl + ggf. Zahlwort
  const mengeRepr = new Set();
  mengeRepr.add(String(menge));
  if (!Number.isInteger(menge)) {
    // Whisper schreibt mal "55,5" mal "55.5"
    mengeRepr.add(String(menge).replace('.', ','));
  }
  if (Number.isInteger(menge) && menge >= 1 && menge <= 12) {
    mengeRepr.add(ZAHLWORT_REVERSE[menge]);
  }

  const mengeAlt = Array.from(mengeRepr).filter(s => s).map(escRe).join('|');
  const einheitAlt = rohWoerter.map(escRe).join('|');

  // Pattern: (menge)\s*(einheit) als zusammenhängender Token
  // Boundary vorne: Anfang, Whitespace oder Komma
  // Boundary hinten: Whitespace, Satzzeichen oder Ende
  // (kein \b nach m²/m³, weil Unicode-Zeichen keine Word-Chars sind)
  const re = new RegExp(
    `(?:^|[\\s,;:])(?:${mengeAlt})\\s*(?:${einheitAlt})(?=[\\s,.;:!?]|$)`,
    'gi'
  );

  let cleaned = text.replace(re, ' ');
  cleaned = cleaned.replace(/\s+/g, ' ').trim();
  cleaned = cleaned.replace(/^[\s,.;:]+|[\s,.;:]+$/g, '').trim();

  // Fallback: wenn nach Cleanup nichts mehr übrig ist (z.B. Beschreibung
  // war NUR "55 m²"), Original behalten — sonst wäre die Position leer.
  return cleaned || text;
}

const results = [];

for (let i = 0; i < llmItems.length; i++) {
  const llmRaw = llmItems[i].json;
  const meta = splitItems[i].json;

  let d;
  try {
    // Tolerant gegenüber verschiedenen LLM-Output-Strukturen:
    // - Direkt das JSON-Objekt
    // - .message.content (Legacy OpenAI)
    // - .output[0].content[0].text (Responses API, Object oder String)
    // - .content[0].text (einige andere Varianten)
    let c = llmRaw?.message?.content
         ?? llmRaw?.output?.[0]?.content?.[0]?.text
         ?? llmRaw?.content?.[0]?.text
         ?? llmRaw?.text
         ?? llmRaw;

    if (typeof c === 'string') {
      c = c.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
      d = JSON.parse(c);
    } else {
      d = c;
    }
  } catch (e) {
    d = {
      beschreibung_normalisiert: meta.rohtext || '(Fehler bei LLM-Parse)',
      menge: null, einheit: null, einzelpreis_netto: null,
      hat_preis: false,
      konfidenz_hinweise: ['LLM-Parse-Fehler: ' + e.message]
    };
  }

  // Beschreibung von redundanter Verrechnungsmenge+Einheit befreien
  const beschreibungRaw = d?.beschreibung_normalisiert || '(leer)';
  const beschreibungCleaned = cleanBeschreibung(
    beschreibungRaw,
    d?.menge ?? null,
    d?.einheit ?? null
  );

  results.push({
    json: {
      position_nr: meta.position_nr,
      ist_optional: meta.ist_optional,
      gewerk: meta.gewerk,
      rohtext: meta.rohtext,
      beschreibung_normalisiert: beschreibungCleaned,
      menge: d?.menge ?? null,
      einheit: d?.einheit ?? null,
      einzelpreis_netto: d?.einzelpreis_netto ?? null,
      hat_preis: !!d?.hat_preis && d?.einzelpreis_netto !== null,
      konfidenz_hinweise: Array.isArray(d?.konfidenz_hinweise) ? d.konfidenz_hinweise : []
    }
  });
}

return results;

// ═══════════════════════════════════════════════════════════════
// Validator + Summen v2 (ERWEITERT)
//
// Neu:
// - Reicht neue Kundendaten-Felder durch (kundennummer, uid, baustelle)
// - Ermittelt finalen Betreff (diktiert ODER auto-generiert)
// - Ermittelt finalen Sachbearbeiter (diktiert ODER Fallback)
// - Auto-Betreff-Logik:
//   * Wenn ist_sanierung: "Sanierungsarbeiten"
//   * Wenn genau 1 Gewerk: Gewerk-Name
//   * Sonst: "Diverse Arbeiten"
// ═══════════════════════════════════════════════════════════════

const raw = $input.first().json.data;
const parserWarn = $('Position-Parser').first().json.warnings || [];
const kundendaten = $('Position-Parser').first().json.kundendaten;

if (!Array.isArray(raw) || raw.length === 0) throw new Error('Keine Positionen.');

const reg = raw.filter(p => !p.ist_optional).sort((a,b) => a.position_nr - b.position_nr);
const opt = raw.filter(p => p.ist_optional).sort((a,b) => a.position_nr - b.position_nr);
const erlaubt = ['Stück','m²','lfm','h','Tage','kg','Pauschal'];
const vw = [...parserWarn];

function validiere(p) {
  const w = [...(p.konfidenz_hinweise || [])];
  let flag = w.length > 0;
  if (!p.beschreibung_normalisiert || p.beschreibung_normalisiert.trim().length < 3) { w.push('Beschreibung fehlt'); flag = true; }
  if (p.einheit !== null && !erlaubt.includes(p.einheit)) { w.push(`Unbekannte Einheit: ${p.einheit}`); flag = true; }
  if (p.hat_preis) {
    if (typeof p.einzelpreis_netto !== 'number' || p.einzelpreis_netto <= 0) { w.push('Preis unplausibel'); flag = true; p.hat_preis = false; p.einzelpreis_netto = null; }
    else if (p.einzelpreis_netto > 1000000) { w.push('Preis > 1M'); flag = true; }
  }
  if (p.menge !== null && (typeof p.menge !== 'number' || p.menge <= 0)) { w.push('Menge unplausibel'); flag = true; }
  if (p.hat_preis && p.menge === null) { p.menge = 1; p.einheit = p.einheit || 'Pauschal'; }
  p.konfidenz_hinweise = w; p.hat_warnung = flag; return p;
}

const vReg = reg.map(validiere);
const vOpt = opt.map(validiere);

function zsumme(p) {
  if (p.hat_preis && typeof p.menge === 'number' && typeof p.einzelpreis_netto === 'number') {
    return { ...p, zeilensumme_netto: Math.round(p.menge * p.einzelpreis_netto * 100) / 100 };
  }
  return { ...p, zeilensumme_netto: null };
}
const rReg = vReg.map(zsumme);
const rOpt = vOpt.map(zsumme);

const mitPreis = rReg.filter(p => p.hat_preis);
const hatPreise = mitPreis.length > 0;
const gemischt = hatPreise && mitPreis.length < rReg.length;
if (gemischt) {
  const op = rReg.filter(p => !p.hat_preis).map(p => p.position_nr);
  vw.push(`Gemischte Diktion: Positionen ohne Preis: ${op.join(', ')}.`);
  rReg.forEach(p => { if (!p.hat_preis) { p.hat_warnung = true; p.konfidenz_hinweise.push('Fehlender Preis'); }});
}

function kr(x) { return Math.round(x * 100) / 100; }
let summen = { zwischensumme_netto: null, ust_20: null, endbetrag_brutto: null };
if (hatPreise) {
  const zs = kr(rReg.filter(p => p.hat_preis).reduce((a,p) => a + p.zeilensumme_netto, 0));
  const u = kr(zs * 0.20);
  summen = { zwischensumme_netto: zs, ust_20: u, endbetrag_brutto: kr(zs + u) };
}
const oMitP = rOpt.filter(p => p.hat_preis);
let oSum = null;
if (oMitP.length) {
  const zs = kr(oMitP.reduce((a,p) => a + p.zeilensumme_netto, 0));
  const u = kr(zs * 0.20);
  oSum = { zwischensumme_netto: zs, ust_20: u, endbetrag_brutto: kr(zs + u) };
}

const now = new Date();
const angebot_nr = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}`;

// ─── NEU: Finaler Betreff ───────────────────────────────────────
// Priorität: 1. Diktiert > 2. Sanierung-Flag > 3. 1 Gewerk = Gewerk-Name > 4. Diverse Arbeiten
let finaler_betreff = kundendaten?.betreff;
if (!finaler_betreff) {
  const gewerke = [...new Set(rReg.map(p => p.gewerk).filter(Boolean))];
  if (kundendaten?.ist_sanierung) {
    finaler_betreff = 'Sanierungsarbeiten';
  } else if (gewerke.length === 1) {
    finaler_betreff = gewerke[0];
  } else {
    finaler_betreff = 'Diverse Arbeiten';
  }
}

// ─── NEU: Finaler Sachbearbeiter ────────────────────────────────
const finaler_sachbearbeiter = kundendaten?.sachbearbeiter || 'Ing. Ernst Baumeister';

// ─── NEU: Finale Baustelle (null wenn nicht diktiert = nicht anzeigen) ──
// Wenn Baustelle nicht diktiert, bleibt es bei null.
// Der DOCX Generator zeigt Baustelle nur wenn Werte da sind.
// So bleibt die Darstellung sauber: Kundenadresse im Briefkopf links,
// Baustelle rechts nur wenn sie wirklich abweicht.
const finale_baustelle = kundendaten?.baustelle || null;

return [{ json: {
  angebot_nr,
  datum: now.toLocaleDateString('de-AT'),
  modus: hatPreise ? 'preis' : 'leistung',
  hat_gemischte_diktion: gemischt,
  hat_optionale_positionen: rOpt.length > 0,
  regulaere_positionen: rReg,
  optionale_positionen: rOpt,
  summen,
  optionale_summen: oSum,
  warnings: vw,
  kundendaten,
  // NEU:
  betreff: finaler_betreff,
  sachbearbeiter: finaler_sachbearbeiter,
  baustelle: finale_baustelle
}}];

// ═══════════════════════════════════════════════════════════════════════════
// DOCX Generator v18 – Optionale Positionen mit 'à' und 'gesamt:' (rechtlich klar) + v17 Inline-Layout
// - Liest Daten aus Validator+Summen (regulaere/optionale_positionen, summen)
// - Layout wie GALBAU v11 (GAL Header/Footer, DIN 5008, Floating Footer)
// - Word-2019-Kompatibel (type: 'jpg' bei ImageRun)
// - Footer mit 12mm Druck-Safety-Margin
// ═══════════════════════════════════════════════════════════════════════════

const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, ImageRun, AlignmentType, BorderStyle, WidthType,
  VerticalAlign, PageNumber, TabStopType,
  HorizontalPositionRelativeFrom, HorizontalPositionAlign,
  VerticalPositionRelativeFrom,
  TextWrappingType, TextWrappingSide,
} = require('docx');

// ── 0. Input-Daten ─────────────────────────────────────────────────────
const d = $input.first().json;
const {
  angebot_nr, datum, modus,
  regulaere_positionen, optionale_positionen,
  summen, optionale_summen, warnings,
  hat_optionale_positionen, kundendaten
} = d;

// Validierung: angebot_nr muss im Input vorhanden sein
// (kommt vom Counter-Block oder ist aus Legacy-Workflow noch Datums-basiert)
if (!angebot_nr) {
  throw new Error(
    'angebot_nr fehlt im Input. Stelle sicher dass der Counter-Block ' +
    '(Counter laden → Nummer berechnen → Counter erhöhen → Pipeline fortsetzen) ' +
    'vor dem DOCX-Generator läuft.'
  );
}

// ── 1. DYNAMISCHE FELDER (aus Validator + Summen) ─────────────────────
// Werden vom Validator gesetzt mit Fallbacks:
// - sachbearbeiter: diktiert ODER "Ing. Ernst Baumeister"
// - betreff: diktiert ODER auto-generiert ("Sanierungsarbeiten" / Gewerk-Name / "Diverse Arbeiten")
// - baustelle: diktiert ODER null (dann nicht angezeigt)
const SACHBEARBEITER = d.sachbearbeiter || 'Ing. Ernst Baumeister';
const BETREFF = d.betreff || 'Diverse Arbeiten';
const KUNDENNUMMER = kundendaten?.kundennummer || '';
const KUNDEN_UID = kundendaten?.uid || '';
// Baustelle-Fallback: Wenn keine diktiert, Kundenadresse übernehmen
const BAUSTELLE_PLZ_ORT = d.baustelle?.plz_ort
  || [kundendaten?.plz, kundendaten?.ort].filter(Boolean).join(' ');
const BAUSTELLE_STRASSE = d.baustelle?.strasse
  || [kundendaten?.strasse, kundendaten?.hausnummer].filter(Boolean).join(' ');
const BAUSTELLE_HINWEIS = d.baustelle?.hinweis || '';

// ── 2. GAL-Bilder als Base64 (aus GALBAU-Projekt) ──────────────────────
const GAL_HEADER_BASE64 = '';
const GAL_FOOTER_BASE64 = '';

const headerImgBuffer = Buffer.from(GAL_HEADER_BASE64, 'base64');
const footerImgBuffer = Buffer.from(GAL_FOOTER_BASE64, 'base64');

// ── 3. DOCX-Konstanten ────────────────────────────────────────────────
const FONT = 'Arial';
const PT8 = 16, PT9 = 18, PT10 = 20, PT11 = 22, PT12 = 24;
const A4_W = 11906, A4_H = 16838;
const MG = 1134;
const CW = A4_W - 2 * MG;

// Spaltenbreiten für Positions-Tabelle
const C_POS = 880, C_MNG = 1020, C_EIN = 1110, C_PRE = 1350, C_GES = 1400;
const C_BEZ = modus === 'preis'
  ? (CW - C_POS - C_MNG - C_EIN - C_PRE - C_GES)
  : (CW - C_POS - C_MNG - C_EIN - C_GES);

const NONE = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
const nb = () => ({ top: NONE, bottom: NONE, left: NONE, right: NONE });
const ROT = 'CC0000';

const HEADER_W = 640, HEADER_H = 52;
const FOOTER_W = 640, FOOTER_H = 55;

// Footer-Positionierung: 12mm Abstand zum unteren Seitenrand
const FOOTER_OFFSET_FROM_PAGE_TOP_EMU = 9736125;

// ── 4. Helper ─────────────────────────────────────────────────────────
const tx = (t, o = {}) => new TextRun({
  text: String(t), font: FONT,
  size: o.size ?? PT9,
  bold: o.bold ?? false,
  italics: o.italic ?? false,
  color: o.rot ? ROT : undefined
});

const pr = (c, o = {}) => new Paragraph({
  spacing: { before: o.before ?? 0, after: o.after ?? 40 },
  alignment: o.align,
  border: o.border,
  children: Array.isArray(c) ? c : [c]
});

function fmtC(n) {
  if (n == null) return '';
  return new Intl.NumberFormat('de-AT', {
    minimumFractionDigits: 2, maximumFractionDigits: 2
  }).format(n) + ' €';
}

function fmtM(n) {
  if (n == null) return '';
  return new Intl.NumberFormat('de-AT', {
    minimumFractionDigits: 0, maximumFractionDigits: 2
  }).format(n);
}

// ── 5. DIN 5008 Briefkopf (Empfänger + Sachbearbeiter) ────────────────
// DIN 5008 Spacer: Adresse beginnt bei 45mm vom oberen Rand
const dinSpacerParagraph = new Paragraph({
  spacing: { before: 0, after: 1020 },
  children: [new TextRun({ text: '', font: FONT, size: 2 })],
});

// Empfänger-Anrede-Zeile
const anredeZeile = kundendaten?.anrede === 'Herr' ? 'Herrn'
                  : kundendaten?.anrede === 'Frau' ? 'Frau'
                  : kundendaten?.anrede === 'Firma' ? 'Firma'
                  : (kundendaten?.anrede || '');

const nameZeile = kundendaten?.firmenname
                  || [kundendaten?.vorname, kundendaten?.nachname].filter(Boolean).join(' ');
const adrZeile1 = [kundendaten?.strasse, kundendaten?.hausnummer].filter(Boolean).join(' ');
const adrZeile2 = [kundendaten?.plz, kundendaten?.ort].filter(Boolean).join(' ');

// Linke Spalte: Empfänger-Adresse (bold, 10pt wie im GAL-Layout)
const adressblockParagraphs = [
  new Paragraph({
    spacing: { before: 0, after: 60 },
    children: [tx(anredeZeile, { size: PT10 })],
  }),
  new Paragraph({
    spacing: { before: 0, after: 60 },
    children: [tx(nameZeile, { bold: true, size: PT10 })],
  }),
  new Paragraph({
    spacing: { before: 120, after: 60 },
    children: [tx(adrZeile1, { bold: true, size: PT10 })],
  }),
  new Paragraph({
    spacing: { before: 0, after: 60 },
    children: [tx(adrZeile2, { bold: true, size: PT10 })],
  }),
];

// Rechte Spalte: Sachbearbeiter + Kundendaten
const rightColParagraphs = [
  new Paragraph({
    spacing: { before: 0, after: 120 },
    children: [
      tx('Sachbearbeiter: ', { bold: true, size: PT9 }),
      tx(SACHBEARBEITER, { size: PT9 }),
    ],
  }),
];

// Kundennummer nur anzeigen wenn vorhanden
if (KUNDENNUMMER) {
  rightColParagraphs.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [
      tx('Kundennummer: ', { bold: true, size: PT9 }),
      tx(KUNDENNUMMER, { size: PT9 }),
    ],
  }));
}

if (KUNDEN_UID) {
  rightColParagraphs.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [
      tx('Kunden-UID-Nr.: ', { bold: true, size: PT9 }),
      tx(KUNDEN_UID, { size: PT9 }),
    ],
  }));
}

if (kundendaten?.mail) {
  rightColParagraphs.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [
      tx('Kunden-E-Mail: ', { bold: true, size: PT9 }),
      tx(kundendaten.mail, { size: PT9 }),
    ],
  }));
}

if (kundendaten?.telefon) {
  rightColParagraphs.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [
      tx('Kunden-Tel.: ', { bold: true, size: PT9 }),
      tx(kundendaten.telefon, { size: PT9 }),
    ],
  }));
}

// Baustellen-Block - IMMER anzeigen
// Wenn diktiert: eigene Baustelle. Wenn nicht: Kundenadresse als Fallback (siehe Platzhalter-Block oben)
rightColParagraphs.push(new Paragraph({
  spacing: { before: 200, after: 40 },
  children: [tx('Baustelle:', { bold: true, size: PT9 })],
}));
// DIN-5008-konform: Straße über PLZ/Ort
if (BAUSTELLE_STRASSE) {
  rightColParagraphs.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [tx(BAUSTELLE_STRASSE, { size: PT9 })],
  }));
}
if (BAUSTELLE_PLZ_ORT) {
  rightColParagraphs.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [tx(BAUSTELLE_PLZ_ORT, { size: PT9 })],
  }));
}
if (BAUSTELLE_HINWEIS) {
  rightColParagraphs.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [tx(BAUSTELLE_HINWEIS, { bold: true, size: PT8 })],
  }));
}

// Zweispaltige Briefkopf-Tabelle (62% links / 38% rechts)
const FIRST_PAGE_LEFT = Math.round(CW * 0.62);
const FIRST_PAGE_RIGHT = CW - FIRST_PAGE_LEFT;

const kundendatenTable = new Table({
  width: { size: CW, type: WidthType.DXA },
  columnWidths: [FIRST_PAGE_LEFT, FIRST_PAGE_RIGHT],
  rows: [new TableRow({
    children: [
      new TableCell({
        borders: nb(),
        width: { size: FIRST_PAGE_LEFT, type: WidthType.DXA },
        margins: { top: 0, bottom: 0, left: 0, right: 120 },
        verticalAlign: VerticalAlign.TOP,
        children: adressblockParagraphs,
      }),
      new TableCell({
        borders: nb(),
        width: { size: FIRST_PAGE_RIGHT, type: WidthType.DXA },
        margins: { top: 0, bottom: 0, left: 120, right: 0 },
        verticalAlign: VerticalAlign.TOP,
        children: rightColParagraphs,
      }),
    ],
  })],
});

// Spacer vor "Angebot Nr."
const spacerAboveAngebot = new Paragraph({
  spacing: { before: 0, after: 800 },
  children: [new TextRun({ text: '', font: FONT, size: 2 })],
});

// "Angebot Nr. ... vom ..."  links + "Seite 1" rechts (hardcoded)
const angebotNrParagraph = new Paragraph({
  spacing: { before: 0, after: 0 },
  tabStops: [{ type: TabStopType.RIGHT, position: CW }],
  children: [
    tx('Angebot Nr. ', { bold: true, size: PT12 }),
    tx(angebot_nr, { bold: true, size: PT12 }),
    tx(' vom ', { bold: true, size: PT12 }),
    tx(datum, { bold: true, size: PT12 }),
    new TextRun({ text: '\t', font: FONT, size: PT9 }),
    new TextRun({ text: 'Seite 1', font: FONT, size: PT9 }),
  ],
});

// Betrifft-Zeile
const betrifftParagraph = new Paragraph({
  spacing: { before: 240, after: 360 },
  children: [
    tx('Betrifft: ', { size: PT9 }),
    tx(BETREFF, { size: PT9 }),
  ],
});

// ── 6. Warnings-Block (rot umrandet, falls vorhanden) ──────────────────
function warnBlk() {
  if (!warnings || warnings.length === 0) return [];
  const el = [
    new Paragraph({
      spacing: { before: 0, after: 120 },
      border: {
        top: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
        bottom: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
        left: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
        right: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
      },
      children: [tx('Hinweise zu diesem Entwurf:', { bold: true, rot: true, size: PT10 })],
    }),
  ];
  for (const w of warnings) {
    el.push(new Paragraph({
      spacing: { before: 0, after: 60 },
      children: [tx('• ' + w, { rot: true })],
    }));
  }
  el.push(new Paragraph({ spacing: { after: 240 }, children: [tx('')] }));
  return el;
}

// ── 7. Hauptpositions-Tabelle mit Gewerk-Gruppierung ──────────────────
const hBorder = {
  top: NONE, left: NONE, right: NONE,
  bottom: { style: BorderStyle.SINGLE, size: 6, color: '444444' }
};

const hCell = (txt, w, a) => new TableCell({
  borders: hBorder,
  width: { size: w, type: WidthType.DXA },
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  children: [new Paragraph({
    alignment: a,
    children: [new TextRun({ text: txt, bold: true, font: FONT, size: PT10 })]
  })],
});

const hCells = [
  hCell('Pos.', C_POS, AlignmentType.LEFT),
  hCell('Bezeichnung', C_BEZ, AlignmentType.LEFT),
  hCell('Menge', C_MNG, AlignmentType.RIGHT),
  hCell('Einheit', C_EIN, AlignmentType.LEFT),
];
if (modus === 'preis') hCells.push(hCell('Einzelpreis', C_PRE, AlignmentType.RIGHT));
hCells.push(hCell('Gesamt', C_GES, AlignmentType.RIGHT));

const hRow = new TableRow({ tableHeader: true, children: hCells });

// Gruppiere Positionen nach Gewerk
function grp(list) {
  const g = [];
  let cur = { gewerk: null, items: [] };
  for (const p of list) {
    if (p.gewerk !== cur.gewerk) {
      if (cur.items.length) g.push(cur);
      cur = { gewerk: p.gewerk, items: [p] };
    } else {
      cur.items.push(p);
    }
  }
  if (cur.items.length) g.push(cur);
  return g;
}

// ── Hilfsfunktion: Inline-Text für optionale Positionen ──────────
// Wird in der Bezeichnungs-Spalte unter "Optional" angezeigt.
// Regeln:
//   - Optional ohne Preis  → leer (nur "Optional" steht da)
//   - Pauschal             → "Pauschal X,XX € netto"   (keine Menge, keine Wiederholung)
//   - Mit Menge + Einheit  → "30 m² 85,00 €, 2.550,00 € netto"
//   - Sonst (defensiv)     → "X,XX € netto"
function buildOptionalInlineText(p) {
  if (!p.hat_preis || typeof p.einzelpreis_netto !== 'number') {
    // Leistungsverzeichnis (kein Preis): Menge + Einheit trotzdem zeigen,
    // damit z.B. "20 lfm" bei optionalen Positionen nicht verloren geht.
    if (typeof p.menge === 'number' && p.einheit) {
      return `${fmtM(p.menge)} ${p.einheit}`;
    }
    return '';
  }
  const einzel = fmtC(p.einzelpreis_netto);
  const gesamt = fmtC(p.zeilensumme_netto);

  if (p.einheit === 'Pauschal') {
    return `Pauschal ${gesamt} netto`;
  }

  if (typeof p.menge === 'number' && p.einheit) {
    return `${fmtM(p.menge)} ${p.einheit} à ${einzel}, gesamt: ${gesamt} netto`;
  }

  return `${gesamt} netto`;
}

// Daten-Row für eine Position
// v17: Optionale Positionen bekommen die Preise inline in der
//      Bezeichnungs-Spalte (neue Zeile, "Optional" fett+kursiv,
//      Rest kursiv). Die Spalten Menge/Einheit/Einzelpreis/Gesamt
//      bleiben bei optionalen Zeilen leer.
function dRow(p) {
  const r = p.hat_warnung;

  // Bezeichnungs-Spalte
  const bezPars = [
    new Paragraph({
      spacing: { before: 0, after: 0 },
      children: [tx(p.beschreibung_normalisiert || '', { rot: r })]
    })
  ];

  if (p.ist_optional) {
    const inline = buildOptionalInlineText(p);
    const optChildren = [
      // "Optional" – fett + kursiv
      new TextRun({
        text: 'Optional',
        font: FONT,
        size: PT9,
        bold: true,
        italics: true,
        color: r ? ROT : undefined,
      }),
    ];
    if (inline) {
      // Rest – nur kursiv
      optChildren.push(new TextRun({
        text: ' ' + inline,
        font: FONT,
        size: PT9,
        italics: true,
        color: r ? ROT : undefined,
      }));
    }
    bezPars.push(new Paragraph({
      spacing: { before: 60, after: 40 },
      children: optChildren,
    }));
  } else {
    // Bei nicht-optionalen Positionen das spacing.after wieder aufholen,
    // damit die Tabellenzeilenhöhe gleich bleibt
    bezPars[0] = new Paragraph({
      spacing: { before: 0, after: 40 },
      children: [tx(p.beschreibung_normalisiert || '', { rot: r })]
    });
  }

  const cells = [
    new TableCell({
      borders: nb(),
      width: { size: C_POS, type: WidthType.DXA },
      margins: { top: 100, bottom: 100, left: 120, right: 120 },
      verticalAlign: VerticalAlign.TOP,
      children: [pr(tx(String(p.position_nr), { bold: true, rot: r }))],
    }),
    new TableCell({
      borders: nb(),
      width: { size: C_BEZ, type: WidthType.DXA },
      margins: { top: 100, bottom: 100, left: 120, right: 120 },
      verticalAlign: VerticalAlign.TOP,
      children: bezPars,
    }),
    new TableCell({
      borders: nb(),
      width: { size: C_MNG, type: WidthType.DXA },
      margins: { top: 100, bottom: 100, left: 120, right: 120 },
      verticalAlign: VerticalAlign.TOP,
      children: [new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [tx(p.ist_optional ? '' : fmtM(p.menge), { rot: r })]
      })],
    }),
    new TableCell({
      borders: nb(),
      width: { size: C_EIN, type: WidthType.DXA },
      margins: { top: 100, bottom: 100, left: 120, right: 120 },
      verticalAlign: VerticalAlign.TOP,
      children: [pr(tx(p.ist_optional ? '' : (p.einheit || ''), { rot: r }))],
    }),
  ];
  if (modus === 'preis') {
    cells.push(new TableCell({
      borders: nb(),
      width: { size: C_PRE, type: WidthType.DXA },
      margins: { top: 100, bottom: 100, left: 120, right: 120 },
      verticalAlign: VerticalAlign.TOP,
      children: [new Paragraph({
        alignment: AlignmentType.RIGHT,
        children: [tx(p.ist_optional ? '' : fmtC(p.einzelpreis_netto), { rot: r })]
      })],
    }));
  }
  cells.push(new TableCell({
    borders: nb(),
    width: { size: C_GES, type: WidthType.DXA },
    margins: { top: 100, bottom: 100, left: 120, right: 120 },
    verticalAlign: VerticalAlign.TOP,
    children: [new Paragraph({
      alignment: AlignmentType.RIGHT,
      children: [tx(p.ist_optional ? '' : fmtC(p.zeilensumme_netto), { rot: r, bold: true })]
    })],
  }));
  return new TableRow({ children: cells });
}

// Gewerk-Row (Zwischenüberschrift, italic, über alle Spalten)
function gRow(name) {
  const cs = modus === 'preis' ? 6 : 5;
  return new TableRow({
    children: [new TableCell({
      borders: nb(),
      columnSpan: cs,
      margins: { top: 200, bottom: 80, left: 120, right: 120 },
      children: [pr(tx(name, { italic: true, size: PT10 }))],
    })],
  });
}

// Alle Positionen (regulär + optional) in eine Liste, sortiert nach position_nr wie diktiert
const allePositionen = [...regulaere_positionen, ...optionale_positionen]
  .sort((a, b) => a.position_nr - b.position_nr);

const mainRows = [hRow];
for (const g of grp(allePositionen)) {
  if (g.gewerk) mainRows.push(gRow(g.gewerk));
  for (const p of g.items) mainRows.push(dRow(p));
}
const colW = modus === 'preis'
  ? [C_POS, C_BEZ, C_MNG, C_EIN, C_PRE, C_GES]
  : [C_POS, C_BEZ, C_MNG, C_EIN, C_GES];
const mainTable = new Table({
  width: { size: CW, type: WidthType.DXA },
  columnWidths: colW,
  rows: mainRows,
});

// ── 8. Summen-Tabelle ─────────────────────────────────────────────────
function sumT(s) {
  const SL = 2800, SR = 1600;
  const sumRows = [
    ['Zwischensumme netto', fmtC(s.zwischensumme_netto), false],
    ['20% USt.', fmtC(s.ust_20), false],
    ['Rechnungsbetrag brutto', fmtC(s.endbetrag_brutto), true],
  ];

  const rows = sumRows.map(([lb, v, b], idx) => {
    const borderStyle = b
      ? { style: BorderStyle.DOUBLE, size: 6, color: '444444' }
      : { style: BorderStyle.SINGLE, size: 4, color: '888888' };
    const isLastRow = idx === sumRows.length - 1;
    return new TableRow({
      cantSplit: true,
      children: [
        new TableCell({
          borders: { ...nb(), bottom: borderStyle },
          width: { size: SL, type: WidthType.DXA },
          margins: { top: 40, bottom: 40, left: 0, right: 80 },
          children: [new Paragraph({
            spacing: { before: 0, after: 40 },
            keepNext: !isLastRow,
            keepLines: true,
            children: [tx(lb, { bold: b })]
          })],
        }),
        new TableCell({
          borders: { ...nb(), bottom: borderStyle },
          width: { size: SR, type: WidthType.DXA },
          margins: { top: 40, bottom: 40, left: 80, right: 0 },
          children: [new Paragraph({
            spacing: { before: 0, after: 40 },
            alignment: AlignmentType.RIGHT,
            keepNext: !isLastRow,
            keepLines: true,
            children: [tx(v, { bold: b })]
          })],
        }),
      ],
    });
  });

  return new Table({
    width: { size: SL + SR, type: WidthType.DXA },
    columnWidths: [SL, SR],
    alignment: AlignmentType.RIGHT,
    rows,
  });
}

const spacerBeforeSumTable = new Paragraph({
  spacing: { after: 480 },
  keepNext: true,
  keepLines: true,
  children: [tx('')],
});

// ── 9. Optionale Sektion entfällt - Positionen sind jetzt inline ──────


// ── 10. Gültigkeitssatz + Floating Footer ─────────────────────────────
const gueltigkeitsParagraph = new Paragraph({
  spacing: { before: 600, after: 0 },
  children: [tx('Unser Angebot ist 1 Monat ab Ausstellungsdatum gültig!', { size: PT9 })],
});

// Floating Footer: GAL-Bild mit absolutem Offset vom oberen Seitenrand
// = 12mm Abstand zum unteren Seitenrand (Druck-Safety)
// type: 'jpg' ist KRITISCH für Word 2019 Kompatibilität
const footerAnchorParagraph = new Paragraph({
  spacing: { before: 0, after: 0 },
  children: [
    new ImageRun({
      data: footerImgBuffer,
      type: 'jpg',
      transformation: { width: FOOTER_W, height: FOOTER_H },
      floating: {
        horizontalPosition: {
          relative: HorizontalPositionRelativeFrom.MARGIN,
          align: HorizontalPositionAlign.LEFT,
        },
        verticalPosition: {
          relative: VerticalPositionRelativeFrom.PAGE,
          offset: FOOTER_OFFSET_FROM_PAGE_TOP_EMU,
        },
        behindDocument: false,
        allowOverlap: true,
        wrap: {
          type: TextWrappingType.NONE,
          side: TextWrappingSide.BOTH_SIDES,
        },
      },
    }),
  ],
});

// ── 11. Header-Definitionen ───────────────────────────────────────────

// Seite 1: Nur GAL-Logo (first page header)
const firstPageHeader = new Header({
  children: [
    new Paragraph({
      alignment: AlignmentType.LEFT,
      spacing: { before: 0, after: 0 },
      children: [new ImageRun({
        data: headerImgBuffer,
        type: 'jpg',
        transformation: { width: HEADER_W, height: HEADER_H },
      })],
    }),
  ],
});

// Folgeseiten: Angebot Nr. links + Seite X/Y rechts
const defaultHeaderTable = new Table({
  width: { size: CW, type: WidthType.DXA },
  columnWidths: [Math.round(CW * 0.70), CW - Math.round(CW * 0.70)],
  rows: [new TableRow({
    children: [
      new TableCell({
        borders: nb(),
        width: { size: Math.round(CW * 0.70), type: WidthType.DXA },
        margins: { top: 0, bottom: 0, left: 0, right: 0 },
        verticalAlign: VerticalAlign.BOTTOM,
        children: [new Paragraph({
          spacing: { before: 0, after: 0 },
          children: [
            tx('Angebot Nr. ', { bold: true, size: PT10 }),
            tx(angebot_nr, { bold: true, size: PT10 }),
            tx(' vom ', { bold: true, size: PT10 }),
            tx(datum, { bold: true, size: PT10 }),
          ],
        })],
      }),
      new TableCell({
        borders: nb(),
        width: { size: CW - Math.round(CW * 0.70), type: WidthType.DXA },
        margins: { top: 0, bottom: 0, left: 0, right: 0 },
        verticalAlign: VerticalAlign.BOTTOM,
        children: [new Paragraph({
          spacing: { before: 0, after: 0 },
          alignment: AlignmentType.RIGHT,
          children: [
            new TextRun({ text: 'Seite ', font: FONT, size: PT9 }),
            new TextRun({ children: [PageNumber.CURRENT], font: FONT, size: PT9 }),
            new TextRun({ text: ' von ', font: FONT, size: PT9 }),
            new TextRun({ children: [PageNumber.TOTAL_PAGES], font: FONT, size: PT9 }),
          ],
        })],
      }),
    ],
  })],
});

const defaultHeader = new Header({
  children: [
    defaultHeaderTable,
    new Paragraph({
      spacing: { before: 0, after: 120 },
      children: [new TextRun({ text: '', font: FONT, size: PT9 })],
    }),
  ],
});

// ── 12. Document bauen ────────────────────────────────────────────────
const children = [
  dinSpacerParagraph,
  kundendatenTable,
  spacerAboveAngebot,
  angebotNrParagraph,
  betrifftParagraph,
  ...warnBlk(),
  mainTable,
];

if (modus === 'preis' && summen.endbetrag_brutto !== null) {
  children.push(spacerBeforeSumTable);
  children.push(sumT(summen));
}

// Optionale Positionen werden jetzt inline in der Hauptliste angezeigt
// (siehe allePositionen-Merge oben), keine separate Sektion mehr
children.push(gueltigkeitsParagraph);
children.push(footerAnchorParagraph);

const doc = new Document({
  styles: { default: { document: { run: { font: FONT, size: PT9 } } } },
  settings: { updateFields: true },
  sections: [{
    headers: {
      first: firstPageHeader,
      default: defaultHeader,
    },
    properties: {
      titlePage: true,
      page: {
        size: { width: A4_W, height: A4_H },
        margin: {
          top: MG + 400, right: MG, bottom: MG + 400, left: MG,
          header: 600, footer: 600,
        },
      },
    },
    children,
  }],
});

// ── 13. Output ────────────────────────────────────────────────────────
const buffer = await Packer.toBuffer(doc);
const filename = `Angebot_${angebot_nr}.docx`;

return [{
  json: {
    angebot_nr, datum, modus,
    position_count: regulaere_positionen.length,
    optionale_count: optionale_positionen.length,
    warnings_count: warnings.length,
    summen,
    filename,
    kunden_name: kundendaten?.firmenname
              || [kundendaten?.vorname, kundendaten?.nachname].filter(Boolean).join(' '),
    kunden_mail: kundendaten?.mail,
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      fileName: filename,
    },
  },
}];

