// ═══════════════════════════════════════════════════════════════
// Kundendaten-Parser v3.9 (freier-Angebot-Workflow)
//
// ÄNDERUNG gegenüber v3.8:
//   FIX 14: ortMatch-Regex robuster gegen trailing junk-Kommas.
//           Vorher: Lookahead stoppte nur bei Telefon/Mail oder $.
//           Bei Reihenfolgen wie "1010 Wien, UID ATU..." oder bei
//           leeren Kommas durch entfernte Felder griff der Match
//           nicht und ort blieb null.
//           Jetzt: erweiterter Stop-Lookahead - matched auch bei
//           Komma, Semikolon und allen extrahierten Marker-Wörtern.
//
//   FIX 15: Ort-Fallback aus plzBasis bei nicht erkanntem Ort.
//           Wenn der Regex versagt (Whisper-Halluzination, ungewöhn-
//           liche Reihenfolge, etc.), aber die PLZ in der plzBasis
//           eindeutig ist, wird der Ort automatisch aus plzBasis
//           gesetzt - mit Warning für Transparenz.
//
// ÄNDERUNG v3.8 → v3.9 ist nicht-destruktiv: alle bestehenden Test-
// fälle laufen identisch durch. Neu erkannt werden nur Fälle, die
// vorher zu ort=null führten.
// ═══════════════════════════════════════════════════════════════

const transkript = $input.first().json.text ?? '';
if (!transkript.trim()) {
  throw new Error('Transkript ist leer.');
}

const warnings = [];

// ─── 1. Kundendaten-Block extrahieren ────────────────────────────
const startMatch = transkript.match(/\bKundendaten[.,:;]?\s+/i);
if (!startMatch) {
  throw new Error('Kein Kundendaten-Block erkannt. Bitte Diktat mit dem Wort "Kundendaten" beginnen.');
}
const blockStart = startMatch.index + startMatch[0].length;

const endeExplizit = transkript.substring(blockStart).match(
  /\b(?:Ende\s+Kundendaten|Kundendaten[\s,.]+(?:fertig|Ende)|fertig\s+Kundendaten)[.,:;]?/i
);
const endePosition = transkript.substring(blockStart).match(/\bPos(?:ition)?\.?\s*(?:\d+|eins|ein)\b/i);

let blockEnde;
if (endeExplizit && (!endePosition || endeExplizit.index < endePosition.index)) {
  blockEnde = blockStart + endeExplizit.index;
} else if (endePosition) {
  blockEnde = blockStart + endePosition.index;
  warnings.push('"Ende Kundendaten" fehlt – Block endet automatisch bei Position 1.');
} else {
  throw new Error('Nach dem Kundendaten-Block wurde keine Position erkannt. Bitte mit "Position 1" fortfahren.');
}

const kundenBlock = transkript.substring(blockStart, blockEnde).trim();
const restTranskript = transkript.substring(endePosition
  ? blockStart + endePosition.index
  : blockEnde + (endeExplizit ? endeExplizit[0].length : 0)).trim();

// ─── 2. Buchstabiertabelle ───────────────────────────────────────
const buchstabenMap = {
  'anton':'A','ärger':'Ä','aerger':'Ä','berta':'B','bertha':'B',
  'cäsar':'C','caesar':'C','casar':'C','christine':'Ch','charlotte':'Ch',
  'dora':'D','emil':'E','friedrich':'F','fritz':'F',
  'gustav':'G','heinrich':'H','ida':'I','julius':'J','johann':'J','jakob':'J',
  'konrad':'K','kaufmann':'K','ludwig':'L','martha':'M','marta':'M',
  'nordpol':'N','norbert':'N','otto':'O',
  'österreich':'Ö','ökonom':'Ö','oe':'Ö',
  'paula':'P','peter':'P','quelle':'Q','qu':'Q','richard':'R',
  'siegfried':'S','samuel':'S','sigfried':'S','schule':'Sch',
  'theodor':'T','toni':'T','ulrich':'U',
  'übel':'Ü','übermut':'Ü','uebel':'Ü','ue':'Ü',
  'viktor':'V','victor':'V','wilhelm':'W',
  'xaver':'X','xanthippe':'X','ypsilon':'Y','ysop':'Y',
  'zeppelin':'Z','zürich':'Z','zuerich':'Z','zacharias':'Z'
};
const sonderMap = {
  'bei':'@','at':'@','punkt':'.','bindestrich':'-','minus':'-',
  'unterstrich':'_','slash':'/','schrägstrich':'/','schraegstrich':'/'
};

function levenshtein(a, b) {
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  const m = [];
  for (let i = 0; i <= b.length; i++) m[i] = [i];
  for (let j = 0; j <= a.length; j++) m[0][j] = j;
  for (let i = 1; i <= b.length; i++)
    for (let j = 1; j <= a.length; j++)
      m[i][j] = b[i-1]===a[j-1] ? m[i-1][j-1] : Math.min(m[i-1][j-1]+1, m[i][j-1]+1, m[i-1][j]+1);
  return m[b.length][a.length];
}

function fuzzyLookup(word, map) {
  const n = word.toLowerCase().replace(/[.,!?;:]/g, '').trim();
  if (map[n]) return map[n];
  if (n.length < 4) return null;
  let best = null, bestDist = 99;
  for (const k of Object.keys(map)) {
    const d = levenshtein(n, k);
    if (d < bestDist && d <= 2) { bestDist = d; best = map[k]; }
  }
  return best;
}

function resolveBuchstabierung(text, includeSonder = false) {
  const tokens = text.split(/\s+/).filter(t => t.trim());
  let result = '';
  const unresolved = [];
  for (const tok of tokens) {
    const cleaned = tok.toLowerCase().replace(/[.,!?;:]/g, '').trim();
    if (!cleaned) continue;
    const b = fuzzyLookup(cleaned, buchstabenMap);
    if (b) { result += b; continue; }
    if (includeSonder && sonderMap[cleaned]) { result += sonderMap[cleaned]; continue; }
    if (/^[a-zäöüß]$/i.test(cleaned)) { result += cleaned.toUpperCase(); continue; }
    unresolved.push(tok);
  }
  return { result, unresolved };
}

// ─── 3. NEUE MARKER ZUERST EXTRAHIEREN ──────────────────────────
let blockClean = kundenBlock.replace(/\s+/g, ' ').trim();

// FIX 1: Buchstabier-Pattern normalisieren
blockClean = blockClean.replace(
  /\b(Vorname[n]?|Nachname[n]?)[\s,.:;]+(?:\S+[\s,.:;]+)?buchstabiert\b/gi,
  '$1 buchstabiert'
);

const STOP = '(?=\\b(?:Sachbearbeiter|Sachbearbeitung|Bearbeiter|Berater|Betrifft|Betrefft|Betreff|Bezug|Thema|Baustelle|Kundennummer|Kunden-?Nr\\.?|UID|Telefon|Telefonnummer|Tel\\.?|Handy|Mobil|Mail|E-?Mail|Ende\\b)|$)';

// 3a. SACHBEARBEITER
let sachbearbeiter = null;
const sachbMatch = blockClean.match(new RegExp(`\\b(?:Sachbearbeiter|Sachbearbeitung|Bearbeiter|Berater)\\s*[:.,;]?\\s*(.+?)\\s*[,.;:]?\\s*${STOP}`, 'is'));
if (sachbMatch) {
  sachbearbeiter = sachbMatch[1].trim().replace(/[,.;:]+$/, '').trim();
  blockClean = blockClean.replace(sachbMatch[0], ' ').replace(/\s+/g, ' ').trim();
}

// 3b. BETREFF (FIX 13)
let betreff = null;
const betreffMatch = blockClean.match(new RegExp(`\\b(?:Betrifft|Betrefft|Betreff|Bezug|Thema)\\b\\s*[:.,;]?\\s*(.+?)\\s*[,.;:]?\\s*${STOP}`, 'is'));
if (betreffMatch) {
  betreff = betreffMatch[1].trim().replace(/[,.;:]+$/, '').trim();
  blockClean = blockClean.replace(betreffMatch[0], ' ').replace(/\s+/g, ' ').trim();
}

// 3c. UID
let uid = null;
const uidMatch = blockClean.match(new RegExp(`\\bUID(?:-?Nummer|-?Nr\\.?)?\\s*[:.,;]?\\s*((?:ATU|A\\s*T\\s*U|atu)\\s*\\d{8,9})`, 'i'));
if (uidMatch) {
  const digits = uidMatch[1].replace(/\D/g, '');
  if (digits.length >= 8) {
    uid = 'ATU' + digits.substring(0, 8);
  }
  blockClean = blockClean.replace(uidMatch[0], ' ').replace(/\s+/g, ' ').trim();
}

// 3d. KUNDENNUMMER
let kundennummer = null;
const kdnrMatch = blockClean.match(/\bKunden(?:nummer|-?Nr\.?)\s*[:.,;]?\s*(\d+)/i);
if (kdnrMatch) {
  kundennummer = kdnrMatch[1].trim();
  blockClean = blockClean.replace(kdnrMatch[0], ' ').replace(/\s+/g, ' ').trim();
}

// 3e. BAUSTELLE
let baustelle = null;
const bsMatch = blockClean.match(new RegExp(`\\bBaustelle\\s*[:.,;]?\\s*(.+?)\\s*[,.;:]?\\s*${STOP}`, 'is'));
if (bsMatch) {
  const bsText = bsMatch[1].trim();
  baustelle = parseBaustelle(bsText);
  blockClean = blockClean.replace(bsMatch[0], ' ').replace(/\s+/g, ' ').trim();
}

function parseBaustelle(text) {
  text = text.replace(/\b(\d{4}),\s+([A-ZÄÖÜ])/g, '$1 $2');

  const parts = text.split(/\s*,\s*/).map(p => p.trim()).filter(p => p);
  if (parts.length === 0) return null;

  let plz_ort = '', strasse = '', hinweis = '';

  for (const part of parts) {
    const plzMatch = part.match(/^\s*([1-9]\d{3})\s+(.+)$/);
    const topMatch = part.match(/^\s*(Top|Tür|Stg\.?|Stiege)\s+.+$/i);
    const strHnrMatch = part.match(/^([A-ZÄÖÜ][\wäöüß\-\s\.]+?)\s+(\d+[a-z]?(?:\s*[\/\-]\s*\d+)?)\s*$/i);

    if (plzMatch && !plz_ort) {
      plz_ort = `${plzMatch[1]} ${plzMatch[2]}`.trim();
    } else if (topMatch) {
      hinweis = hinweis ? `${hinweis}, ${part}` : part;
    } else if (strHnrMatch && !strasse) {
      strasse = part;
    } else {
      const fallbackPlz = part.match(/^\s*(\d{4})\s+/);
      if (fallbackPlz && !plz_ort) {
        plz_ort = part;
      } else if (!strasse) {
        strasse = part;
      } else {
        hinweis = hinweis ? `${hinweis}, ${part}` : part;
      }
    }
  }

  if (strasse) {
    strasse = strasse.replace(/\bstrasse\b/gi, 'straße');
    if (strasse.endsWith('Strasse')) strasse = strasse.slice(0, -7) + 'Straße';
  }

  return (plz_ort || strasse || hinweis) ? { plz_ort, strasse, hinweis } : null;
}

// ─── 4. BESTEHENDE FELD-EXTRAKTION ──────────────────────────────

// 4a. ANREDE
let anrede = null;
const anredeMatch = blockClean.match(/\b(Herr|Frau|Firma|Divers|Damen\s+und\s+Herren)\b/i);
if (anredeMatch) {
  const a = anredeMatch[1].toLowerCase();
  if (a.includes('firma')) anrede = 'Firma';
  else if (a.startsWith('herr')) anrede = 'Herr';
  else if (a.startsWith('frau')) anrede = 'Frau';
  else if (a.startsWith('divers')) anrede = 'Divers';
  else if (a.includes('damen')) anrede = 'Damen und Herren';
} else {
  warnings.push('Keine Anrede erkannt – Anrede-Zeile bleibt leer.');
}

// 4b. NAME + ADRESSE-Split
let vorname = null, nachname = null, firmenname = null;

const addrMarkerRegex = /\b(?:Adresse|wohnhaft)\b\s*[,.:;]?|\b(?:[A-ZÄÖÜ][a-zäöüß]+\s*)?(?:[Ss]traße|[Ss]trasse|[Gg]asse|[Pp]latz|[Ww]eg|[Rr]ing|[Aa]llee)\s+\d+/;
const addrMatch = blockClean.match(addrMarkerRegex);

let namePart = '', adressePart = '';
if (addrMatch) {
  const idx = addrMatch.index;
  namePart = blockClean.substring(0, idx).trim();
  adressePart = blockClean.substring(idx).trim();
} else {
  const plzSplit = blockClean.match(/\b[1-9]\d{3}\b/);
  if (plzSplit) {
    namePart = blockClean.substring(0, plzSplit.index).trim();
    adressePart = blockClean.substring(plzSplit.index).trim();
  } else {
    namePart = blockClean;
    warnings.push('Adresse nicht erkannt.');
  }
}

let nameRest = namePart.replace(/\b(Herr|Frau|Firma|Divers|Damen\s+und\s+Herren)\b/i, '').trim();

nameRest = nameRest.replace(/[,.:;\s]*\b(?:Straße|Strasse|Adresse|wohnhaft)\b[,.:;\s]*$/i, '').trim();
nameRest = nameRest.replace(/^[,.:;\s]+|[,.:;\s]+$/g, '').trim();

const vornameBuchMatch = nameRest.match(/Vorname[n]?\s+buchstabiert\s*[,.:;]?\s*(.+?)(?=\bNachname\b|$)/is);
const nachnameBuchMatch = nameRest.match(/Nachname[n]?\s+buchstabiert\s*[,.:;]?\s*(.+?)$/is);
const inlineBuchMatch = nameRest.match(/^(.+?)\s+buchstabiert\s*[,.:;]?\s*(.+)$/is);

if (vornameBuchMatch) {
  const { result, unresolved } = resolveBuchstabierung(vornameBuchMatch[1]);
  vorname = result.charAt(0).toUpperCase() + result.slice(1).toLowerCase();
  if (unresolved.length) warnings.push(`Vorname-Buchstabierung: ${unresolved.length} unauflösbar`);
  nameRest = nameRest.replace(vornameBuchMatch[0], '').trim();
}
if (nachnameBuchMatch) {
  const { result, unresolved } = resolveBuchstabierung(nachnameBuchMatch[1]);
  nachname = result.charAt(0).toUpperCase() + result.slice(1).toLowerCase();
  if (unresolved.length) warnings.push(`Nachname-Buchstabierung: ${unresolved.length} unauflösbar`);
  nameRest = nameRest.replace(nachnameBuchMatch[0], '').trim();
}

if (nachname && !vorname && nameRest) {
  const vornameParts = nameRest.replace(/[,.:;]+/g, ' ').split(/\s+/).filter(p => p && p.length > 1);
  if (vornameParts.length >= 1) {
    vorname = vornameParts[0].replace(/[,.:;]+$/, '');
  }
}

if (!vorname && !nachname) {
  if (inlineBuchMatch && !vornameBuchMatch && !nachnameBuchMatch) {
    const vorTeil = inlineBuchMatch[1].trim().replace(/[,.:;]+$/, '').trim();
    const buchTeil = inlineBuchMatch[2];
    const parts = vorTeil.split(/\s+/).filter(p => p);
    if (parts.length >= 1) {
      vorname = parts[0].replace(/[,.:;]+$/, '');
      const { result, unresolved } = resolveBuchstabierung(buchTeil);
      nachname = result.charAt(0).toUpperCase() + result.slice(1).toLowerCase();
      if (unresolved.length) warnings.push(`Nachname-Buchstabierung: ${unresolved.length} unauflösbar`);
    }
  } else {
    const parts = nameRest.replace(/[,.:;]+$/, '').split(/\s+/).filter(p => p);
    if (anrede === 'Firma') {
      firmenname = parts.join(' ').trim();
    } else if (parts.length >= 2) {
      vorname = parts[0].replace(/[,.:;]+$/, '');
      nachname = parts.slice(1).join(' ').replace(/[,.:;]+$/, '');
    } else if (parts.length === 1) {
      nachname = parts[0].replace(/[,.:;]+$/, '');
      warnings.push('Nur Nachname erkannt, kein Vorname.');
    } else {
      warnings.push('Kein Name erkannt.');
    }
  }
}

// 4c. ADRESSE
let strasse = null, hausnummer = null;
let adrClean = adressePart.replace(/^(Straße|Strasse|Adresse|wohnhaft)\b\s*[,.:;]?\s*/i, '').trim();

const strasseBuchMatch = adrClean.match(/^buchstabiert\s*[,.:;]?\s*(.+?)(?=,|$|\d{4})/is);
if (strasseBuchMatch) {
  const { result, unresolved } = resolveBuchstabierung(strasseBuchMatch[1]);
  strasse = result.charAt(0).toUpperCase() + result.slice(1).toLowerCase();
  if (unresolved.length) warnings.push(`Straße-Buchstabierung: ${unresolved.length} unauflösbar`);
  adrClean = adrClean.replace(strasseBuchMatch[0], '').trim();
}

if (!strasse) {
  const strHsnrMatch = adrClean.match(/^([A-ZÄÖÜ][\wäöüß\-\s]+?)\s+(\d+[a-z]?(?:\s*[\/\-]\s*\d+)?)\b/i);
  if (strHsnrMatch) {
    strasse = strHsnrMatch[1].trim().replace(/[,.:;]+$/, '');
    hausnummer = strHsnrMatch[2].trim();
  } else {
    const hsnrOnly = adrClean.match(/\b(\d+[a-z]?)\b/);
    if (hsnrOnly) {
      hausnummer = hsnrOnly[1];
      strasse = adrClean.substring(0, hsnrOnly.index).trim().replace(/[,.:;]+$/, '');
    }
  }
}

if (strasse && !hausnummer) {
  const hnMatch = adrClean.match(/\bHausnummer\s+(\d+[a-z]?)\b/i) || adrClean.match(/\b(\d+[a-z]?)\b/);
  if (hnMatch) hausnummer = hnMatch[1];
}

if (strasse) {
  strasse = strasse.replace(/-(gasse|straße|strasse|platz|weg|ring|allee)\b/gi, '$1');
  strasse = strasse.replace(/strasse\b/gi, 'straße');
  if (strasse.endsWith('Strasse')) strasse = strasse.slice(0, -7) + 'Straße';
}

// 4d. PLZ + ORT (FIX 14: robusterer Lookahead)
let plz = null, ort = null;
let plzOrtSearch = adressePart;
if (strasse && hausnummer) {
  const toRemove = `${strasse} ${hausnummer}`;
  const idx = plzOrtSearch.indexOf(toRemove);
  if (idx >= 0) plzOrtSearch = plzOrtSearch.substring(idx + toRemove.length);
}

const plzMatch = plzOrtSearch.match(/\b([1-9]\d{3})\b/);
if (plzMatch) {
  plz = plzMatch[1];
  const afterPlz = plzOrtSearch.substring(plzMatch.index + 4);
  // FIX 14: erweiterter Stop-Lookahead - matched auch bei Komma,
  // Semikolon, Whitespace+Marker-Wort oder Stringende. Damit greift
  // der Match auch wenn nach dem Ort trailing junk-Kommas stehen
  // (entstehen weil vorher extrahierte Felder ihre umschließenden
  // Kommas hinterlassen haben) oder eine ungewöhnliche Reihenfolge
  // verwendet wurde (z.B. "Wien, UID ATU..." statt "Wien, Telefon...").
  const ortMatch = afterPlz.match(
    /^[\s,.:;]*([A-ZÄÖÜ][\wäöüß\-\s\.]+?)(?=[,;:]|\s+(?:Telefon|Telefonnummer|Tel\.?|Handy|Mobil|Mail|E-?Mail|Kundennummer|Kunden-?Nr\.?|UID|Sachbearbeiter|Sachbearbeitung|Bearbeiter|Berater|Betrifft|Betrefft|Betreff|Bezug|Thema|Baustelle|Ende)\b|\s*$)/i
  );
  if (ortMatch) {
    ort = ortMatch[1].trim().replace(/[,.:;\s]+$/, '');
    if (/buchstabiert/i.test(ort)) {
      const ortBuchMatch = ort.match(/buchstabiert\s*[,.:;]?\s*(.+)$/is);
      if (ortBuchMatch) {
        const { result } = resolveBuchstabierung(ortBuchMatch[1]);
        ort = result.charAt(0).toUpperCase() + result.slice(1).toLowerCase();
      }
    }
  }
}

// 4e. TELEFON
let telefon = null;
const telMatch = blockClean.match(/\b(?:Telefon(?:nummer)?|Tel\.?|Handy|Mobil(?:nummer)?)\s*[:.,;]?\s*([+\d\s\-\/\(\)]+?)(?=[\s,.;:]*(?:Mail|E-?Mail|$)|[,.;:]\s*(?:Mail|E-?Mail))/i);
if (telMatch) {
  let digits = telMatch[1].trim().replace(/[^\d+]/g, '');

  if (digits.startsWith('+36') || digits.startsWith('0036')) {
    telefon = '+36 ' + digits.replace(/^(\+36|0036)/, '').replace(/^0/, '');
    warnings.push('Ungarische Telefonnummer erkannt.');
  } else if (digits.startsWith('+49') || digits.startsWith('0049')) {
    telefon = '+49 ' + digits.replace(/^(\+49|0049)/, '').replace(/^0/, '');
    warnings.push('Deutsche Telefonnummer erkannt.');
  } else if (digits.startsWith('+43')) {
    telefon = '+43 ' + digits.substring(3);
  } else if (digits.startsWith('0043')) {
    telefon = '+43 ' + digits.substring(4);
  } else if (digits.startsWith('0')) {
    telefon = '+43 ' + digits.substring(1);
  } else if (digits.length >= 8) {
    telefon = '+43 ' + digits;
    warnings.push('Telefon-Format unklar, AT angenommen.');
  }

  if (telefon) {
    const atMobilMatch = telefon.match(/^\+43\s*(6\d{2})(\d+)$/);
    if (atMobilMatch) {
      telefon = `+43 ${atMobilMatch[1]} ${atMobilMatch[2]}`;
    } else {
      const m = telefon.match(/^(\+\d{2})\s*(\d{2,4})(\d+)$/);
      if (m) telefon = `${m[1]} ${m[2]} ${m[3]}`;
    }
  }
}

// 4f. MAIL
let mail = null;
const mailMatch = blockClean.match(new RegExp(`\\b(?:Mail|E-?Mail)\\s*[:.,;]?\\s*(.+?)\\s*${STOP}`, 'is'));
if (mailMatch) {
  let mailRaw = mailMatch[1].trim().replace(/[.,;:]+$/, '').trim();

  let mailProcessed = mailRaw
    .replace(/\s+(?:ät|ätt|aett)\s+/gi, '@')
    .replace(/\s+bei\s+/gi, '@')
    .replace(/\s+at\s+/gi, '@')
    .replace(/\s+Punkt\s+/gi, '.')
    .replace(/\s+Bindestrich\s+/gi, '-')
    .replace(/\s+Minus\s+/gi, '-')
    .replace(/\s+Unterstrich\s+/gi, '_')
    .replace(/\s+/g, '')
    .toLowerCase();

  const umlautsBefore = mailProcessed;
  mailProcessed = mailProcessed
    .replace(/ü/g, 'ue').replace(/ö/g, 'oe').replace(/ä/g, 'ae').replace(/ß/g, 'ss');
  if (mailProcessed !== umlautsBefore) {
    warnings.push(`Mail enthielt Umlaute (${umlautsBefore}) - automatisch konvertiert zu ${mailProcessed}. Bitte prüfen.`);
  }

  function tryProviderHeuristic(s) {
    const PROVIDER_TOKENS = [
      'gmail.com', 'googlemail.com',
      'outlook.com', 'outlook.at', 'outlook.de',
      'hotmail.com', 'hotmail.at', 'hotmail.de',
      'yahoo.com', 'yahoo.de', 'yahoo.at',
      'icloud.com', 'me.com', 'mac.com',
      'live.com', 'live.de', 'live.at',
      'msn.com', 'msn.de',
      'gmx.at', 'gmx.de', 'gmx.net', 'gmx.com',
      'web.de', 't-online.de', 'freenet.de', 'arcor.de',
      'aon.at', 'chello.at', 'kabsi.at', 'inode.at', 'utanet.at',
      'a1.net', 'magenta.at', 'drei.at',
      'gmail', 'gmx', 'yahoo', 'hotmail', 'outlook', 'live', 'msn',
      'icloud', 'web.', 't-online', 'aon.', 'a1.'
    ];
    const lower = s.toLowerCase();
    for (const tok of PROVIDER_TOKENS) {
      const idx = lower.indexOf(tok);
      if (idx > 2) {
        const before = lower.substring(0, idx);
        const beforeClean = before.replace(/[,.\s_\-]+$/, '');
        if (beforeClean.endsWith('at')) {
          const userPart = beforeClean.substring(0, beforeClean.length - 2)
            .replace(/[._\-,\s]+$/, '');
          if (userPart.length >= 2) {
            const afterToken = s.substring(idx);
            const domainMatch = afterToken.match(/^([a-z0-9.\-]+)/i);
            const domain = domainMatch ? domainMatch[1].replace(/[.\-]+$/, '') : afterToken;
            return userPart + '@' + domain;
          }
        }
      }
    }
    return null;
  }

  if (/buchstabiert/i.test(mailRaw)) {
    const mailBuchMatch = mailRaw.match(/buchstabiert\s*[,.:;]?\s*(.+)$/is);
    if (mailBuchMatch) {
      const { result, unresolved } = resolveBuchstabierung(mailBuchMatch[1], true);
      mail = result.toLowerCase();
      if (unresolved.length) warnings.push(`Mail-Buchstabierung: ${unresolved.length} unauflösbar`);
    }
  } else {
    const directMatch = mailProcessed.match(/([a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,})/i);
    if (directMatch) {
      mail = directMatch[1].toLowerCase();
    } else {
      const providerGuess = tryProviderHeuristic(mailProcessed);
      if (providerGuess && /^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/i.test(providerGuess)) {
        mail = providerGuess;
        warnings.push('Mail enthielt kein "ät" sondern verschmolzenes "at". Heuristisch als ' + mail + ' interpretiert – bitte prüfen!');
      } else {
        const tldRegex = /\.(at|com|net|org|de|eu|hu|ch|io|info|biz)\b/i;
        const tldMatch = mailProcessed.match(tldRegex);
        if (tldMatch) {
          const beforeTld = mailProcessed.substring(0, tldMatch.index);
          const tld = tldMatch[1];
          const parts = beforeTld.split('.');
          if (parts.length >= 3) {
            const domain = parts[parts.length - 1];
            const user = parts.slice(0, -1).join('.');
            mail = `${user}@${domain}.${tld}`.toLowerCase();
            warnings.push('Mail enthielt kein @-Zeichen. Heuristisch als ' + mail + ' interpretiert – bitte prüfen!');
          } else if (parts.length === 2) {
            mail = `${parts[0]}@${parts[1]}.${tld}`.toLowerCase();
            warnings.push('Mail enthielt kein @-Zeichen. Heuristisch als ' + mail + ' interpretiert – bitte prüfen!');
          } else {
            mail = mailRaw.toLowerCase();
            warnings.push('Mail-Format konnte nicht interpretiert werden – bitte prüfen.');
          }
        } else {
          mail = mailRaw.toLowerCase();
          warnings.push('Mail-Format unklar.');
        }
      }
    }
  }

  if (mail && !/^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/i.test(mail)) {
    warnings.push('Mail entspricht nicht dem Standard-Format – bitte im Preview prüfen.');
  }
}

