  '7072':'Mörbisch am See','7081':'Schützen am Gebirge','7082':'Donnerskirchen','7083':'Purbach am Neusiedler See','7091':'Breitenbrunn am Neusiedler See',
  '7092':'Winden am See','7093':'Jois','7100':'Neusiedl am See','7111':'Parndorf','7121':'Weiden am See',
  '7122':'Gols','7123':'Mönchhof','7131':'Halbturn','7132':'Frauenkirchen','7141':'Podersdorf am See',
  '7142':'Illmitz','7143':'Apetlon','7151':'Wallern im Burgenland','7152':'Pamhagen','7161':'Sankt Andrä am Zicksee',
  '7162':'Tadten','7163':'Andau','7201':'Neudörfl','7202':'Bad Sauerbrunn','7203':'Wiesen',
  '7210':'Mattersburg','7212':'Forchtenstein','7221':'Marz','7222':'Rohrbach bei Mattersburg','7223':'Sieggraben',
  '7421':'Pinggau','8694':'Neuberg an der Mürz'
};

let plzOrtKonsistent = null;
if (plz) {
  const expected = plzBasis[plz];
  if (expected) {
    function normalizeOrt(s) {
      return s.toLowerCase().trim()
        .replace(/ß/g, 'ss')
        .replace(/ü/g, 'u').replace(/ö/g, 'o').replace(/ä/g, 'a')
        .replace(/[\-_]/g, ' ')
        .replace(/\s+/g, ' ')
        .replace(/[.,;:]/g, '')
        .trim();
    }
    if (!ort) {
      // FIX 15: Ort wurde nicht erkannt, aber PLZ ist eindeutig in plzBasis
      // → automatisch setzen. Whisper-Hörfehler oder Regex-Fail werden
      // damit gefangen, ohne dass der User korrigieren muss.
      ort = expected;
      warnings.push(`Ort "${expected}" aus PLZ ${plz} ergänzt (im Diktat nicht eindeutig erkannt).`);
      plzOrtKonsistent = true;
    } else {
      // FIX 11/12: Tolerante Konsistenz-Prüfung + Auto-Korrektur
      const oN = normalizeOrt(ort);
      const eN = normalizeOrt(expected);
      const matched = oN === eN || oN.includes(eN) || eN.includes(oN);
      if (!matched) {
        warnings.push(`Ort "${ort}" zu "${expected}" korrigiert (PLZ ${plz} ist eindeutig in der Postleitzahlen-Datenbank).`);
        ort = expected;
      }
      plzOrtKonsistent = true;
    }
  } else {
    // PLZ nicht in der Basis → außerhalb Einsatzgebiet, kein Check möglich
    plzOrtKonsistent = true;
  }
}

// ─── 8. Output ──────────────────────────────────────────────────
const kundendaten = {
  anrede, vorname, nachname, firmenname,
  strasse, hausnummer, plz, ort, telefon, mail,
  kundennummer, uid,
  baustelle,
  betreff,
  sachbearbeiter,
  ist_sanierung,
  plz_ort_konsistent: plzOrtKonsistent,
  warnings, pflichtfehler
};

return [{
  json: {
    kundendaten,
    rest_transkript: restTranskript,
    original_transkript: transkript
  }
}];

// ═══════════════════════════════════════════════════════════════
// Position-Parser v3 (ROBUST + ECHTE HEADER-ERKENNUNG)
//
// Änderungen ggü. v2:
// - Gewerke-Map bereinigt (Demontage/Bau/Parkett entfernt - waren Tätigkeiten)
// - Nur "-arbeiten"-Begriffe und eindeutige Gewerke-Namen bleiben
// - Header-Erkennung strikt: Gewerk muss ALS EIGENSTÄNDIGER BLOCK
//   direkt vor "Position X" stehen
// ═══════════════════════════════════════════════════════════════

const transkript = $input.first().json.text ?? '';
const kundendaten = $input.first().json.kundendaten;

if (!transkript.trim()) {
  throw new Error('Rest-Transkript (Positionen) ist leer.');
}

// ─── Zahlwort → Zahl ────────────────────────────────────────────
const zahlwortMap = {
  'eins':1,'ein':1,'zwei':2,'drei':3,'vier':4,'fünf':5,'fuenf':5,
  'sechs':6,'sieben':7,'acht':8,'neun':9,'zehn':10,
  'elf':11,'zwölf':12,'zwoelf':12,'dreizehn':13,'vierzehn':14,
  'fünfzehn':15,'fuenfzehn':15,'sechzehn':16,'siebzehn':17,
  'achtzehn':18,'neunzehn':19,'zwanzig':20,
  'einundzwanzig':21,'zweiundzwanzig':22,'dreiundzwanzig':23,
  'vierundzwanzig':24,'fünfundzwanzig':25,'fuenfundzwanzig':25,
  'sechsundzwanzig':26,'siebenundzwanzig':27,'achtundzwanzig':28,
  'neunundzwanzig':29,'dreißig':30,'dreissig':30
};

function parsePositionNr(raw) {
  const c = raw.toLowerCase().trim();
  if (/^\d+$/.test(c)) return parseInt(c, 10);
  if (zahlwortMap[c] !== undefined) return zahlwortMap[c];
  return null;
}

// ─── BEREINIGTE Gewerke-Map (v3) ────────────────────────────────
// Nur echte Gewerke-Headers, KEINE Tätigkeiten wie Demontage/Abbruch
const gewerkeMap = {
  // Elektro
  'elektrikerarbeiten': 'Elektrikerarbeiten',
  'elektroarbeiten': 'Elektrikerarbeiten',
  'elektrik': 'Elektrikerarbeiten',
  'elektro': 'Elektrikerarbeiten',
  // Sanitär
  'sanitärinstallationen': 'Sanitärinstallationen',
  'sanitär': 'Sanitärinstallationen',
  'sanitaer': 'Sanitärinstallationen',
  'installateurarbeiten': 'Sanitärinstallationen',
  // Fliesen
  'fliesenlegerarbeiten': 'Fliesenlegerarbeiten',
  'fliesenleger': 'Fliesenlegerarbeiten',
  // Maler
  'malerarbeiten': 'Malerarbeiten',
  'anstreicharbeiten': 'Anstreicharbeiten',
  // Tischler, Boden
  'tischlerarbeiten': 'Tischlerarbeiten',
  'bodenlegerarbeiten': 'Bodenlegerarbeiten',
  // Abbruch (echtes Gewerk wenn so benannt)
  'abbrucharbeiten': 'Abbrucharbeiten',
  // Bau
  'bauarbeiten': 'Bauarbeiten',
  // Reinigung
  'reinigungsarbeiten': 'Reinigung',
  'endreinigung': 'Reinigung',
  // Sonstiges
  'diverse arbeiten': 'diverse Arbeiten'
};

// ─── Position-Regex (unverändert von v2) ────────────────────────
const zwAlt = Object.keys(zahlwortMap).join('|');
const positionRegex = new RegExp(
  `\\b(?:Position|Pos\\.?)\\s+(\\d+|${zwAlt})\\b(?:\\s*[,.:\\s]*\\s*(optional))?`,
  'gi'
);

const matches = [];
let m;
while ((m = positionRegex.exec(transkript)) !== null) {
  const pn = parsePositionNr(m[1]);
  if (pn === null) continue;
  matches.push({
    position_nr: pn,
    ist_optional: !!m[2],
    match_start: m.index,
    match_end: m.index + m[0].length,
    match_text: m[0]
  });
}

if (matches.length === 0) {
  const preview = transkript.substring(0, 200);
  throw new Error(
    'Keine Positionen erkannt.\n\n' +
    'TRANSKRIPT (erste 200 Zeichen):\n"' + preview + '"\n\n' +
    'Tipp: Sage "Position 1" oder "Position eins" zu Beginn jeder Leistungsbeschreibung.'
  );
}

// ─── Gewerk-Header-Erkennung (STRIKT) ───────────────────────────
// Regel: Ein Gewerk wird nur dann erkannt, wenn es UNMITTELBAR vor
// der Position als eigenständiger Block steht.
// Konkret: Zwischen dem Gewerk-Wort und "Position X" darf nichts
// außer Satztrennern (. , ; :) und Whitespace stehen.
//
// ERKENNEN:
//   "Elektrikerarbeiten. Position 1, ..."        ✓
//   "Elektrikerarbeiten, Position 1, ..."        ✓
//   "Sanitärinstallationen Position 3, ..."      ✓ (nur Whitespace dazwischen)
//
// NICHT ERKENNEN:
//   "Position 1, Demontage..."                   ✗ (keine Gewerke im Rohtext)
//   "... alten Installation. Position 2, ..."    ✗ (Position 2 gehört zur neuen)
//   "... Fliesen verlegen. Position 3, ..."      ✗ (Fliesen war Tätigkeit)

function findGewerkHeader(textBeforePosition) {
  // Nur die letzten ~80 Zeichen vor der Position anschauen
  const zone = textBeforePosition.substring(Math.max(0, textBeforePosition.length - 80));
  // Whisper trennt Komposita oft ("Elektrikerarbeiten" -> "Elektriker arbeiten").
  const zoneCompact = zone.replace(/\s+/g, '');

  // Strikte Pattern: <Gewerk-Wort> gefolgt NUR von Satztrennern/Whitespace bis zum Ende
  const sorted = Object.keys(gewerkeMap).sort((a,b) => b.length - a.length);

  for (const key of sorted) {
    // Pattern: Wortgrenze + Gewerk + [Satztrenner/Whitespace]* + Ende der zone
    const escapedKey = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const headerRegex = new RegExp(`\\b${escapedKey}\\s*[,.;:]?\\s*$`, 'i');
    // Fallback gegen leerzeichenfreie Variante (Whisper-Worttrennung)
    const compactRegex = new RegExp(`(?:^|[\\s.,;:])${escapedKey}[.,;:]?$`, 'i');
    if (headerRegex.test(zone) || compactRegex.test(zoneCompact)) {
      return gewerkeMap[key];
    }
  }
  return null;
}

// ─── Helfer: nachfolgendes Gewerk-Wort am Ende des Rohtexts abschneiden ──
// Der Rohtext reicht bis zur nächsten "Position X"; direkt davor steht oft
// das Gewerk-Wort der NÄCHSTEN Position (z.B. "...25 Quadratmeter. Elektriker
// arbeiten"). Das verwirrt die LLM -> hier entfernen. Tolerant gegen Whisper-
// Worttrennung ("Elektriker arbeiten" == "elektrikerarbeiten").
function stripTrailingGewerk(text) {
  if (!text) return text;
  let t = text.replace(/[\s.,;:]+$/, '');
  const keys = Object.keys(gewerkeMap);
  for (let n = 2; n >= 1; n--) {
    const words = t.trim().split(/\s+/);
    if (words.length <= n) continue;
    const compact = words.slice(words.length - n).join('').replace(/[.,;:]+$/, '').toLowerCase();
    if (keys.includes(compact)) {
      const head = words.slice(0, words.length - n).join(' ');
      return head.replace(/[\s.,;:]+$/, '').trim();
    }
  }
  return t.trim();
}

// ─── Positionen aufbauen ────────────────────────────────────────
const positions = [];
const warnings = [];
let currentGewerk = null;

for (let i = 0; i < matches.length; i++) {
  const mm = matches[i];
  const nextStart = (i+1 < matches.length) ? matches[i+1].match_start : transkript.length;
  const rohtextRaw = transkript.substring(mm.match_end, nextStart).trim().replace(/^[,.:;\s]+/, '');
  const rohtext = stripTrailingGewerk(rohtextRaw);

  // Text VOR dieser Position: entweder bis Anfang Transkript oder bis Ende der vorherigen Position
  const startContext = (i === 0) ? 0 : matches[i-1].match_end;
  const kontext = transkript.substring(startContext, mm.match_start);

  const neuesGewerk = findGewerkHeader(kontext);
  if (neuesGewerk) currentGewerk = neuesGewerk;

  positions.push({
    position_nr: mm.position_nr,
    ist_optional: mm.ist_optional,
    gewerk: currentGewerk,
    rohtext
  });
}

// ─── Lücken/Doppelungen checken ─────────────────────────────────
const reg = positions.filter(p => !p.ist_optional).map(p => p.position_nr).sort((a,b) => a-b);
const opt = positions.filter(p => p.ist_optional).map(p => p.position_nr).sort((a,b) => a-b);

function checkSeq(arr, lbl) {
  if (!arr.length) return;
  const min = Math.min(...arr), max = Math.max(...arr);
  const expected = [];
  for (let i=min; i<=max; i++) expected.push(i);
  const fehlend = expected.filter(x => !arr.includes(x));
  if (fehlend.length) warnings.push(`Lücke in ${lbl}: ${fehlend.join(', ')}`);
  const dop = arr.filter((x,i,a) => a.indexOf(x) !== i);
  if (dop.length) warnings.push(`Doppelt ${lbl}: ${[...new Set(dop)].join(', ')}`);
}
checkSeq(reg, 'reguläre');
checkSeq(opt, 'optionale');

return [{
  json: {
    position_count: positions.length,
    positions,
    warnings,
    kundendaten
  }
}];

// ═══════════════════════════════════════════════════════════════
// Korrektur-Parser1 v4 (Erst-Diktat-Pfad)
//
// CHANGELOG ggü. v3:
//   FIX 1: FELD_ALIASE um 'anrede', 'titel', 'ansprache' erweitert.
//          Vorher: Korrektur der Anrede war unmöglich, weil 'anrede'
//          nicht in der Allowlist stand → Fehler "anrede ist kein
//          bekanntes Feld".
//   FIX 2: Switch-Block bekommt `case 'anrede'` mit deterministischem
//          Mapping (Herr/Frau/Firma/Divers/Damen und Herren). Whisper-
//          tolerante Match-Logik via includes().
//   FIX 3: buildHilfeNachricht() listet Anrede in den möglichen Feldern
//          auf und zeigt erlaubte Werte. Verhindert Trial-and-Error.
//
// UNVERÄNDERT:
//   - Betreff/Bearbeiter/Baustelle/PLZ/Ort/Mail/Telefon/UID/Kundennr
//     waren bereits in v3 korrekt implementiert.
//   - VERBOTENE_FELDER (adresse/anschrift/kunde/kontakt) bleibt strict.
//   - Multi-Feld-Splitting-Logik unverändert (Komma-aware bei Baustelle).
//   - Buchstabier-Auflösung für freitext-Felder unverändert.
// ═══════════════════════════════════════════════════════════════

const { correction_text, session, chat_id, bot_token } = $input.first().json;

// ─── Liste aller unterstützten Felder ───────────────────────────
const FELD_ALIASE = {
  // NEU in v4: Anrede mit Aliasen
  'anrede': 'anrede', 'titel': 'anrede', 'ansprache': 'anrede',

  // Name
  'vorname': 'vorname',
  'nachname': 'nachname',
  'firma': 'firma', 'firmenname': 'firma',

  // Adresse
  'straße': 'strasse', 'strasse': 'strasse',
  'hausnummer': 'hausnummer', 'hausnr': 'hausnummer', 'nr': 'hausnummer',
  'plz': 'plz', 'postleitzahl': 'plz',
  'ort': 'ort', 'stadt': 'ort',

  // Kontakt
  'telefon': 'telefon', 'tel': 'telefon', 'handy': 'telefon', 'mobil': 'telefon',
  'mail': 'mail', 'email': 'mail', 'e-mail': 'mail',

  // Stammdaten
  'kundennummer': 'kundennummer', 'kunden-nr': 'kundennummer', 'kundennr': 'kundennummer', 'kunden-nummer': 'kundennummer',
  'uid': 'uid', 'uid-nr': 'uid', 'uid-nummer': 'uid',

  // Projekt
  'baustelle': 'baustelle',
  'betreff': 'betreff', 'betrifft': 'betreff', 'thema': 'betreff', 'bezug': 'betreff',
  'sachbearbeiter': 'sachbearbeiter', 'sachbearbeitung': 'sachbearbeiter',
  'bearbeiter': 'sachbearbeiter', 'berater': 'sachbearbeiter'
};

// Stellt die Hilfe-Nachricht zusammen
function buildHilfeNachricht(fehlertext) {
  let msg = fehlertext + '\n\n';
  msg += '📝 *Syntax für Korrektur:*\n';
  msg += '`Korrektur: Feld1 Wert1, Feld2 Wert2, ...`\n\n';
  msg += '*Mögliche Felder:*\n';
  msg += '• Anrede (Herr / Frau / Firma / Divers)\n';   // NEU in v4
  msg += '• Vorname, Nachname, Firma\n';
  msg += '• Straße, Hausnummer, PLZ, Ort\n';
  msg += '• Telefon, Mail\n';
  msg += '• Kundennummer, UID\n';
  msg += '• Baustelle\n';
  msg += '• Betreff (oder Thema/Bezug)\n';
  msg += '• Sachbearbeiter (oder Bearbeiter/Berater)\n\n';
  msg += '*Beispiele:*\n';
  msg += '`Korrektur: Anrede Frau`\n';
  msg += '`Korrektur: Nachname Srnka`\n';
  msg += '`Korrektur: Anrede Firma, Firma Müller Bau GmbH`\n';
  msg += '`Korrektur: Straße Mariahilfer Straße, Hausnummer 45`\n';
  msg += '`Korrektur: Betreff Badsanierung, Bearbeiter Philipp Eckhardt`';
  return msg;
}

// ─── Textstart prüfen: "Korrektur:" / "Ändern:" / etc. ──────────
const startMatch = correction_text.match(/^(?:korrektur|ändern|fix|korrigieren)\s*[:,]?\s*(.+)$/is);
if (!startMatch) {
  return [{
    json: {
      action: 'correction_failed',
      chat_id,
      bot_token,
      preview_message: buildHilfeNachricht('❌ Nachricht muss mit "Korrektur:" beginnen.')
    }
  }];
}

const rest = startMatch[1].trim();

// ─── Multi-Feld-Parsing ─────────────────────────────────────────
const VERBOTENE_FELDER = {
  'adresse': 'Adresse ist kein Einzelfeld. Bitte Straße, Hausnummer, PLZ und Ort separat korrigieren.',
  'anschrift': 'Anschrift ist kein Einzelfeld. Bitte Straße, Hausnummer, PLZ und Ort separat korrigieren.',
  'kunde': 'Kunde ist kein Einzelfeld. Bitte Vorname, Nachname oder Firma separat korrigieren.',
  'kontakt': 'Kontakt ist kein Einzelfeld. Bitte Telefon oder Mail separat korrigieren.'
};

function splitKorrekturen(text) {
  const parts = text.split(/\s*,\s*/);
  const result = [];
  let current = '';

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i].trim();
    if (!part) continue;

    // Erstes Wort des Parts extrahieren
    const firstWord = part.split(/\s+/)[0].toLowerCase().replace(/[.:;]$/, '');
    const istFeldname = FELD_ALIASE.hasOwnProperty(firstWord);
    const istVerbotenesFeld = VERBOTENE_FELDER.hasOwnProperty(firstWord);

    if (istFeldname || istVerbotenesFeld) {
      // Neuer Korrektur-Teil beginnt
      if (current) result.push(current.trim());
      current = part;
    } else {
      // Gehört zum vorherigen Teil (z.B. bei Baustelle "..., Top 3")
      if (current) current += ', ' + part;
      else current = part;
    }
  }
  if (current) result.push(current.trim());
  return result;
}

const korrekturParts = splitKorrekturen(rest);

if (korrekturParts.length === 0) {
  return [{
    json: {
      action: 'correction_failed',
      chat_id,
      bot_token,
      preview_message: buildHilfeNachricht('❌ Keine Felder in der Korrektur gefunden.')
    }
  }];
}

// ─── Jeden Korrektur-Teil parsen ────────────────────────────────
const kd = { ...session.kundendaten };
const angewendet = [];
const fehler = [];

// Buchstabier-Map für "buchstabiert"-Fälle
const buchstabenMap = {
  'anton':'A','ärger':'Ä','berta':'B','cäsar':'C','christine':'Ch','dora':'D',
  'emil':'E','friedrich':'F','gustav':'G','heinrich':'H','ida':'I','julius':'J',
  'konrad':'K','ludwig':'L','martha':'M','nordpol':'N','otto':'O','österreich':'Ö',
  'paula':'P','quelle':'Q','richard':'R','siegfried':'S','theodor':'T','ulrich':'U',
  'übel':'Ü','viktor':'V','wilhelm':'W','xaver':'X','ypsilon':'Y','zeppelin':'Z',
  'zürich':'Z','zacharias':'Z','peter':'P','norbert':'N','johann':'J',
  'bei':'@','ät':'@','punkt':'.','bindestrich':'-','unterstrich':'_'
};

function resolveBuchstabierung(text) {
  const tokens = text.split(/\s+/).filter(t => t);
  let result = '';
  for (const tok of tokens) {
    const cleaned = tok.toLowerCase().replace(/[.,!?;:]/g, '');
    if (buchstabenMap[cleaned]) result += buchstabenMap[cleaned];
    else if (/^[a-zäöüß]$/i.test(cleaned)) result += cleaned.toUpperCase();
  }
  return result;
}

function parseBaustelle(text) {
  const parts = text.split(/\s*,\s*/).map(p => p.trim()).filter(p => p);
  if (parts.length === 0) return null;
  let plz_ort = '', strasse = '', hinweis = '';
  for (const part of parts) {
    const plzMatch = part.match(/^\s*([1-9]\d{3})\s+(.+)$/);
    const topMatch = part.match(/^\s*(Top|Tür|Stg\.?|Stiege)\s+.+$/i);
    const strHnrMatch = part.match(/^([A-ZÄÖÜ][\wäöüß\-\s\.]+?)\s+(\d+[a-z]?(?:\s*[\/\-]\s*\d+)?)\s*$/i);
    if (plzMatch && !plz_ort) plz_ort = `${plzMatch[1]} ${plzMatch[2]}`.trim();
    else if (topMatch) hinweis = hinweis ? `${hinweis}, ${part}` : part;
    else if (strHnrMatch && !strasse) strasse = part;
    else if (!strasse) strasse = part;
    else hinweis = hinweis ? `${hinweis}, ${part}` : part;
  }
  if (strasse) {
    strasse = strasse.replace(/\bstrasse\b/gi, 'straße');
    if (strasse.endsWith('Strasse')) strasse = strasse.slice(0, -7) + 'Straße';
  }
  return (plz_ort || strasse || hinweis) ? { plz_ort, strasse, hinweis } : null;
}

for (const part of korrekturParts) {
  // Erstes Wort = Feldname, Rest = Wert
  const match = part.match(/^(\S+)\s+(.+)$/s);
  if (!match) {
    fehler.push(`"${part}": kein Wert angegeben`);
    continue;
  }

  const feldRaw = match[1].toLowerCase().replace(/[.:;]$/, '');
  const feldCanonical = FELD_ALIASE[feldRaw];

  if (!feldCanonical) {
    if (VERBOTENE_FELDER.hasOwnProperty(feldRaw)) {
      fehler.push(VERBOTENE_FELDER[feldRaw]);
    } else {
      fehler.push(`"${feldRaw}" ist kein bekanntes Feld`);
    }
    continue;
  }

  let wert = match[2].trim().replace(/[.,]$/, '');
  const istBuchstabiert = /^buchstabiert\s+/i.test(wert);
  if (istBuchstabiert) {
    wert = wert.replace(/^buchstabiert\s+/i, '').trim();
    wert = resolveBuchstabierung(wert);
    wert = wert.charAt(0).toUpperCase() + wert.slice(1).toLowerCase();
  }

  try {
    switch (feldCanonical) {
      // ─── NEU in v4: Anrede ────────────────────────────────────
      case 'anrede': {
        const a = wert.toLowerCase().trim();
        if (a.includes('herr') && !a.includes('damen')) {
          kd.anrede = 'Herr';
        } else if (a.includes('frau')) {
          kd.anrede = 'Frau';
        } else if (a.includes('firma')) {
          kd.anrede = 'Firma';
        } else if (a.includes('divers')) {
          kd.anrede = 'Divers';
        } else if (a.includes('damen') && a.includes('herr')) {
          kd.anrede = 'Damen und Herren';
        } else {
          fehler.push(`Anrede "${wert}" nicht erkannt – erlaubt: Herr, Frau, Firma, Divers, Damen und Herren`);
          continue;
        }
        break;
      }
      case 'vorname': kd.vorname = wert; break;
      case 'nachname': kd.nachname = wert; break;
      case 'firma': kd.firmenname = wert; break;
      case 'strasse': {
        let s = wert.replace(/\bstrasse\b/gi, 'straße');
        if (s.endsWith('Strasse')) s = s.slice(0, -7) + 'Straße';
        kd.strasse = s;
        break;
      }
      case 'hausnummer': kd.hausnummer = wert.replace(/[^0-9a-z\/\-]/gi, ''); break;
      case 'plz': {
        const digits = wert.replace(/\D/g, '').substring(0, 4);
        if (digits.length !== 4 || !/^[1-9]/.test(digits)) {
          fehler.push(`PLZ "${wert}" ist kein gültiger 4-stelliger AT-Postleitzahl-Format`);
          continue;
        }
        kd.plz = digits;
        break;
      }
      case 'ort': kd.ort = wert; break;
      case 'telefon': {
        const digits = wert.replace(/\D/g, '');
        let tel;
        if (digits.startsWith('43')) tel = '+43 ' + digits.substring(2);
        else if (digits.startsWith('0')) tel = '+43 ' + digits.substring(1);
        else tel = '+43 ' + digits;
        const m = tel.match(/^\+43\s*(6\d{2})(\d+)$/);
        if (m) tel = `+43 ${m[1]} ${m[2]}`;
        kd.telefon = tel;
        break;
      }
      case 'mail': {
        let m = wert.toLowerCase()
          .replace(/\s+(?:ät|ätt|aett)\s+/gi, '@')
          .replace(/\s+bei\s+/gi, '@')
          .replace(/\s+at\s+/gi, '@')
          .replace(/\s+punkt\s+/gi, '.')
          .replace(/\s+/g, '');
        m = m.replace(/ü/g, 'ue').replace(/ö/g, 'oe').replace(/ä/g, 'ae').replace(/ß/g, 'ss');
        kd.mail = m;
        break;
      }
      case 'kundennummer': kd.kundennummer = wert.replace(/\D/g, ''); break;
      case 'uid': {
        const digits = wert.replace(/\D/g, '');
        if (digits.length < 8) {
          fehler.push(`UID "${wert}" hat zu wenige Ziffern (${digits.length} statt 8)`);
          continue;
        }
        kd.uid = 'ATU' + digits.substring(0, 8);
        break;
      }
      case 'baustelle': {
        const bs = parseBaustelle(wert);
        if (!bs) {
          fehler.push(`Baustelle "${wert}" konnte nicht geparst werden`);
          continue;
        }
        kd.baustelle = bs;
        break;
      }
      case 'betreff': kd.betreff = wert; break;
      case 'sachbearbeiter': kd.sachbearbeiter = wert; break;
    }
    angewendet.push({ feld: feldCanonical, wert: typeof wert === 'object' ? JSON.stringify(wert) : wert });
  } catch (e) {
    fehler.push(`${feldCanonical}: Fehler beim Setzen (${e.message})`);
  }
}

// ─── Pflichtfeld-Check neu berechnen ────────────────────────────
kd.pflichtfehler = [];
if (!kd.firmenname && (!kd.vorname || !kd.nachname)) kd.pflichtfehler.push('Name');
if (!kd.strasse) kd.pflichtfehler.push('Straße');
if (!kd.plz) kd.pflichtfehler.push('PLZ');
if (!kd.ort) kd.pflichtfehler.push('Ort');
if (!kd.telefon) kd.pflichtfehler.push('Telefon');
if (!kd.mail) kd.pflichtfehler.push('Mail');
kd.warnings = kd.pflichtfehler.length > 0
  ? ['Pflichtfelder fehlen: ' + kd.pflichtfehler.join(', ')]
  : [];

// ─── Rückgabe ───────────────────────────────────────────────────
if (angewendet.length === 0) {
  return [{
    json: {
      action: 'correction_failed',
      chat_id,
      bot_token,
      preview_message: buildHilfeNachricht('❌ Keine Korrekturen übernommen:\n' + fehler.map(f => '• ' + f).join('\n'))
    }
  }];
}

return [{
  json: {
    action: 'correction_applied',
    chat_id,
    bot_token,
    kundendaten: kd,
    rest_transkript: session.rest_transkript,
    original_transkript: session.original_transkript,
    angewendet,
    fehler,
    korrektur_feld: angewendet.map(a => a.feld).join(', '),
    korrektur_wert: angewendet.map(a => a.wert).join(' / ')
  }
}];

// ═══════════════════════════════════════════════════════════════
// Korrektur-Preview v5 (nur OK-Button)
//
// ÄNDERUNG ggü. v4:
//   reply_markup enthält jetzt NUR den OK-Button.
//   Korrektur und Neu diktieren entfernt — beide erfordern eh ein
//   Text-Diktat/Text-Eingabe, der Button-Klick allein hätte zu
//   einer Fehlermeldung geführt.
//
// CHANGELOG ggü. v3 (aus v4, unverändert):
//   - Erkennt Fehler-Items (action === 'correction_failed') und gibt
//     diese unverändert durch (mit OK-Button)
//   - Multi-Feld-Korrekturen: zeigt alle angewendeten Änderungen
//   - Zeigt bei Teilerfolg die fehlgeschlagenen Felder
// ═══════════════════════════════════════════════════════════════

const data = $input.first().json;

// Inline-Keyboard wird in beiden Fällen mitgegeben
const replyMarkup = JSON.stringify({
  inline_keyboard: [
    [{ text: '✅ OK', callback_data: 'confirm' }]
  ]
});

// Fehlerfall: Item durchreichen, reply_markup ergänzen
if (data.action === 'correction_failed') {
  return [{ json: { ...data, reply_markup: replyMarkup } }];
}

// Erfolgsfall / Teilerfolg
const kd = data.kundendaten;
const angewendet = data.angewendet || [];
const fehler = data.fehler || [];

const anredeZeile = kd.anrede === 'Herr' ? 'Herrn'
                  : kd.anrede === 'Frau' ? 'Frau'
                  : kd.anrede === 'Firma' ? 'Firma'
                  : kd.anrede;

let briefkopf = '```\n' + anredeZeile + '\n';
if (kd.firmenname) briefkopf += kd.firmenname + '\n';
else briefkopf += [kd.vorname, kd.nachname].filter(Boolean).join(' ') + '\n';
briefkopf += [kd.strasse, kd.hausnummer].filter(Boolean).join(' ') + '\n';
briefkopf += [kd.plz, kd.ort].filter(Boolean).join(' ') + '\n\n';
briefkopf += (kd.telefon ? 'Tel.:   ' + kd.telefon + '\n' : '');
briefkopf += (kd.mail ? 'Mail:   ' + kd.mail + '\n' : '');
briefkopf += (kd.kundennummer ? 'Kd.-Nr.: ' + kd.kundennummer + '\n' : '');
briefkopf += (kd.uid ? 'UID:    ' + kd.uid + '\n' : '');
briefkopf += '```';

let baustellenBlock = '';
if (kd.baustelle) {
  baustellenBlock = '\n\n🏗 *Baustelle:*\n```\n';
  if (kd.baustelle.plz_ort) baustellenBlock += kd.baustelle.plz_ort + '\n';
  if (kd.baustelle.strasse) baustellenBlock += kd.baustelle.strasse + '\n';
  if (kd.baustelle.hinweis) baustellenBlock += kd.baustelle.hinweis + '\n';
  baustellenBlock += '```';
}

let metaBlock = '\n\n';
metaBlock += '📄 *Betreff:* ' + (kd.betreff || '_(wird automatisch aus Gewerken ermittelt)_') + '\n';
metaBlock += '👤 *Sachbearbeiter:* ' + (kd.sachbearbeiter || '_Ing. Ernst Baumeister (Standard)_') + '\n';

let msg = '✏️ *Korrektur angewendet:*\n';
for (const a of angewendet) {
  msg += `  • ${a.feld}: ${a.wert}\n`;
}

if (fehler.length > 0) {
  msg += '\n⚠️ *Nicht übernommen:*\n';
  for (const f of fehler) msg += '  • ' + f + '\n';
}

msg += '\n📋 *Aktueller Briefkopf:*\n\n' + briefkopf;
msg += baustellenBlock;
msg += metaBlock;

if (kd.pflichtfehler && kd.pflichtfehler.length > 0) {
  msg += '\n⚠️ *Pflichtfelder fehlen noch:* ' + kd.pflichtfehler.join(', ') + '\n';
}

msg += '\n*Antwort-Optionen:*\n';
msg += '✅ `OK` → Angebot wird erstellt\n';
msg += '✏️ `Korrektur: [Feld] [Wert], [Feld] [Wert]` → weitere Änderungen\n';
msg += '🔁 `Neu diktieren` → Abbruch';

const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${data.chat_id}`;
if (staticData[sessionKey]) {
  staticData[sessionKey].kundendaten = kd;
  staticData[sessionKey].created_at = Date.now();
}

return [{
  json: {
    chat_id: data.chat_id,
    bot_token: data.bot_token,
    preview_message: msg,
    reply_markup: replyMarkup
  }
}];

// ═══════════════════════════════════════════════════════════════
// Hole nächste Angebotsnummer aus SeaTable Counter v5
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG v5 gegenüber v4:
//   FIX 1: Referenz auf "Betreff-Apply" statt "Betreff-Generator".
//          Der Node wurde umbenannt — die alte Referenz lief in einen
//          stillen Try-Catch und fiel auf den Validator-Default zurück,
//          weshalb im DOCX immer wieder "Diverse Arbeiten" auftauchte,
//          auch wenn der LLM einen sinnvollen Betreff geliefert hatte.
//   FIX 2: Betreff-Prep als zweite Fallback-Quelle. Falls der LLM-Pfad
//          gar nicht durchlief (z.B. needs_llm=false, also direkter
//          Pfad durch den IF-Node), enthält Betreff-Prep den Original-
//          Betreff inklusive aller Validator-Felder.
//
// ÄNDERUNG v4 (unverändert übernommen):
//   - Liest validatorData via Fallback-Kaskade
//   - Whisper-Transkript-Lookup für Telegram-Pfad
//   - Counter-Update-Felder
//
// Validator-Daten-Quellen (Priorität von oben nach unten):
//   1) Betreff-Apply       → LLM-Pfad lief durch, finaler Betreff drin
//   2) Betreff-Prep        → IF-False-Pfad (needs_llm=false)
//   3) Validator + Summen  → defensiv, falls Betreff-Block fehlt
//   4) Validator + Summen 2 → defensiv, falls Aufgreifen ohne Betreff-Block
// ═══════════════════════════════════════════════════════════════

const counterRow = $input.first().json;

if (!counterRow || typeof counterRow.wert !== 'number') {
  throw new Error(
    'Counter-Zeile nicht korrekt geladen. Erwarte Feld "wert" (number). ' +
    'Erhalten: ' + JSON.stringify(counterRow)
  );
}

const aktuelleNummer = counterRow.wert;

if (aktuelleNummer < 1) {
  throw new Error(
    'Counter-Wert ist ' + aktuelleNummer + ' - das ist ungültig. ' +
    'Setze den Counter in SeaTable auf einen Wert >= 1.'
  );
}

const naechsteNummer = aktuelleNummer + 1;
const counterRowId = counterRow._id;

if (!counterRowId) {
  throw new Error(
    'Counter-Zeile hat keine _id. Stelle sicher dass im Search-Node ' +
    '"Simplify" auf OFF steht.'
  );
}

// ── Angebotsnummer mit Jahres-Präfix bauen ─────────────────────
const aktuellesJahr = new Date().getFullYear();
const angebotNrFormatiert = `${aktuellesJahr}-${aktuelleNummer}`;

// ── Validator-Daten holen (Priorität: Apply → Prep → Validator1 → Validator2) ─
let validatorData = null;
let validatorQuelle = 'none';

// 1) Betreff-Apply: LLM-Pfad ist durchgelaufen (needs_llm=true)
try {
  const ba = $('Betreff-Apply').first().json;
  if (ba && ba.angebot_nr) {
    validatorData = ba;
    validatorQuelle = 'betreff_apply';
  }
} catch (e) {
  // Betreff-Apply nicht erreichbar (IF-False-Pfad oder Node fehlt)
}

// 2) Betreff-Prep: IF-False-Pfad gewählt (Betreff war schon gesetzt)
if (!validatorData) {
  try {
    const bp = $('Betreff-Prep').first().json;
    if (bp && bp.angebot_nr) {
      validatorData = bp;
      validatorQuelle = 'betreff_prep';
    }
  } catch (e) {
    // Betreff-Prep nicht erreichbar
  }
}

// 3) Fallback: direkter Erst-Diktat-Validator (Betreff-Block deaktiviert)
if (!validatorData) {
  try {
    const v1 = $('Validator + Summen').first().json;
    if (v1 && v1.angebot_nr) {
      validatorData = v1;
      validatorQuelle = 'validator_direkt';
    }
  } catch (e) {}
}

// 4) Fallback: Aufgreifen-Validator (Betreff-Block deaktiviert)
if (!validatorData) {
  try {
    const v2 = $('Validator + Summen 2').first().json;
    if (v2 && v2.angebot_nr) {
      validatorData = v2;
      validatorQuelle = 'validator_aufgreifen';
    }
  } catch (e) {}
}

if (!validatorData) {
  throw new Error(
    'Keine Validator-Daten gefunden. Pipeline gebrochen. ' +
    'Geprüft: Betreff-Apply, Betreff-Prep, Validator + Summen, Validator + Summen 2.'
  );
}

// ── Transkript holen ───────────────────────────────────────────
let whisperTranskript = '';
let transkriptQuelle = 'none';

// Direkt-Pfad: Session → Pipeline hat das Transkript durchgereicht
try {
  const sessionData = $('Session → Pipeline').first().json;
  if (sessionData?.whisper_transkript) {
    whisperTranskript = sessionData.whisper_transkript;
    transkriptQuelle = 'session';
  }
} catch (e) {
  // Session → Pipeline nicht erreichbar (Aufgreifen-Pfad)
}

// Fallback: Whisper-Node direkt
if (!whisperTranskript) {
  try {
    const whisperData = $('Whisper Transkription').first().json;
    if (whisperData?.text) {
      whisperTranskript = whisperData.text;
      transkriptQuelle = 'whisper_direkt';
    }
  } catch (e) {
    // Whisper-Node nicht erreichbar
  }
}

if (!whisperTranskript) {
  console.warn(
    `[Nummer berechnen] Kein Transkript gefunden für Angebot ${angebotNrFormatiert}. ` +
    `Quellen geprüft: Session→Pipeline, Whisper-Node. ` +
    `SeaTable-Eintrag wird ohne Transkript erstellt.`
  );
}

return [{
  json: {
    // 1. Validator-/Betreff-Apply-Daten zuerst (enthält angebot_nr-Default,
    //    vorgaenger_*, und vor allem den final generierten betreff)
    ...validatorData,

    // 2. Counter-Felder ÜBERSCHREIBEN angebot_nr
    angebot_nr: angebotNrFormatiert,
    angebot_nr_zahl: aktuelleNummer,
    angebot_nr_jahr: aktuellesJahr,
    counter_row_id: counterRowId,
    counter_naechster_wert: naechsteNummer,

    // 3. Datum konsistent
    datum: new Date().toLocaleDateString('de-AT'),

    // 4. Transkript für SeaTable-Speicherung
    whisper_transkript: whisperTranskript,

    // 5. Debug-Info
    transkript_quelle: transkriptQuelle,
    validator_quelle: validatorQuelle
  }
}];

// ═══════════════════════════════════════════════════════════════
// Pipeline fortsetzen v2 - holt Daten von "Nummer berechnen" zurück
// ═══════════════════════════════════════════════════════════════
// Der Update-Node ersetzt die Pipeline-Daten mit der Update-Response.
// Wir holen uns die echten Workflow-Daten zurück.
//
// ÄNDERUNG v2: Bereitet 'unit_changes_addon' als formatierten String
// vor, damit der Telegram Erfolg-Knoten ihn ohne komplexe Logik
// einfügen kann. Leerer String wenn keine Einheits-Anpassungen.
// ═══════════════════════════════════════════════════════════════

const pipelineData = $('Nummer berechnen').first().json;

// Vorformatierter Telegram-Addon-Text für Einheit-Anpassungen
const unitChanges = pipelineData.unit_changes || [];
const unit_changes_addon = unitChanges.length > 0
  ? '\n\n_Einheits-Anpassungen:_\n• ' + unitChanges.join('\n• ')
  : '';

return [{
  json: {
    ...pipelineData,
    unit_changes_addon,
    counter_update_erfolgreich: true
  }
}];

// ═══════════════════════════════════════════════════════════════
// SeaTable-Felder vorbereiten v2
// ═══════════════════════════════════════════════════════════════
// Sammelt alle Daten aus dem Workflow und mapped sie auf die
// 14 SeaTable-Spalten der Tabelle "Angebote".
//
// ÄNDERUNG v2:
// - Status dynamisch: 'Finalisiert' wenn Modus 'preis', sonst 'Entwurf'
// - vorgaenger_angebotsnummer aus Validator-Daten (Aufgreifen-Pfad)
// - vorgaenger_row_id durchreichen für späteren Status-Update
// ═══════════════════════════════════════════════════════════════

const d = $input.first().json;

// ── Pflicht-Validierung ────────────────────────────────────────
if (!d.angebot_nr) {
  throw new Error('angebot_nr fehlt - Counter-Block muss vor diesem Node laufen');
}
if (!d.kundendaten) {
  throw new Error('kundendaten fehlt - Validator muss vor diesem Node laufen');
}

// ── Datum-Formatierung für SeaTable ────────────────────────────
function formatSeaTableDateTime(date) {
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const hh = String(date.getHours()).padStart(2, '0');
  const mi = String(date.getMinutes()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd} ${hh}:${mi}`;
}

function formatSeaTableDate(date) {
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

const jetzt = new Date();
const in30Tagen = new Date(jetzt.getTime() + 30 * 24 * 60 * 60 * 1000);

// ── Status-Logik ───────────────────────────────────────────────
// 'preis' = alle Pflicht-Positionen mit Preis = Angebot komplett = 'Finalisiert'
// 'leistung' = Lücken im Angebot oder reines Leistungsverzeichnis = 'Entwurf'
const status = (d.modus === 'preis') ? 'Finalisiert' : 'Entwurf';

// ── JSON-Felder als Roh-String ─────────────────────────────────
const kundendatenJson = JSON.stringify(d.kundendaten || {});

const allePositionen = [
  ...(d.regulaere_positionen || []),
  ...(d.optionale_positionen || [])
].sort((a, b) => a.position_nr - b.position_nr);
const positionenJson = JSON.stringify(allePositionen);

const baustelleJson = d.baustelle ? JSON.stringify(d.baustelle) : '';

// ── Vorgänger-Verknüpfung (nur bei Aufgreifen-Pfad) ────────────
const vorgaengerNummer = d.vorgaenger_angebotsnummer || '';

// ── SeaTable-Zeile zusammenbauen ───────────────────────────────
const seatableRow = {
  angebotsnummer: String(d.angebot_nr),
  erstelldatum: formatSeaTableDateTime(jetzt),
  status: status,
  generator_typ: 'speech_to_offer',
  kundendaten_json: kundendatenJson,
  positionen_json: positionenJson,
  betreff: d.betreff || '',
  sachbearbeiter: d.sachbearbeiter || 'Ing. Ernst Baumeister',
  baustelle_json: baustelleJson,
  hat_preise: d.modus === 'preis',
  vorgaenger_angebotsnummer: vorgaengerNummer,
  transkript: d.whisper_transkript || '',
  transkript_loeschen_am: formatSeaTableDate(in30Tagen),
  notizen: ''
};

return [{
  json: {
    seatable_row: seatableRow,
    vorgaenger_row_id: d.vorgaenger_row_id || null,  // für späteren Update
    ...d
  }
}];

// ═══════════════════════════════════════════════════════════════
// Angebot in Session speichern (Modus: awaiting_prices) v3
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG v3 gegenüber v2:
//   - Pro Position werden, sofern vorhanden, Einzelpreis und Zeilen-
//     summe in einer kursiven Detailzeile angezeigt. Pauschal wird
//     als "Pauschal X,XX €" dargestellt (keine Wiederholung).
//   - Positionen ohne Preis bekommen "(kein Preis)"-Marker, damit
//     der Baumeister auf einen Blick sieht, was er noch diktieren
//     muss.
//   - Gesamtsumme über alle bepreisten Pflicht-Positionen wird am
//     Ende ausgewiesen (netto + brutto). Bei optionalen Positionen
//     eine separate Summe.
//
// UNVERÄNDERT:
//   - Status-Wertelist auf 'Entwurf', 'Finalisiert', 'Ersetzt'
//     (passend zur SeaTable-Statusliste). 'Versendet' und 'Gelöscht'
//     bleiben geblockt.
// ═══════════════════════════════════════════════════════════════

const items = $input.all();
const router = $('Action Router').first().json;
const chat_id = router.chat_id;
const bot_token = router.bot_token;
const angebotsnummer = router.angebotsnummer;

// ─── Validierung: Angebot gefunden? ─────────────────────────────
if (!items || items.length === 0) {
  return [{
    json: {
      chat_id,
      bot_token,
      message: `❌ Angebot ${angebotsnummer} nicht gefunden.\n\nBitte prüfe die Nummer im Format YYYY-NNNNNN.`
    }
  }];
}

if (items.length > 1) {
  return [{
    json: {
      chat_id,
      bot_token,
      message: `❌ Angebot ${angebotsnummer} existiert mehrfach in SeaTable (${items.length}x). Das darf nicht sein – bitte manuell bereinigen.`
    }
  }];
}

const angebot = items[0].json;

// ─── Validierung: Status erlaubt Aufgreifen? ────────────────────
const erlaubteStati = ['Entwurf', 'Finalisiert', 'Ersetzt'];
if (angebot.status && !erlaubteStati.includes(angebot.status)) {
  return [{
    json: {
      chat_id,
      bot_token,
      message: `⚠️ Angebot ${angebotsnummer} hat Status "${angebot.status}" und kann nicht aufgegriffen werden.\n\nNur Angebote mit Status "Entwurf", "Finalisiert" oder "Ersetzt" sind erlaubt.`
    }
  }];
}

// ─── JSON-Felder zurückparsen ───────────────────────────────────
let kundendaten, positionen, baustelle;
try {
  kundendaten = angebot.kundendaten_json ? JSON.parse(angebot.kundendaten_json) : {};
  positionen = angebot.positionen_json ? JSON.parse(angebot.positionen_json) : [];
  baustelle = angebot.baustelle_json ? JSON.parse(angebot.baustelle_json) : null;
} catch (e) {
  return [{
    json: {
      chat_id,
      bot_token,
      message: `❌ JSON-Parse-Fehler beim Laden von Angebot ${angebotsnummer}: ${e.message}\n\nBitte SeaTable-Daten prüfen.`
    }
  }];
}

if (!Array.isArray(positionen) || positionen.length === 0) {
  return [{
    json: {
      chat_id,
      bot_token,
      message: `❌ Angebot ${angebotsnummer} hat keine Positionen. Aufgreifen nicht möglich.`
    }
  }];
}

// ─── Session speichern ──────────────────────────────────────────
const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
staticData[sessionKey] = {
  created_at: Date.now(),
  state: 'awaiting_prices',
  vorgaenger_angebotsnummer: angebotsnummer,
  vorgaenger_row_id: angebot._id,
  kundendaten,
  positionen,
  baustelle,
  betreff_alt: angebot.betreff || null,
  sachbearbeiter_alt: angebot.sachbearbeiter || null
};

// ─── Übersicht für Telegram-Bestätigung bauen ───────────────────
const kundenName = kundendaten.firmenname
                  || [kundendaten.vorname, kundendaten.nachname].filter(Boolean).join(' ')
                  || '(Name unbekannt)';

// Helfer: Geldformat de-AT
function fmtC(n) {
  if (n == null || typeof n !== 'number') return '';
  return new Intl.NumberFormat('de-AT', {
    minimumFractionDigits: 2, maximumFractionDigits: 2
  }).format(n) + ' €';
}

// Helfer: Mengenformat de-AT (ohne €)
function fmtM(n) {
  if (n == null || typeof n !== 'number') return '';
  return new Intl.NumberFormat('de-AT', {
    minimumFractionDigits: 0, maximumFractionDigits: 2
  }).format(n);
}

// Pro Position eine Zeile + optional kursive Detail-Subzeile
function formatPosition(p) {
  const beschreibung = p.beschreibung_normalisiert || p.rohtext || '(leer)';
  const kurz = beschreibung.length > 60 ? beschreibung.substring(0, 57) + '...' : beschreibung;
  let zeile = `${p.position_nr}. ${kurz}`;

  const mengeEinheit = (typeof p.menge === 'number' && p.einheit)
    ? `${fmtM(p.menge)} ${p.einheit}`
    : (typeof p.menge === 'number' ? fmtM(p.menge) : (p.einheit || ''));

  if (p.hat_preis && typeof p.einzelpreis_netto === 'number') {
    const einzel = fmtC(p.einzelpreis_netto);
    const gesamt = fmtC(p.zeilensumme_netto);

    if (p.einheit === 'Pauschal') {
      // Pauschal: keine Wiederholung
      zeile += `\n   _Pauschal ${gesamt}_`;
    } else if (typeof p.menge === 'number' && p.einheit) {
      // Vollformat: Menge à Einzelpreis = Gesamt
      zeile += `\n   _${fmtM(p.menge)} ${p.einheit} à ${einzel} = ${gesamt}_`;
    } else {
      // Defensiv: nur Gesamt
      zeile += `\n   _${gesamt}_`;
    }
  } else if (mengeEinheit) {
    // Ohne Preis aber mit Mengeneinheit
    zeile += `  _(${mengeEinheit}, kein Preis)_`;
  } else {
    // Ohne Preis und ohne Menge
    zeile += `  _(kein Preis)_`;
  }
  return zeile;
}

const regulaerePos = positionen.filter(p => !p.ist_optional);
const optionalePos = positionen.filter(p => p.ist_optional);

let positionenListe = '';
for (const p of regulaerePos) {
  positionenListe += formatPosition(p) + '\n';
}

if (optionalePos.length > 0) {
  positionenListe += '\n*Optionale Positionen:*\n';
  for (const p of optionalePos) {
    positionenListe += formatPosition(p) + '\n';
  }
}

// ─── Summenzeilen bauen (wenn Preise vorhanden) ─────────────────
const regMitPreis = regulaerePos.filter(p => p.hat_preis && typeof p.zeilensumme_netto === 'number');
const regOhnePreis = regulaerePos.filter(p => !p.hat_preis || typeof p.zeilensumme_netto !== 'number');
const optMitPreis = optionalePos.filter(p => p.hat_preis && typeof p.zeilensumme_netto === 'number');

let summenBlock = '';
if (regMitPreis.length > 0) {
  const summeReg = regMitPreis.reduce((a, p) => a + p.zeilensumme_netto, 0);
  const bruttoReg = Math.round(summeReg * 1.20 * 100) / 100;
  summenBlock += `\n📊 *Aktuelle Zwischensumme (Pflicht):*\n` +
                 `   Netto: ${fmtC(summeReg)}\n` +
                 `   Brutto (20% USt.): ${fmtC(bruttoReg)}\n`;
  if (regOhnePreis.length > 0) {
    summenBlock += `   _Hinweis: ${regOhnePreis.length} Pflicht-Position(en) noch ohne Preis._\n`;
  }
}
if (optMitPreis.length > 0) {
  const summeOpt = optMitPreis.reduce((a, p) => a + p.zeilensumme_netto, 0);
  summenBlock += `\n📊 *Optionale Positionen (netto):* ${fmtC(summeOpt)}\n`;
}

// ─── Nachricht zusammenbauen ────────────────────────────────────
const message = `📋 *Angebot ${angebotsnummer} geladen*\n\n` +
  `Kunde: *${kundenName}*\n` +
  `Status alt: ${angebot.status || 'unbekannt'}\n` +
  `Positionen gesamt: ${positionen.length}\n\n` +
  `${positionenListe}` +
  `${summenBlock}` +
  `\n🎤 *Bitte Preise diktieren:*\n` +
  `_Beispiel:_ "Position 1, 450 Euro pro Stück. Position 2, 1200 Euro pauschal. Position 3, 80 Euro pro Laufmeter."\n\n` +
  `_Falsche Nummer? Einfach \`/preise YYYY-NNNNNN\` mit korrekter Nummer schicken._\n` +
  `_Komplett abbrechen: \`Abbruch\` oder \`Stopp\` schicken._\n\n` +
  `Session läuft 30 Min ohne Aktion ab.`;

return [{
  json: {
    chat_id,
    bot_token,
    message
  }
}];

// ═══════════════════════════════════════════════════════════════
// Session-Status prüfen
// ═══════════════════════════════════════════════════════════════
// Liest aus static data, ob eine awaiting_prices-Session aktiv ist.
//
// Sonderfall (Implicit-Cancel): Wenn Stephan im awaiting_prices-Modus
// ein neues Diktat mit "Kundendaten..." beginnt, interpretieren wir
// das als Abbruch der Aufgreifen-Session und routen in den normalen
// Kundendaten-Parser-Pfad. Die alte awaiting_prices-Session wird
// dabei aus den static data entfernt.
// ═══════════════════════════════════════════════════════════════

const transkript = $input.first().json.text || '';
const chat_id = $('Message Router').first().json.chat_id;
const bot_token = $('Message Router').first().json.bot_token;

const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
const session = staticData[sessionKey];

let isAwaitingPrices = !!(session && session.state === 'awaiting_prices');

// Implicit-Cancel: Diktat startet mit "Kundendaten" → neuer Vorgang
if (isAwaitingPrices && /^[\s,.:;]*Kundendaten\b/i.test(transkript)) {
  isAwaitingPrices = false;
  delete staticData[sessionKey];
}

return [{
  json: {
    text: transkript,
    chat_id,
    bot_token,
    is_awaiting_prices: isAwaitingPrices,
    aufgreifen_session: isAwaitingPrices ? session : null
  }
}];

// ═══════════════════════════════════════════════════════════════
// Preis-Parser v6 (Aufgreifen-Pfad) - mit Positions-KORREKTUR
//
// NEU ggü. v5:
//   - Korrektur ohne Preis möglich: "Position 2 Menge 5",
//     "Position 1 Einheit Quadratmeter", "Position 3 Beschreibung ..."
//   - Beschreibung/Bezeichnung einer Position änderbar.
//   - Preis bleibt optional: nicht genannte Felder bleiben erhalten,
//     ein vorhandener Preis wird NICHT mehr genullt (Teil-Update).
//   - Zeilensumme wird nur neu berechnet, wenn ein Preis vorhanden ist.
//
// v5: Konnektor-Liste um Whisper-Varianten "a"/"à" erweitert.
// v4: Pattern-Familien C/A/B/D/E; Einheiten m³/Monate; Datenerhalt.
// ═══════════════════════════════════════════════════════════════

const inputData = $input.first().json;
const transkript = inputData.text || '';
const session = inputData.aufgreifen_session;

if (!transkript.trim()) {
  throw new Error('Transkript ist leer.');
}
if (!session || !Array.isArray(session.positionen) || session.positionen.length === 0) {
  throw new Error('Aufgreifen-Session fehlt oder ohne Positionen.');
}

// ─── Zahlwort → Zahl ─────────────────────────────────────────────
const zahlwortMap = {
  'eins':1,'ein':1,'eine':1,'einen':1,'einer':1,'einmal':1,
  'zwei':2,'drei':3,'vier':4,'fünf':5,'fuenf':5,
  'sechs':6,'sieben':7,'acht':8,'neun':9,'zehn':10,
  'elf':11,'zwölf':12,'zwoelf':12,'dreizehn':13,'vierzehn':14,
  'fünfzehn':15,'fuenfzehn':15,'sechzehn':16,'siebzehn':17,
  'achtzehn':18,'neunzehn':19,'zwanzig':20,
  'einundzwanzig':21,'zweiundzwanzig':22,'dreiundzwanzig':23,
  'vierundzwanzig':24,'fünfundzwanzig':25,'fuenfundzwanzig':25,
  'sechsundzwanzig':26,'siebenundzwanzig':27,'achtundzwanzig':28,
  'neunundzwanzig':29,'dreißig':30,'dreissig':30
};

function parsePositionNr(raw) {
  const c = raw.toLowerCase().trim();
  if (/^\d+$/.test(c)) return parseInt(c, 10);
  if (zahlwortMap[c] !== undefined) return zahlwortMap[c];
  return null;
}

function parseMenge(raw) {
  if (raw === null || raw === undefined) return null;
  const c = String(raw).toLowerCase().trim();
  if (/^\d+(?:[.,]\d+)?$/.test(c)) {
    return parseFloat(c.replace(',', '.'));
  }
  if (zahlwortMap[c] !== undefined) return zahlwortMap[c];
  return null;
}

function parsePreisString(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  let preis;
  if (s.includes(',')) {
    preis = parseFloat(s.replace(/\./g, '').replace(',', '.'));
  } else {
    const decimalPunktTest = s.match(/\.(\d{1,2})$/);
    if (decimalPunktTest && s.split('.').length === 2) {
      preis = parseFloat(s);
    } else {
      preis = parseFloat(s.replace(/\./g, ''));
    }
  }
  return (isNaN(preis) || preis <= 0) ? null : preis;
}

// ─── Einheit-Normalisierung ──────────────────────────────────────
const einheitMap = {
  'stück':'Stück','stueck':'Stück','stk':'Stück',
  'meter':'lfm','laufmeter':'lfm','lfm':'lfm','lm':'lfm',
  'quadratmeter':'m²','qm':'m²','m²':'m²','m2':'m²',
  'kubikmeter':'m³','kubik':'m³','m³':'m³','m3':'m³',
  'stunde':'h','stunden':'h','h':'h',
  'tag':'Tage','tage':'Tage','tagen':'Tage',
  'monat':'Monate','monate':'Monate','monaten':'Monate',
  'kg':'kg','kilo':'kg','kilogramm':'kg',
  'pauschal':'Pauschal','pauschale':'Pauschal','komplett':'Pauschal'
};

function normalizeEinheit(raw) {
  if (!raw) return null;
  const c = raw.toLowerCase().trim().replace(/[.,!?;:]/g, '');
  return einheitMap[c] || null;
}

// ─── Regex-Building ─────────────────────────────────────────────
const mengeZahlwortAlt = Object.keys(zahlwortMap).join('|');

const einheitWoerter = Object.keys(einheitMap)
  .filter(w => !['pauschal','pauschale','komplett'].includes(w))
  .sort((a, b) => b.length - a.length);
const einheitAlt = einheitWoerter.join('|');
const einheitAltMitPauschal = Object.keys(einheitMap).sort((a, b) => b.length - a.length).join('|');

const konnektorAlt = 'mit\\s+jeweils|jeweils|à\\s+je|a\\s+je|zu\\s+je|à|a';

const preisZahl = `\\d{1,3}(?:[.,]\\d{3})*(?:[.,]\\d{1,2})?|\\d+(?:[.,]\\d+)?`;
const euroToken = '(?:€|Euro\\b|EUR\\b)';

// ─── Pattern-Familien (Preis) ───────────────────────────────────
const mengeEinheitPreisRegex = new RegExp(
  `\\b(\\d+(?:[.,]\\d+)?|${mengeZahlwortAlt})[\\s,.:;]+(${einheitAlt})[\\s,.:;]+(?:${konnektorAlt})[\\s,.:;]+(${preisZahl})\\s*${euroToken}`,
  'i'
);
const pauschalPrefixRegex = new RegExp(
  `\\b(?:einmal\\s+(?:pauschal\\s+)?|pauschal\\s+)(${preisZahl})\\s*${euroToken}`,
  'i'
);
const pauschalSuffixRegex = new RegExp(
  `(${preisZahl})\\s*${euroToken}\\s*(?:pauschal|komplett)\\b`,
  'i'
);
const preisProEinheitRegex = new RegExp(
  `(${preisZahl})\\s*${euroToken}\\s*pro\\s+(${einheitAlt})\\b`,
  'i'
);
const nurPreisRegex = new RegExp(
  `(${preisZahl})\\s*${euroToken}`,
  'i'
);

function findeMengeImText(text, einheitNormalized) {
  const rohWoerter = Object.keys(einheitMap).filter(k => einheitMap[k] === einheitNormalized);
  if (rohWoerter.length === 0) return null;
  const rohAlt = rohWoerter.sort((a,b) => b.length - a.length).join('|');
  const re = new RegExp(`\\b(\\d+(?:[.,]\\d+)?|${mengeZahlwortAlt})\\s+(?:${rohAlt})\\b`, 'i');
  const m = text.match(re);
  return m ? parseMenge(m[1]) : null;
}

// ─── Position-Pattern ────────────────────────────────────────────
const zwAltPos = Object.keys(zahlwortMap).join('|');
const positionRegex = new RegExp(
  `\\bPosition\\s+(\\d+|${zwAltPos})\\b\\s*[,.:;]?\\s*([\\s\\S]+?)(?=\\bPosition\\s+(?:\\d+|${zwAltPos})\\b|$)`,
  'gi'
);

// ─── Preis aus Positionstext parsen (v5-Logik) ──────────────────
function parsePreis(innerText) {
  let m;
  m = innerText.match(mengeEinheitPreisRegex);
  if (m) return { menge: parseMenge(m[1]), einheit: normalizeEinheit(m[2]), einzelpreis_netto: parsePreisString(m[3]), pattern: 'C' };
  m = innerText.match(pauschalPrefixRegex);
  if (m) return { menge: 1, einheit: 'Pauschal', einzelpreis_netto: parsePreisString(m[1]), pattern: 'A' };
  m = innerText.match(pauschalSuffixRegex);
  if (m) return { menge: 1, einheit: 'Pauschal', einzelpreis_netto: parsePreisString(m[1]), pattern: 'B' };
  m = innerText.match(preisProEinheitRegex);
  if (m) { const einheit = normalizeEinheit(m[2]); return { menge: findeMengeImText(innerText, einheit), einheit, einzelpreis_netto: parsePreisString(m[1]), pattern: 'D' }; }
  m = innerText.match(nurPreisRegex);
  if (m) return { menge: null, einheit: null, einzelpreis_netto: parsePreisString(m[1]), pattern: 'E' };
  return null;
}

// ─── NEU: explizite Korrektur-Schlüsselwörter (ohne Preis) ──────
const mengeKwRegex = new RegExp(`\\b(?:Menge|Anzahl|St(?:ü|ue)ckzahl)\\s*[:,]?\\s*(\\d+(?:[.,]\\d+)?|${mengeZahlwortAlt})\\b`, 'i');
const einheitKwRegex = new RegExp(`\\bEinheit\\s*[:,]?\\s*(${einheitAltMitPauschal})\\b`, 'i');
const beschreibungKwRegex = /\b(?:Beschreibung|Bezeichnung|Leistungstext|Text)\s*[:,]?\s*([\s\S]+?)$/i;

function parseInhalt(innerText) {
  const preis = parsePreis(innerText);

  let menge_kw = null, einheit_kw = null, beschreibung_kw = null;
  const mM = innerText.match(mengeKwRegex);
  if (mM) menge_kw = parseMenge(mM[1]);
  const mE = innerText.match(einheitKwRegex);
  if (mE) einheit_kw = normalizeEinheit(mE[1]);
  const mB = innerText.match(beschreibungKwRegex);
  if (mB) {
    // Beschreibungstext bereinigen: ein evtl. nachgestelltes "Menge/Einheit/…-Euro"
    // bleibt drin – Empfehlung: Beschreibung als eigenes Kommando diktieren.
    beschreibung_kw = mB[1].trim().replace(/[\s,.;:]+$/, '');
    if (!beschreibung_kw) beschreibung_kw = null;
  }

  if (!preis && menge_kw === null && einheit_kw === null && beschreibung_kw === null) {
    return null;
  }
  return {
    einzelpreis_netto: preis ? preis.einzelpreis_netto : null,
    // Menge/Einheit: explizites Keyword hat Vorrang vor Preis-Muster
    menge: (menge_kw !== null) ? menge_kw : (preis ? preis.menge : null),
    einheit: einheit_kw || (preis ? preis.einheit : null),
    beschreibung: beschreibung_kw,
    pattern: preis ? preis.pattern : 'KORR'
  };
}

// ─── Diktat parsen ───────────────────────────────────────────────
const erkannteUpdates = [];
let pm;
while ((pm = positionRegex.exec(transkript)) !== null) {
  const posNr = parsePositionNr(pm[1]);
  if (posNr === null) continue;
  const innerText = pm[2].trim();
  const parsed = parseInhalt(innerText);
  if (!parsed) continue;
  erkannteUpdates.push({ position_nr: posNr, ...parsed });
}

// ─── Updates auf existierende Positionen mappen ─────────────────
// Datenerhalt: nicht erwähnte Positionen bleiben unverändert.
const positionen = JSON.parse(JSON.stringify(session.positionen));
const angewendet = [];
const fehlend = [];
const warnings = [];
const unit_changes = [];

for (const pos of positionen) {
  const update = erkannteUpdates.find(p => p.position_nr === pos.position_nr);

  if (!update) {
    if (!pos.ist_optional && !pos.hat_preis) fehlend.push(pos.position_nr);
    continue;
  }

  const mengeAlt = pos.menge;
  const einheitAlt2 = pos.einheit;
  const preisAlt = pos.einzelpreis_netto;
  const beschrAlt = pos.beschreibung_normalisiert;

  // Preis nur setzen, wenn im Update einer genannt wurde (Teil-Update!)
  if (update.einzelpreis_netto !== null && update.einzelpreis_netto !== undefined) {
    pos.einzelpreis_netto = update.einzelpreis_netto;
    pos.hat_preis = true;
  }
  if (update.menge !== null && update.menge !== undefined) {
    pos.menge = update.menge;
  }
  if (update.einheit) {
    pos.einheit = update.einheit;
  }
  if (update.beschreibung) {
    pos.beschreibung_normalisiert = update.beschreibung;
  }

  // Plausibilität nur relevant, wenn ein Preis existiert
  if (pos.hat_preis) {
    if (typeof pos.menge !== 'number' || pos.menge <= 0) {
      pos.menge = 1;
      pos.einheit = pos.einheit || 'Pauschal';
    }
    if (typeof pos.einzelpreis_netto === 'number') {
      pos.zeilensumme_netto = Math.round(pos.menge * pos.einzelpreis_netto * 100) / 100;
    }
  }

  // korrigierte Position gilt als geprüft → Warnungen zurücksetzen
  pos.hat_warnung = false;
  pos.konfidenz_hinweise = [];

  if (mengeAlt != null && mengeAlt !== pos.menge) unit_changes.push(`Pos. ${pos.position_nr}: Menge ${mengeAlt} → ${pos.menge}`);
  if (einheitAlt2 && einheitAlt2 !== pos.einheit) unit_changes.push(`Pos. ${pos.position_nr}: Einheit ${einheitAlt2} → ${pos.einheit}`);
  if (preisAlt != null && preisAlt !== pos.einzelpreis_netto) unit_changes.push(`Pos. ${pos.position_nr}: Preis ${preisAlt} → ${pos.einzelpreis_netto}`);
  if (update.beschreibung && beschrAlt !== pos.beschreibung_normalisiert) unit_changes.push(`Pos. ${pos.position_nr}: Beschreibung geändert`);

  angewendet.push(pos.position_nr);
}

// ─── Echte Warnings sammeln ─────────────────────────────────────
if (fehlend.length > 0) {
  warnings.push(`Preise fehlen für Pflicht-Positionen: ${fehlend.join(', ')}. Modus bleibt "leistung", Status bleibt "Entwurf".`);
}

const erkannteNummern = erkannteUpdates.map(p => p.position_nr);
const positionsNummern = positionen.map(p => p.position_nr);
const ueberzaehlig = erkannteNummern.filter(n => !positionsNummern.includes(n));
if (ueberzaehlig.length > 0) {
  warnings.push(`Korrekturen für nicht existierende Positionen ignoriert: ${ueberzaehlig.join(', ')}`);
}

const pflichtPositionen = positionen.filter(p => !p.ist_optional);
const allePflichtMitPreis = pflichtPositionen.length > 0 && pflichtPositionen.every(p => p.hat_preis);

return [{
  json: {
    aufgegriffen_positionen: positionen,
    angewendet,
    fehlend,
    alle_pflicht_mit_preis: allePflichtMitPreis,
    kundendaten: session.kundendaten,
    baustelle: session.baustelle,
    betreff_alt: session.betreff_alt,
    sachbearbeiter_alt: session.sachbearbeiter_alt,
    vorgaenger_angebotsnummer: session.vorgaenger_angebotsnummer,
    vorgaenger_row_id: session.vorgaenger_row_id,
    aufgreifen_warnings: warnings,
    unit_changes,
    text: transkript
  }
}];

// ═══════════════════════════════════════════════════════════════
// Validator + Summen 2 v3 (für Aufgreifen-Pfad)
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG v3 gegenüber v2:
//   FIX: Vorgänger-Betreff "Diverse Arbeiten" wird NICHT mehr blind
//   übernommen. Wenn der alte Betreff entweder leer ist ODER genau
//   "Diverse Arbeiten" lautet, gibt der Validator betreff=null zurück.
//   Damit erkennt der nachfolgende Betreff-Prep-Node das als "leer"
//   und triggert den LLM-Call, statt den Default einfach erneut
//   durchzureichen.
//   Problem vorher: Wenn das Erst-Diktat-Angebot wegen Bugs ohne
//   sinnvollen Betreff gespeichert wurde (z.B. "Diverse Arbeiten"),
//   reproduzierte sich der Fehler bei jedem Aufgreifen-Lauf.
//
// ÄNDERUNG v2 (übernommen):
//   - 'unit_changes' aus Preis-Parser durchreichen
//
// Aufgabe:
//   Positionen sind bereits strukturiert (vom Preis-Parser). Hier nur:
//   - Zeilensummen neu berechnen
//   - Gesamt-Summen + USt + Brutto
//   - Output-Schema kompatibel mit Validator + Summen 1
//   - Vorgänger-Daten durchreichen für SeaTable-Update
// ═══════════════════════════════════════════════════════════════

const data = $input.first().json;
const positionen = data.aufgegriffen_positionen;

if (!Array.isArray(positionen) || positionen.length === 0) {
  throw new Error('Keine Positionen vom Preis-Parser erhalten.');
}

const reg = positionen.filter(p => !p.ist_optional).sort((a,b) => a.position_nr - b.position_nr);
const opt = positionen.filter(p => p.ist_optional).sort((a,b) => a.position_nr - b.position_nr);

const warnings = [...(data.aufgreifen_warnings || [])];
const unit_changes = data.unit_changes || [];

// ─── Zeilensummen neu berechnen ────────────────────────────────
function zsumme(p) {
  if (p.hat_preis && typeof p.menge === 'number' && typeof p.einzelpreis_netto === 'number') {
    p.zeilensumme_netto = Math.round(p.menge * p.einzelpreis_netto * 100) / 100;
  } else {
    p.zeilensumme_netto = null;
  }
  return p;
}

const rReg = reg.map(zsumme);
const rOpt = opt.map(zsumme);

// ─── Gemischte Diktion erkennen ────────────────────────────────
const mitPreis = rReg.filter(p => p.hat_preis);
const hatPreise = mitPreis.length > 0;
const allePflichtMitPreis = mitPreis.length === rReg.length;
const gemischt = hatPreise && !allePflichtMitPreis;

if (gemischt) {
  const op = rReg.filter(p => !p.hat_preis).map(p => p.position_nr);
  warnings.push(`Gemischte Diktion: Positionen ohne Preis: ${op.join(', ')}.`);
  rReg.forEach(p => {
    if (!p.hat_preis) {
      p.hat_warnung = true;
      p.konfidenz_hinweise = (p.konfidenz_hinweise || []).concat(['Fehlender Preis']);
    }
  });
}

// ─── Summen ────────────────────────────────────────────────────
function kr(x) { return Math.round(x * 100) / 100; }

let summen = { zwischensumme_netto: null, ust_20: null, endbetrag_brutto: null };
if (allePflichtMitPreis) {
  const zs = kr(rReg.filter(p => p.hat_preis).reduce((a,p) => a + p.zeilensumme_netto, 0));
  const u = kr(zs * 0.20);
  summen = { zwischensumme_netto: zs, ust_20: u, endbetrag_brutto: kr(zs + u) };
}

const oMitP = rOpt.filter(p => p.hat_preis);
let oSum = null;
if (oMitP.length > 0) {
  const zs = kr(oMitP.reduce((a,p) => a + p.zeilensumme_netto, 0));
  const u = kr(zs * 0.20);
  oSum = { zwischensumme_netto: zs, ust_20: u, endbetrag_brutto: kr(zs + u) };
}

// ─── Modus, Datum, Default-Angebotsnummer ──────────────────────
const modus = allePflichtMitPreis ? 'preis' : 'leistung';

const now = new Date();
const angebot_nr = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}`;

// ─── Betreff aus Vorgänger-Angebot übernehmen ─────────────────
// FIX v3: "Diverse Arbeiten" als Vorgänger-Betreff wird NICHT
// übernommen, weil das ein Fallback-Default ist, kein echter
// inhaltlicher Betreff. Stattdessen null setzen, damit der
// nachfolgende Betreff-Prep den LLM neu aufruft.
const betreffAltRaw = data.betreff_alt;
const betreffAltIstDefault = !betreffAltRaw
  || (typeof betreffAltRaw === 'string' && betreffAltRaw.trim().toLowerCase() === 'diverse arbeiten');

let finaler_betreff = betreffAltIstDefault ? null : betreffAltRaw;
const finaler_sachbearbeiter = data.sachbearbeiter_alt || 'Ing. Ernst Baumeister';

return [{ json: {
  angebot_nr,
  datum: now.toLocaleDateString('de-AT'),
  modus,
  hat_gemischte_diktion: gemischt,
  hat_optionale_positionen: rOpt.length > 0,
  regulaere_positionen: rReg,
  optionale_positionen: rOpt,
  summen,
  optionale_summen: oSum,
  warnings,
  unit_changes,
  kundendaten: data.kundendaten,
  betreff: finaler_betreff,   // Kann null sein → Betreff-Prep triggert LLM
  sachbearbeiter: finaler_sachbearbeiter,
  baustelle: data.baustelle,
  vorgaenger_angebotsnummer: data.vorgaenger_angebotsnummer,
  vorgaenger_row_id: data.vorgaenger_row_id,
  ist_aufgegriffen: true
}}];

// ═══════════════════════════════════════════════════════════════
// Send-Session laden v4 (mit Diagnose bei fehlender validator_data)
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG v4: Wenn die Session zwar existiert aber keine
// validator_data hat (also angelegt von einer alten Version vor v7
// von "Send-Session anlegen1"), wirft DIESER Node den klaren Error
// statt erst DOCX neu rendern. Plus: der Error enthält den
// tatsächlichen Session-Inhalt, damit man sofort sieht welche
// Keys da sind und welche fehlen.
// ═══════════════════════════════════════════════════════════════

const input = $input.first().json || {};
const chat_id = input.chat_id;
const bot_token = input.bot_token;
const action = input.action;

if (!chat_id) {
  throw new Error(
    'Send-Session laden: chat_id fehlt im Input-Item. ' +
    'Vorgänger-Felder: ' + JSON.stringify(Object.keys(input))
  );
}

const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
const session = staticData[sessionKey];

if (!session || session.state !== 'awaiting_send_confirmation') {
  throw new Error(
    'Erwartete awaiting_send_confirmation-Session ist nicht aktiv. ' +
    'State: ' + (session ? session.state : 'keine Session') + '. ' +
    'Action: ' + action
  );
}

// NEUE Diagnose: validator_data muss da sein, sonst klarer Hinweis
if (!session.validator_data) {
  const sessionKeys = Object.keys(session);
  const angebotsnummer = session.angebotsnummer || '(unbekannt)';
  throw new Error(
    'Send-Session enthält KEIN validator_data — vermutlich wurde sie ' +
    'von einer alten Version von "Send-Session anlegen1" (vor v7) ' +
    'angelegt.\n\n' +
    'Angebotsnummer: ' + angebotsnummer + '\n' +
    'Session-Keys: ' + sessionKeys.join(', ') + '\n\n' +
    'Lösung: Stelle sicher, dass "Send-Session anlegen1" auf v7 läuft, ' +
    'und mache ein neues Diktat. Die alte Session wird beim nächsten ' +
    '"Senden"-Versuch ohnehin nicht funktionieren.'
  );
}

return [{
  json: {
    chat_id,
    bot_token,
    action,
    send_session: session,
    correction_text: input.correction_text || null
  }
}];

// ═══════════════════════════════════════════════════════════════════════════
// DOCX neu rendern v1
// ═══════════════════════════════════════════════════════════════════════════
// Re-rendert die DOCX aus den in der Send-Session gespeicherten Daten.
// Code ist fast identisch zum DOCX Generator, aber Input-Quelle ist
// session.validator_data statt direkter Pipeline-Input.
//
// Wichtig: Diese Datei MUSS den gleichen DOCX-Code enthalten wie der
// originale DOCX Generator, damit das Layout konsistent bleibt.
//
// Die Base64-Bilder (GAL Header/Footer) sind verkürzt platzhalter-mäßig
// dargestellt - du musst sie durch die echten Strings aus deinem DOCX-
// Generator-Knoten ersetzen.
// ═══════════════════════════════════════════════════════════════════════════

const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, ImageRun, AlignmentType, BorderStyle, WidthType,
  VerticalAlign, PageNumber, TabStopType,
  HorizontalPositionRelativeFrom, HorizontalPositionAlign,
  VerticalPositionRelativeFrom,
  TextWrappingType, TextWrappingSide,
} = require('docx');

// ── Input: Send-Session ───────────────────────────────────────────────
// ─── Input: Send-Session (v3 — robust gegen alle Strukturen) ────────
// Akzeptiert drei mögliche Strukturen vom Vorgänger-Node:
//   1) validator_data direkt im Top-Level (Send-Session laden v2, flach)
//   2) session.validator_data (Send-Session laden v3/v4, Wrapper)
//   3) session ohne validator_data-Wrapper (Alt-Session vor v7)
const sendData = $input.first().json;
const session = sendData.send_session;

// Validator-Daten (Positionen, Kunde, Summen):
const d =
     sendData.validator_data
  || (session && session.validator_data)
  || session
  || null;

if (!d || (!d.kundendaten && !d.regulaere_positionen)) {
  throw new Error(
    'Validator-Daten nicht gefunden. ' +
    'Top-Level-Felder: ' + Object.keys(sendData).join(', ') +
    (session ? '; Session-Keys: ' + Object.keys(session).join(', ') : '; (kein send_session-Wrapper)')
  );
}

// Metadata (mail_subject, mail_body, seatable_row_id, angebotsnummer):
// Bei flacher Struktur (Fall 1) im sendData, bei Wrapper-Struktur in session.
const meta = session || sendData;

const {
  angebot_nr, datum, modus,
  regulaere_positionen, optionale_positionen,
  summen, optionale_summen, warnings,
  hat_optionale_positionen, kundendaten
} = d;

if (!angebot_nr) throw new Error('angebot_nr fehlt in Session.');

// ── Dynamische Felder ─────────────────────────────────────────────────
const SACHBEARBEITER = d.sachbearbeiter || 'Ing. Ernst Baumeister';
const BETREFF = d.betreff || 'Diverse Arbeiten';
const KUNDENNUMMER = kundendaten?.kundennummer || '';
const KUNDEN_UID = kundendaten?.uid || '';
const BAUSTELLE_PLZ_ORT = d.baustelle?.plz_ort
  || [kundendaten?.plz, kundendaten?.ort].filter(Boolean).join(' ');
const BAUSTELLE_STRASSE = d.baustelle?.strasse
  || [kundendaten?.strasse, kundendaten?.hausnummer].filter(Boolean).join(' ');
const BAUSTELLE_HINWEIS = d.baustelle?.hinweis || '';

// ═════════════════════════════════════════════════════════════════════════
// WICHTIG: Base64-Bilder hier durch die ECHTEN Strings ersetzen
// Aus dem originalen DOCX Generator-Knoten kopieren
// ═════════════════════════════════════════════════════════════════════════
const GAL_HEADER_BASE64 = '';
const GAL_FOOTER_BASE64 = '';

const headerImgBuffer = Buffer.from(GAL_HEADER_BASE64, 'base64');
const footerImgBuffer = Buffer.from(GAL_FOOTER_BASE64, 'base64');

// ── DOCX-Konstanten ───────────────────────────────────────────────────
const FONT = 'Arial';
const PT8 = 16, PT9 = 18, PT10 = 20, PT11 = 22, PT12 = 24;
const A4_W = 11906, A4_H = 16838;
const MG = 1134;
const CW = A4_W - 2 * MG;
const C_POS = 880, C_MNG = 1020, C_EIN = 1110, C_PRE = 1350, C_GES = 1400;
const C_BEZ = modus === 'preis'
  ? (CW - C_POS - C_MNG - C_EIN - C_PRE - C_GES)
  : (CW - C_POS - C_MNG - C_EIN - C_GES);

const NONE = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
const nb = () => ({ top: NONE, bottom: NONE, left: NONE, right: NONE });
const ROT = 'CC0000';

const HEADER_W = 640, HEADER_H = 52;
const FOOTER_W = 640, FOOTER_H = 55;
const FOOTER_OFFSET_FROM_PAGE_TOP_EMU = 9736125;

// ── Helper ────────────────────────────────────────────────────────────
const tx = (t, o = {}) => new TextRun({
  text: String(t), font: FONT,
  size: o.size ?? PT9,
  bold: o.bold ?? false,
  italics: o.italic ?? false,
  color: o.rot ? ROT : undefined
});

const pr = (c, o = {}) => new Paragraph({
  spacing: { before: o.before ?? 0, after: o.after ?? 40 },
  alignment: o.align,
  border: o.border,
  children: Array.isArray(c) ? c : [c]
});

function fmtC(n) {
  if (n == null) return '';
  return new Intl.NumberFormat('de-AT', {
    minimumFractionDigits: 2, maximumFractionDigits: 2
  }).format(n) + ' €';
}

function fmtM(n) {
  if (n == null) return '';
  return new Intl.NumberFormat('de-AT', {
    minimumFractionDigits: 0, maximumFractionDigits: 2
  }).format(n);
}

// ── DIN 5008 Briefkopf ───────────────────────────────────────────────
const dinSpacerParagraph = new Paragraph({
  spacing: { before: 0, after: 1020 },
  children: [new TextRun({ text: '', font: FONT, size: 2 })],
});

const anredeZeile = kundendaten?.anrede === 'Herr' ? 'Herrn'
                  : kundendaten?.anrede === 'Frau' ? 'Frau'
                  : kundendaten?.anrede === 'Firma' ? 'Firma'
                  : (kundendaten?.anrede || '');

const nameZeile = kundendaten?.firmenname
                  || [kundendaten?.vorname, kundendaten?.nachname].filter(Boolean).join(' ');
const adrZeile1 = [kundendaten?.strasse, kundendaten?.hausnummer].filter(Boolean).join(' ');
const adrZeile2 = [kundendaten?.plz, kundendaten?.ort].filter(Boolean).join(' ');

const adressblockParagraphs = [
  new Paragraph({ spacing: { before: 0, after: 60 }, children: [tx(anredeZeile, { size: PT10 })] }),
  new Paragraph({ spacing: { before: 0, after: 60 }, children: [tx(nameZeile, { bold: true, size: PT10 })] }),
  new Paragraph({ spacing: { before: 120, after: 60 }, children: [tx(adrZeile1, { bold: true, size: PT10 })] }),
  new Paragraph({ spacing: { before: 0, after: 60 }, children: [tx(adrZeile2, { bold: true, size: PT10 })] }),
];

const rightColParagraphs = [
  new Paragraph({
    spacing: { before: 0, after: 120 },
    children: [
      tx('Sachbearbeiter: ', { bold: true, size: PT9 }),
      tx(SACHBEARBEITER, { size: PT9 }),
    ],
  }),
];

if (KUNDENNUMMER) rightColParagraphs.push(new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx('Kundennummer: ', { bold: true, size: PT9 }), tx(KUNDENNUMMER, { size: PT9 })] }));
if (KUNDEN_UID) rightColParagraphs.push(new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx('Kunden-UID-Nr.: ', { bold: true, size: PT9 }), tx(KUNDEN_UID, { size: PT9 })] }));
if (kundendaten?.mail) rightColParagraphs.push(new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx('Kunden-E-Mail: ', { bold: true, size: PT9 }), tx(kundendaten.mail, { size: PT9 })] }));
if (kundendaten?.telefon) rightColParagraphs.push(new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx('Kunden-Tel.: ', { bold: true, size: PT9 }), tx(kundendaten.telefon, { size: PT9 })] }));

rightColParagraphs.push(new Paragraph({ spacing: { before: 200, after: 40 }, children: [tx('Baustelle:', { bold: true, size: PT9 })] }));
if (BAUSTELLE_STRASSE) rightColParagraphs.push(new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx(BAUSTELLE_STRASSE, { size: PT9 })] }));
if (BAUSTELLE_PLZ_ORT) rightColParagraphs.push(new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx(BAUSTELLE_PLZ_ORT, { size: PT9 })] }));
if (BAUSTELLE_HINWEIS) rightColParagraphs.push(new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx(BAUSTELLE_HINWEIS, { bold: true, size: PT8 })] }));

const FIRST_PAGE_LEFT = Math.round(CW * 0.62);
const FIRST_PAGE_RIGHT = CW - FIRST_PAGE_LEFT;

const kundendatenTable = new Table({
  width: { size: CW, type: WidthType.DXA },
  columnWidths: [FIRST_PAGE_LEFT, FIRST_PAGE_RIGHT],
  rows: [new TableRow({
    children: [
      new TableCell({ borders: nb(), width: { size: FIRST_PAGE_LEFT, type: WidthType.DXA }, margins: { top: 0, bottom: 0, left: 0, right: 120 }, verticalAlign: VerticalAlign.TOP, children: adressblockParagraphs }),
      new TableCell({ borders: nb(), width: { size: FIRST_PAGE_RIGHT, type: WidthType.DXA }, margins: { top: 0, bottom: 0, left: 120, right: 0 }, verticalAlign: VerticalAlign.TOP, children: rightColParagraphs }),
    ],
  })],
});

const spacerAboveAngebot = new Paragraph({
  spacing: { before: 0, after: 800 },
  children: [new TextRun({ text: '', font: FONT, size: 2 })],
});

const angebotNrParagraph = new Paragraph({
  spacing: { before: 0, after: 0 },
  tabStops: [{ type: TabStopType.RIGHT, position: CW }],
  children: [
    tx('Angebot Nr. ', { bold: true, size: PT12 }),
    tx(angebot_nr, { bold: true, size: PT12 }),
    tx(' vom ', { bold: true, size: PT12 }),
    tx(datum, { bold: true, size: PT12 }),
    new TextRun({ text: '\t', font: FONT, size: PT9 }),
    new TextRun({ text: 'Seite 1', font: FONT, size: PT9 }),
  ],
});

const betrifftParagraph = new Paragraph({
  spacing: { before: 240, after: 360 },
  children: [tx('Betrifft: ', { size: PT9 }), tx(BETREFF, { size: PT9 })],
});

// ── Warnings-Block ─────────────────────────────────────────────────────
function warnBlk() {
  if (!warnings || warnings.length === 0) return [];
  const el = [
    new Paragraph({
      spacing: { before: 0, after: 120 },
      border: {
        top: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
        bottom: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
        left: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
        right: { style: BorderStyle.SINGLE, size: 8, color: 'CC0000' },
      },
      children: [tx('Hinweise zu diesem Entwurf:', { bold: true, rot: true, size: PT10 })],
    }),
  ];
  for (const w of warnings) {
    el.push(new Paragraph({ spacing: { before: 0, after: 60 }, children: [tx('• ' + w, { rot: true })] }));
  }
  el.push(new Paragraph({ spacing: { after: 240 }, children: [tx('')] }));
  return el;
}

// ── Hauptpositions-Tabelle ─────────────────────────────────────────────
const hBorder = {
  top: NONE, left: NONE, right: NONE,
  bottom: { style: BorderStyle.SINGLE, size: 6, color: '444444' }
};

const hCell = (txt, w, a) => new TableCell({
  borders: hBorder,
  width: { size: w, type: WidthType.DXA },
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  children: [new Paragraph({
    alignment: a,
    children: [new TextRun({ text: txt, bold: true, font: FONT, size: PT10 })]
  })],
});

const hCells = [
  hCell('Pos.', C_POS, AlignmentType.LEFT),
  hCell('Bezeichnung', C_BEZ, AlignmentType.LEFT),
  hCell('Menge', C_MNG, AlignmentType.RIGHT),
  hCell('Einheit', C_EIN, AlignmentType.LEFT),
];
if (modus === 'preis') hCells.push(hCell('Einzelpreis', C_PRE, AlignmentType.RIGHT));
hCells.push(hCell('Gesamt', C_GES, AlignmentType.RIGHT));

const hRow = new TableRow({ tableHeader: true, children: hCells });

function grp(list) {
  const g = [];
  let cur = { gewerk: null, items: [] };
  for (const p of list) {
    if (p.gewerk !== cur.gewerk) {
      if (cur.items.length) g.push(cur);
      cur = { gewerk: p.gewerk, items: [p] };
    } else {
      cur.items.push(p);
    }
  }
  if (cur.items.length) g.push(cur);
  return g;
}

// v2: Inline-Layout für optionale Positionen (Spec siehe DOCX Generator v17).
function buildOptionalInlineText(p) {
  if (!p.hat_preis || typeof p.einzelpreis_netto !== 'number') { if (typeof p.menge === 'number' && p.einheit) return `${fmtM(p.menge)} ${p.einheit}`; return ''; }
  const einzel = fmtC(p.einzelpreis_netto);
  const gesamt = fmtC(p.zeilensumme_netto);
  if (p.einheit === 'Pauschal') return `Pauschal ${gesamt} netto`;
  if (typeof p.menge === 'number' && p.einheit) return `${fmtM(p.menge)} ${p.einheit} à ${einzel}, gesamt: ${gesamt} netto`;
  return `${gesamt} netto`;
}

function dRow(p) {
  const r = p.hat_warnung;

  // Bezeichnungs-Spalte: bei optionalen Positionen zweiter Paragraph mit "Optional <details>"
  const bezPars = p.ist_optional
    ? (() => {
        const inline = buildOptionalInlineText(p);
        const optChildren = [
          new TextRun({ text: 'Optional', font: FONT, size: PT9, bold: true, italics: true, color: r ? ROT : undefined }),
        ];
        if (inline) {
          optChildren.push(new TextRun({ text: ' ' + inline, font: FONT, size: PT9, italics: true, color: r ? ROT : undefined }));
        }
        return [
          new Paragraph({ spacing: { before: 0, after: 0 }, children: [tx(p.beschreibung_normalisiert || '', { rot: r })] }),
          new Paragraph({ spacing: { before: 60, after: 40 }, children: optChildren }),
        ];
      })()
    : [new Paragraph({ spacing: { before: 0, after: 40 }, children: [tx(p.beschreibung_normalisiert || '', { rot: r })] })];

  const cells = [
    new TableCell({ borders: nb(), width: { size: C_POS, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP, children: [pr(tx(String(p.position_nr), { bold: true, rot: r }))] }),
    new TableCell({ borders: nb(), width: { size: C_BEZ, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP, children: bezPars }),
    new TableCell({ borders: nb(), width: { size: C_MNG, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP, children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [tx(p.ist_optional ? '' : fmtM(p.menge), { rot: r })] })] }),
    new TableCell({ borders: nb(), width: { size: C_EIN, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP, children: [pr(tx(p.ist_optional ? '' : (p.einheit || ''), { rot: r }))] }),
  ];
  if (modus === 'preis') {
    cells.push(new TableCell({ borders: nb(), width: { size: C_PRE, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP, children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [tx(p.ist_optional ? '' : fmtC(p.einzelpreis_netto), { rot: r })] })] }));
  }
  cells.push(new TableCell({ borders: nb(), width: { size: C_GES, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 120, right: 120 }, verticalAlign: VerticalAlign.TOP, children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [tx(p.ist_optional ? '' : fmtC(p.zeilensumme_netto), { rot: r, bold: true })] })] }));
  return new TableRow({ children: cells });
}

function gRow(name) {
  const cs = modus === 'preis' ? 6 : 5;
  return new TableRow({
    children: [new TableCell({
      borders: nb(),
      columnSpan: cs,
      margins: { top: 200, bottom: 80, left: 120, right: 120 },
      children: [pr(tx(name, { italic: true, size: PT10 }))],
    })],
  });
}

const allePositionen = [...regulaere_positionen, ...optionale_positionen]
  .sort((a, b) => a.position_nr - b.position_nr);

const mainRows = [hRow];
for (const g of grp(allePositionen)) {
  if (g.gewerk) mainRows.push(gRow(g.gewerk));
  for (const p of g.items) mainRows.push(dRow(p));
}
const colW = modus === 'preis'
  ? [C_POS, C_BEZ, C_MNG, C_EIN, C_PRE, C_GES]
  : [C_POS, C_BEZ, C_MNG, C_EIN, C_GES];
const mainTable = new Table({
  width: { size: CW, type: WidthType.DXA },
  columnWidths: colW,
  rows: mainRows,
});

// ── Summen-Tabelle ─────────────────────────────────────────────────────
function sumT(s) {
  const SL = 2800, SR = 1600;
  const sumRows = [
    ['Zwischensumme netto', fmtC(s.zwischensumme_netto), false],
    ['20% USt.', fmtC(s.ust_20), false],
    ['Rechnungsbetrag brutto', fmtC(s.endbetrag_brutto), true],
  ];

  const rows = sumRows.map(([lb, v, b], idx) => {
    const borderStyle = b
      ? { style: BorderStyle.DOUBLE, size: 6, color: '444444' }
      : { style: BorderStyle.SINGLE, size: 4, color: '888888' };
    const isLastRow = idx === sumRows.length - 1;
    return new TableRow({
      cantSplit: true,
      children: [
        new TableCell({ borders: { ...nb(), bottom: borderStyle }, width: { size: SL, type: WidthType.DXA }, margins: { top: 40, bottom: 40, left: 0, right: 80 }, children: [new Paragraph({ spacing: { before: 0, after: 40 }, keepNext: !isLastRow, keepLines: true, children: [tx(lb, { bold: b })] })] }),
        new TableCell({ borders: { ...nb(), bottom: borderStyle }, width: { size: SR, type: WidthType.DXA }, margins: { top: 40, bottom: 40, left: 80, right: 0 }, children: [new Paragraph({ spacing: { before: 0, after: 40 }, alignment: AlignmentType.RIGHT, keepNext: !isLastRow, keepLines: true, children: [tx(v, { bold: b })] })] }),
      ],
    });
  });

  return new Table({ width: { size: SL + SR, type: WidthType.DXA }, columnWidths: [SL, SR], alignment: AlignmentType.RIGHT, rows });
}

const spacerBeforeSumTable = new Paragraph({ spacing: { after: 480 }, keepNext: true, keepLines: true, children: [tx('')] });

const gueltigkeitsParagraph = new Paragraph({
  spacing: { before: 600, after: 0 },
  children: [tx('Unser Angebot ist 1 Monat ab Ausstellungsdatum gültig!', { size: PT9 })],
});

const footerAnchorParagraph = new Paragraph({
  spacing: { before: 0, after: 0 },
  children: [
    new ImageRun({
      data: footerImgBuffer,
      type: 'jpg',
      transformation: { width: FOOTER_W, height: FOOTER_H },
      floating: {
        horizontalPosition: { relative: HorizontalPositionRelativeFrom.MARGIN, align: HorizontalPositionAlign.LEFT },
        verticalPosition: { relative: VerticalPositionRelativeFrom.PAGE, offset: FOOTER_OFFSET_FROM_PAGE_TOP_EMU },
        behindDocument: false, allowOverlap: true,
        wrap: { type: TextWrappingType.NONE, side: TextWrappingSide.BOTH_SIDES },
      },
    }),
  ],
});

// ── Header-Definitionen ───────────────────────────────────────────────
const firstPageHeader = new Header({
  children: [
    new Paragraph({
      alignment: AlignmentType.LEFT,
      spacing: { before: 0, after: 0 },
      children: [new ImageRun({ data: headerImgBuffer, type: 'jpg', transformation: { width: HEADER_W, height: HEADER_H } })],
    }),
  ],
});

const defaultHeaderTable = new Table({
  width: { size: CW, type: WidthType.DXA },
  columnWidths: [Math.round(CW * 0.70), CW - Math.round(CW * 0.70)],
  rows: [new TableRow({
    children: [
      new TableCell({ borders: nb(), width: { size: Math.round(CW * 0.70), type: WidthType.DXA }, margins: { top: 0, bottom: 0, left: 0, right: 0 }, verticalAlign: VerticalAlign.BOTTOM, children: [new Paragraph({ spacing: { before: 0, after: 0 }, children: [tx('Angebot Nr. ', { bold: true, size: PT10 }), tx(angebot_nr, { bold: true, size: PT10 }), tx(' vom ', { bold: true, size: PT10 }), tx(datum, { bold: true, size: PT10 })] })] }),
      new TableCell({ borders: nb(), width: { size: CW - Math.round(CW * 0.70), type: WidthType.DXA }, margins: { top: 0, bottom: 0, left: 0, right: 0 }, verticalAlign: VerticalAlign.BOTTOM, children: [new Paragraph({ spacing: { before: 0, after: 0 }, alignment: AlignmentType.RIGHT, children: [new TextRun({ text: 'Seite ', font: FONT, size: PT9 }), new TextRun({ children: [PageNumber.CURRENT], font: FONT, size: PT9 }), new TextRun({ text: ' von ', font: FONT, size: PT9 }), new TextRun({ children: [PageNumber.TOTAL_PAGES], font: FONT, size: PT9 })] })] }),
    ],
  })],
});

const defaultHeader = new Header({
  children: [
    defaultHeaderTable,
    new Paragraph({ spacing: { before: 0, after: 120 }, children: [new TextRun({ text: '', font: FONT, size: PT9 })] }),
  ],
});

// ── Document zusammenbauen ────────────────────────────────────────────
const children = [
  dinSpacerParagraph,
  kundendatenTable,
  spacerAboveAngebot,
  angebotNrParagraph,
  betrifftParagraph,
  ...warnBlk(),
  mainTable,
];

if (modus === 'preis' && summen.endbetrag_brutto !== null) {
  children.push(spacerBeforeSumTable);
  children.push(sumT(summen));
}

children.push(gueltigkeitsParagraph);
children.push(footerAnchorParagraph);

const doc = new Document({
  styles: { default: { document: { run: { font: FONT, size: PT9 } } } },
  settings: { updateFields: true },
  sections: [{
    headers: { first: firstPageHeader, default: defaultHeader },
    properties: {
      titlePage: true,
      page: {
        size: { width: A4_W, height: A4_H },
        margin: { top: MG + 400, right: MG, bottom: MG + 400, left: MG, header: 600, footer: 600 },
      },
    },
    children,
  }],
});

// ── Output ────────────────────────────────────────────────────────────
const buffer = await Packer.toBuffer(doc);
const filename = `Angebot_${angebot_nr}.docx`;

return [{
  json: {
    angebot_nr, datum, modus,
    filename,
    kunden_name: kundendaten?.firmenname || [kundendaten?.vorname, kundendaten?.nachname].filter(Boolean).join(' '),
    kunden_mail: kundendaten?.mail,
    mail_subject: meta.mail_subject,
    mail_body: meta.mail_body,
    seatable_row_id: meta.seatable_row_id,
    angebotsnummer: meta.angebotsnummer
  },
  binary: {
    data: { data: buffer.toString('base64'), mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', fileName: filename },
  },
}];

