parameters.jsCode:
// ═══════════════════════════════════════════════════════════════
// Versand abgeschlossen - Session bereinigen + Erfolg-Message
// ═══════════════════════════════════════════════════════════════
// Wird nach erfolgreichem Mail-Versand und Status-Update auf
// 'Versendet' aufgerufen. Räumt die Session auf.
//
// v2: router-Quelle gewechselt auf Send-Session laden
// (zuverlässiger bei langen Pfaden hinter Switch-Nodes).
// ═══════════════════════════════════════════════════════════════

const docxData = $('DOCX neu rendern').first().json;
const router = $('Send-Session laden').first().json;
const chat_id = router.chat_id;
const bot_token = router.bot_token;

const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
delete staticData[sessionKey];

const message = `✅ *Angebot ${docxData.angebotsnummer} versendet!*\n\n` +
  `An: ${docxData.kunden_mail}\n` +
  `Betreff: ${docxData.mail_subject}\n\n` +
  `Status in SeaTable: *Versendet*`;

return [{
  json: {
    chat_id,
    bot_token,
    message
  }
}];

// ═══════════════════════════════════════════════════════════════
// Korrektur-Parser für Send (Versand-Workflow)
// ═══════════════════════════════════════════════════════════════
// Begrenzt auf Send-relevante Felder:
//   mail, anrede, vorname, nachname, firmenname, betreff
//
// Andere Felder (Positions-Preise, Mengen) sind hier verboten -
// dafür gibt's den Aufgreifen-Workflow.
//
// Mehrere Korrekturen in einer Nachricht möglich:
//   "Korrektur: mail neu@test.at, betreff Sanierungsarbeiten"
// ═══════════════════════════════════════════════════════════════

const data = $input.first().json;
const session = data.send_session;
const correction_text = data.correction_text;

if (!correction_text) {
  throw new Error('Kein correction_text - Korrektur-Parser falsch geroutet');
}

// ─── Erlaubte Felder + Aliase ───────────────────────────────────
const FELD_ALIASE = {
  'mail': 'mail', 'email': 'mail', 'e-mail': 'mail',
  'anrede': 'anrede',
  'vorname': 'vorname',
  'nachname': 'nachname',
  'firma': 'firma', 'firmenname': 'firma',
  'betreff': 'betreff', 'betrifft': 'betreff', 'thema': 'betreff'
};

const VERBOTENE_FELDER = {
  'preis': 'Preise sind hier nicht änderbar - dafür den Aufgreifen-Workflow nutzen (/preise YYYY-NNNNN).',
  'einzelpreis': 'Preise sind hier nicht änderbar - dafür den Aufgreifen-Workflow nutzen.',
  'menge': 'Mengen sind hier nicht änderbar - dafür den Aufgreifen-Workflow nutzen.',
  'einheit': 'Einheiten sind hier nicht änderbar - dafür den Aufgreifen-Workflow nutzen.',
  'position': 'Positions-Inhalte sind hier nicht änderbar - dafür den Aufgreifen-Workflow nutzen.',
  'straße': 'Adresse hier nicht änderbar (Versand geht per Mail). Aufgreifen-Workflow nutzen falls Brief.',
  'strasse': 'Adresse hier nicht änderbar (Versand geht per Mail). Aufgreifen-Workflow nutzen falls Brief.',
  'plz': 'Adresse hier nicht änderbar (Versand geht per Mail).',
  'ort': 'Adresse hier nicht änderbar (Versand geht per Mail).',
  'telefon': 'Telefon hier nicht änderbar (Versand geht per Mail).',
  'tel': 'Telefon hier nicht änderbar (Versand geht per Mail).',
  'kundennummer': 'Kundennummer hier nicht änderbar.',
  'uid': 'UID hier nicht änderbar.',
  'baustelle': 'Baustelle hier nicht änderbar.',
  'sachbearbeiter': 'Sachbearbeiter hier nicht änderbar.'
};

function buildHilfeNachricht(fehlertext) {
  let msg = fehlertext + '\n\n';
  msg += '📝 *Syntax:*\n`Korrektur: feld wert, feld wert, ...`\n\n';
  msg += '*Erlaubte Felder vor Versand:*\n';
  msg += '• mail\n• anrede (Herr/Frau/Firma)\n• vorname, nachname, firmenname\n• betreff\n\n';
  msg += '*Beispiele:*\n';
  msg += '`Korrektur: mail kunde@neu.at`\n';
  msg += '`Korrektur: betreff Sanierungsarbeiten Bad`\n';
  msg += '`Korrektur: nachname Müller-Beispiel, mail mueller@gmail.com`\n\n';
  msg += '_Für inhaltliche Änderungen (Preise, Mengen, Positionen): Aufgreifen-Workflow `/preise YYYY-NNNNN` nutzen._';
  return msg;
}

// ─── Textstart prüfen ───────────────────────────────────────────
const startMatch = correction_text.match(/^(?:korrektur|ändern|fix|korrigieren)\s*[:,]?\s*(.+)$/is);
if (!startMatch) {
  return [{
    json: {
      action: 'send_correction_failed',
      chat_id: data.chat_id,
      bot_token: data.bot_token,
      message: buildHilfeNachricht('❌ Nachricht muss mit "Korrektur:" beginnen.')
    }
  }];
}

const rest = startMatch[1].trim();

// ─── Multi-Feld-Splitting ──────────────────────────────────────
function splitKorrekturen(text) {
  const parts = text.split(/\s*,\s*/);
  const result = [];
  let current = '';
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i].trim();
    if (!part) continue;
    const firstWord = part.split(/\s+/)[0].toLowerCase().replace(/[.:;]$/, '');
    const istBekannt = FELD_ALIASE.hasOwnProperty(firstWord) || VERBOTENE_FELDER.hasOwnProperty(firstWord);
    if (istBekannt) {
      if (current) result.push(current.trim());
      current = part;
    } else {
      if (current) current += ', ' + part;
      else current = part;
    }
  }
  if (current) result.push(current.trim());
  return result;
}

const korrekturParts = splitKorrekturen(rest);

if (korrekturParts.length === 0) {
  return [{
    json: {
      action: 'send_correction_failed',
      chat_id: data.chat_id,
      bot_token: data.bot_token,
      message: buildHilfeNachricht('❌ Keine Felder in der Korrektur gefunden.')
    }
  }];
}

// ─── Korrekturen anwenden ──────────────────────────────────────
const kd = JSON.parse(JSON.stringify(session.validator_data.kundendaten));
let neuerBetreff = session.validator_data.betreff;
const angewendet = [];
const fehler = [];

for (const part of korrekturParts) {
  const match = part.match(/^(\S+)\s+(.+)$/s);
  if (!match) {
    fehler.push(`"${part}": kein Wert angegeben`);
    continue;
  }
  const feldRaw = match[1].toLowerCase().replace(/[.:;]$/, '');
  const wert = match[2].trim().replace(/[.,]$/, '');

  if (VERBOTENE_FELDER.hasOwnProperty(feldRaw)) {
    fehler.push(VERBOTENE_FELDER[feldRaw]);
    continue;
  }

  const feldCanonical = FELD_ALIASE[feldRaw];
  if (!feldCanonical) {
    fehler.push(`"${feldRaw}" ist kein erlaubtes Feld`);
    continue;
  }

  try {
    switch (feldCanonical) {
      case 'mail':
        if (!/^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/i.test(wert)) {
          fehler.push(`"${wert}" ist keine gültige Mail-Adresse`);
          continue;
        }
        kd.mail = wert.toLowerCase();
        break;
      case 'anrede':
        const a = wert.toLowerCase().trim();
        if (a.includes('herr')) kd.anrede = 'Herr';
        else if (a.includes('frau')) kd.anrede = 'Frau';
        else if (a.includes('firma')) kd.anrede = 'Firma';
        else {
          fehler.push(`Anrede "${wert}" nicht erkannt - erlaubt: Herr, Frau, Firma`);
          continue;
        }
        break;
      case 'vorname':
        kd.vorname = wert;
        break;
      case 'nachname':
        kd.nachname = wert;
        break;
      case 'firma':
        kd.firmenname = wert;
        break;
      case 'betreff':
        neuerBetreff = wert;
        break;
    }
    angewendet.push({ feld: feldCanonical, wert });
  } catch (e) {
    fehler.push(`${feldCanonical}: ${e.message}`);
  }
}

if (angewendet.length === 0) {
  return [{
    json: {
      action: 'send_correction_failed',
      chat_id: data.chat_id,
      bot_token: data.bot_token,
      message: buildHilfeNachricht('❌ Keine Korrekturen übernommen:\n' + fehler.map(f => '• ' + f).join('\n'))
    }
  }];
}

// ─── Aktualisierte Daten zurück in Session schreiben ───────────
const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${data.chat_id}`;
const updatedSession = staticData[sessionKey];
updatedSession.validator_data.kundendaten = kd;
updatedSession.validator_data.betreff = neuerBetreff;
// Mail-Subject und Body neu generieren mit aktualisierten Daten
const angebotsnummer = updatedSession.angebotsnummer;
const datum = updatedSession.validator_data.datum;

function bauAnredeZeile(kd) {
  if (kd.anrede === 'Herr') return `Sehr geehrter Herr ${kd.nachname || ''}`.trim() + ',';
  if (kd.anrede === 'Frau') return `Sehr geehrte Frau ${kd.nachname || ''}`.trim() + ',';
  if (kd.anrede === 'Firma') return 'Sehr geehrte Damen und Herren,';
  return 'Sehr geehrte Damen und Herren,';
}
const anredeZeile = bauAnredeZeile(kd);

updatedSession.mail_subject = `Ihr Angebot ${angebotsnummer} vom ${datum}`;
updatedSession.mail_body = `${anredeZeile}

vielen Dank für Ihr Interesse an unseren Leistungen.
Anbei übermitteln wir Ihnen unser Angebot Nr. ${angebotsnummer} vom ${datum} zum Thema "${neuerBetreff || 'Diverse Arbeiten'}".

Das Angebot ist ab Ausstellungsdatum einen Monat gültig.
Für Rückfragen stehe ich Ihnen gerne zur Verfügung.

Mit freundlichen Grüßen
${updatedSession.validator_data.sachbearbeiter || 'Ing. Ernst Baumeister'}
Baumeister GmbH`;
updatedSession.created_at = Date.now();

return [{
  json: {
    action: 'send_correction_applied',
    chat_id: data.chat_id,
    bot_token: data.bot_token,
    seatable_row_id: updatedSession.seatable_row_id,
    angewendet,
    fehler,
    updated_kundendaten_json: JSON.stringify(kd),
    updated_betreff: neuerBetreff,
    new_session: updatedSession
  }
}];

// ═══════════════════════════════════════════════════════════════
// Session Save + Preview v3 (mit Inline-Buttons)
//
// ÄNDERUNG ggü. v2:
//   reply_markup im Output ergänzt. Im Telegram Preview senden
//   Node wird dieses Feld als Body-Parameter mitgegeben, sodass
//   unter der Vorschau die drei Buttons erscheinen:
//
//     ✅ OK              → text "OK" → action='confirm'
//     ✏️ Korrektur        → text "Korrektur" → action='correct'
//     🔁 Neu diktieren    → text "Neu diktieren" → action='cancel'
//
//   Die Buttons werden vom Message Router v3 in genau diese Texte
//   übersetzt, sodass der Session Handler sie identisch zu einer
//   getippten Antwort behandelt.
//
// Zeigt im Preview:
// - Briefkopf (Anrede/Name/Adresse)
// - Kontaktdaten (Tel/Mail) + Kundennummer/UID wenn vorhanden
// - Baustelle wenn diktiert
// - Betreff (diktiert ODER Hinweis "wird automatisch ermittelt")
// - Sachbearbeiter (diktiert ODER Fallback-Hinweis)
// ═══════════════════════════════════════════════════════════════

const data = $input.first().json;
const kd = data.kundendaten;
const chat_id = $('Message Router').first().json.chat_id;

// ─── Briefkopf-Preview aufbauen ─────────────────────────────────
const anredeZeile = kd.anrede === 'Herr' ? 'Herrn'
                  : kd.anrede === 'Frau' ? 'Frau'
                  : kd.anrede === 'Firma' ? 'Firma'
                  : kd.anrede;

let briefkopf = '```\n';
briefkopf += anredeZeile + '\n';
if (kd.firmenname) {
  briefkopf += kd.firmenname + '\n';
} else if (kd.vorname || kd.nachname) {
  briefkopf += [kd.vorname, kd.nachname].filter(Boolean).join(' ') + '\n';
}
briefkopf += [kd.strasse, kd.hausnummer].filter(Boolean).join(' ') + '\n';
briefkopf += [kd.plz, kd.ort].filter(Boolean).join(' ') + '\n\n';
briefkopf += (kd.telefon ? 'Tel.:   ' + kd.telefon + '\n' : '');
briefkopf += (kd.mail ? 'Mail:   ' + kd.mail + '\n' : '');
briefkopf += (kd.kundennummer ? 'Kd.-Nr.: ' + kd.kundennummer + '\n' : '');
briefkopf += (kd.uid ? 'UID:    ' + kd.uid + '\n' : '');
briefkopf += '```';

// ─── Baustellen-Block (wenn diktiert) ───────────────────────────
let baustellenBlock = '';
if (kd.baustelle) {
  baustellenBlock = '\n\n🏗 *Baustelle:*\n```\n';
  if (kd.baustelle.plz_ort) baustellenBlock += kd.baustelle.plz_ort + '\n';
  if (kd.baustelle.strasse) baustellenBlock += kd.baustelle.strasse + '\n';
  if (kd.baustelle.hinweis) baustellenBlock += kd.baustelle.hinweis + '\n';
  baustellenBlock += '```';
}

// ─── Metadaten (Betreff, Sachbearbeiter) ────────────────────────
let metaBlock = '\n\n';
metaBlock += '📄 *Betreff:* ' + (kd.betreff || '_(wird automatisch aus Gewerken ermittelt)_') + '\n';
metaBlock += '👤 *Sachbearbeiter:* ' + (kd.sachbearbeiter || '_Ing. Ernst Baumeister (Standard)_') + '\n';

// ─── Nachricht zusammenbauen ────────────────────────────────────
let previewMessage = '📋 *So wird der Briefkopf im Angebot aussehen:*\n\n' + briefkopf;
previewMessage += baustellenBlock;
previewMessage += metaBlock;

if (kd.warnings && kd.warnings.length > 0) {
  previewMessage += '\n⚠️ *Hinweise:*\n';
  for (const w of kd.warnings) previewMessage += '• ' + w + '\n';
}

if (kd.pflichtfehler && kd.pflichtfehler.length > 0) {
  previewMessage += '\n❌ *Pflichtfelder fehlen - bitte neu diktieren!*\n';
}

previewMessage += '\n*Antwort-Optionen:*\n';
previewMessage += '✅ `OK` → Angebot wird erstellt\n';
previewMessage += '✏️ `Korrektur: [Feld] [neuer Wert]` → einzelnes Feld\n';
previewMessage += '🔁 `Neu diktieren` → Abbruch';

// ─── Session in Static Data speichern ───────────────────────────
const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
staticData[sessionKey] = {
  created_at: Date.now(),
  state: 'awaiting_confirmation',
  kundendaten: kd,
  rest_transkript: data.rest_transkript,
  original_transkript: data.original_transkript
};

// ─── Inline-Keyboard mit OK / Korrektur / Neu diktieren ─────────
const replyMarkup = JSON.stringify({
  inline_keyboard: [
    [{ text: '✅ OK', callback_data: 'confirm' }],
    [{ text: '✏️ Korrektur', callback_data: 'correct' }],
    [{ text: '🔁 Neu diktieren', callback_data: 'redo' }]
  ]
});

return [{
  json: {
    chat_id,
    bot_token: $('Message Router').first().json.bot_token,
    preview_message: previewMessage,
    has_pflichtfehler: (kd.pflichtfehler && kd.pflichtfehler.length > 0),
    reply_markup: replyMarkup
  }
}];

// ═══════════════════════════════════════════════════════════════
// Send-Abbruch behandeln
// ═══════════════════════════════════════════════════════════════
// Wenn Stephan im Send-Modus 'Abbruch' schickt:
// - Status BLEIBT 'Finalisiert' (manuell versendbar oder per /senden später)
// - Session wird aus static data gelöscht
// ═══════════════════════════════════════════════════════════════

const router = $('Action Router').first().json;
const chat_id = router.chat_id;
const bot_token = router.bot_token;

const staticData = $getWorkflowStaticData('global');
const sessionKey = `session_${chat_id}`;
const session = staticData[sessionKey];
const angebotsnummer = session?.angebotsnummer || 'unbekannt';

delete staticData[sessionKey];

const message = `❌ Versand abgebrochen.\n\n` +
  `Angebot ${angebotsnummer} bleibt auf Status *Finalisiert* in SeaTable.\n` +
  `Du kannst es später manuell versenden oder mit \`/senden ${angebotsnummer}\` reaktivieren _(falls implementiert)_.`;

return [{
  json: {
    chat_id,
    bot_token,
    message
  }
}];

// ═══════════════════════════════════════════════════════════════
// Filename auf .pdf umstellen (Senden-Pfad) v2
// ═══════════════════════════════════════════════════════════════
// FIX: Das komplette Binary-Objekt durchreichen und nur die Metadaten
// (fileName, mimeType) überschreiben. Kein manuelles Kopieren von .data,
// weil n8n das Binary intern auch als Buffer/Stream darstellen kann.
// ═══════════════════════════════════════════════════════════════

const item = $input.first();
const angebotNr = $('DOCX neu rendern').first().json.angebot_nr;

if (!angebotNr) {
  throw new Error('angebot_nr fehlt in DOCX-neu-rendern-Output. Pipeline kaputt.');
}

if (!item.binary) {
  throw new Error('Kein Binary in der Eingabe. Gotenberg-Konvertierung fehlgeschlagen?');
}

const binaryKeys = Object.keys(item.binary);
if (binaryKeys.length === 0) {
  throw new Error('Binary-Objekt ist leer.');
}

const sourceKey = binaryKeys[0];
const sourceBinary = item.binary[sourceKey];

const pdfFilename = `Angebot_${angebotNr}.pdf`;

// Komplettes Binary-Objekt kopieren, nur Metadaten ändern
const newBinary = {
  ...sourceBinary,
  mimeType: 'application/pdf',
  fileName: pdfFilename,
  fileExtension: 'pdf'
};

return [{
  json: { ...item.json, pdf_filename: pdfFilename },
  binary: {
    data: newBinary
  }
}];

// ═══════════════════════════════════════════════════════════════
// Send-Session anlegen v8 (modus-aware PDF-Vorschau + Bearbeiten-Button)
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG v8 gegenüber v7:
//   Zusätzlich zum bisherigen Output wird ein `reply_markup` als
//   JSON-String mit Inline-Keyboard generiert. Wird im nächsten
//   HTTP-Node (Telegram Komplettzusammenfassung1) als bodyParameter
//   mitgegeben und rendert in Telegram als Button:
//
//     📝 Angebot bearbeiten
//
//   callback_data = "edit:<angebotsnummer>"
//   Beim Klick wird der Button von Message Router v2 in einen
//   /preise <Nr> Text-Befehl übersetzt.
//
//   Funktioniert in BEIDEN Modi:
//   - preis  → Bearbeiten zusätzlich zu "Senden / Korrektur / Abbruch"
//   - leistung → Bearbeiten als Hauptaktion (Preise nachreichen)
//
// ÄNDERUNGEN gegenüber v6 (aus v7, unverändert):
//   Bei modus === 'leistung' wird der Node nicht abgebrochen, sondern
//   produziert ein PDF + andere Caption (Hinweis auf /preise).
//
// VORAUSSETZUNG: "Status Finalisiert?1" IF-Node muss entfernt sein,
// damit dieser Node auch im leistung-Modus durchläuft.
// ═══════════════════════════════════════════════════════════════

const data = $('Pipeline fortsetzen').first().json;
const seatableResult = $input.first().json;
const chat_id = $('Message Router').first().json.chat_id;
const bot_token = $('Message Router').first().json.bot_token;

const angebotsnummer = String(data.angebot_nr);
const kundendaten = data.kundendaten;
const istPreisModus = data.modus === 'preis';

function escapeMd(text) {
  if (text === null || text === undefined) return '';
  return String(text)
    .replace(/\\/g, '\\\\')
    .replace(/_/g, '\\_')
    .replace(/\*/g, '\\*')
    .replace(/`/g, '\\`')
    .replace(/\[/g, '\\[');
}

function findRowId(obj) {
  if (!obj || typeof obj !== 'object') return null;
  const directKeys = ['_id', 'row_id', 'id', 'rowId', 'rowID'];
  for (let i = 0; i < directKeys.length; i++) {
    const v = obj[directKeys[i]];
    if (v && typeof v === 'string' && v.length > 0) return v;
  }
  const nestedKeys = ['row', 'data', 'result', 'body', 'response'];
  for (let i = 0; i < nestedKeys.length; i++) {
    const nested = obj[nestedKeys[i]];
    if (nested && typeof nested === 'object') {
      for (let j = 0; j < directKeys.length; j++) {
        const v = nested[directKeys[j]];
        if (v && typeof v === 'string' && v.length > 0) return v;
      }
    }
  }
  const idPattern = /^[a-zA-Z0-9_-]{20,30}$/;
  const keys = Object.keys(obj);
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    const v = obj[k];
    if (typeof v === 'string' && idPattern.test(v)) {
      if (k === '_id' || /id$/i.test(k) || /^id/i.test(k)) return v;
    }
  }
  return null;
}

const seatable_row_id = findRowId(seatableResult);
if (!seatable_row_id) {
  let fullDump = '';
  try { fullDump = JSON.stringify(seatableResult, null, 2); }
  catch (e) { fullDump = 'JSON.stringify-Fehler: ' + e.message; }
  if (fullDump.length > 3000) fullDump = fullDump.substring(0, 3000) + '... [gekürzt]';
  throw new Error('SeaTable-Insert hat keine row_id zurückgegeben.\n\nResponse:\n' + fullDump);
}

// DOCX-Binary aus dem ersten Generator-Lauf holen
let docxBinary = null;
try {
  const docxItem = $('DOCX Generator').first();
  if (docxItem && docxItem.binary) docxBinary = docxItem.binary;
} catch (e) {}

if (!docxBinary || !docxBinary.data) {
  throw new Error('DOCX-Binary konnte nicht aus DOCX Generator gelesen werden.');
}

const kundenName = kundendaten.firmenname
  || [kundendaten.vorname, kundendaten.nachname].filter(Boolean).join(' ')
  || '(Name unbekannt)';

let caption;
let staticDataUpdate = null;

if (istPreisModus) {
  // ─── PREIS-MODUS: bestehende Logik ──────────────────────────
  function bauAnredeZeile(kd) {
    if (kd.anrede === 'Herr') return ('Sehr geehrter Herr ' + (kd.nachname || '')).trim() + ',';
    if (kd.anrede === 'Frau') return ('Sehr geehrte Frau ' + (kd.nachname || '')).trim() + ',';
    if (kd.anrede === 'Firma') return 'Sehr geehrte Damen und Herren,';
    return 'Sehr geehrte Damen und Herren,';
  }

  const anredeZeile = bauAnredeZeile(kundendaten);
  const mail_subject = 'Ihr Angebot ' + angebotsnummer + ' vom ' + data.datum;
  const betreffText = data.betreff || 'Diverse Arbeiten';
  const sachbearbeiterName = data.sachbearbeiter || 'Ing. Ernst Baumeister';

  const mail_body =
    anredeZeile + '\n\n' +
    'vielen Dank für Ihr Interesse an unseren Leistungen.\n' +
    'Anbei übermitteln wir Ihnen unser Angebot Nr. ' + angebotsnummer +
    ' vom ' + data.datum + ' zum Thema "' + betreffText + '".\n\n' +
    'Das Angebot ist ab Ausstellungsdatum einen Monat gültig.\n' +
    'Für Rückfragen stehe ich Ihnen gerne zur Verfügung.\n\n' +
    'Mit freundlichen Grüßen\n' +
    sachbearbeiterName + '\n' +
    'Baumeister GmbH';

  const empfaenger_summary =
    '*Empfänger:*\n' +
    '  Name:   ' + escapeMd(kundenName) + '\n' +
    '  Mail:   ' + escapeMd(kundendaten.mail || '(keine)') + '\n' +
    '  Anrede: ' + escapeMd(kundendaten.anrede || '') +
    ' (Brief: "' + escapeMd(anredeZeile) + '")\n';

  const mail_preview =
    '*Mail-Vorschau:*\n' +
    '─────────────────\n' +
    'Betreff: ' + escapeMd(mail_subject) + '\n\n' +
    escapeMd(mail_body) + '\n' +
    '─────────────────';

  const captionRaw =
    '*Angebot ' + escapeMd(angebotsnummer) + ' fertig zum Versand*\n\n' +
    empfaenger_summary + '\n' +
    mail_preview + '\n\n' +
    'Anhang: Angebot ' + escapeMd(angebotsnummer) + '.pdf\n\n' +
    '*Antwort-Optionen:*\n' +
    'Senden → an Kunde versenden\n' +
    'Korrektur: feld wert → Felder: mail, anrede, vorname, nachname, firmenname, betreff\n' +
    'Abbruch → bleibt auf Status Finalisiert';

  caption = captionRaw.length > 1024
    ? captionRaw.substring(0, 990) + '\n\n[Caption gekürzt – siehe PDF]'
    : captionRaw;

  staticDataUpdate = {
    created_at: Date.now(),
    state: 'awaiting_send_confirmation',
    angebotsnummer: angebotsnummer,
    seatable_row_id: seatable_row_id,
    validator_data: {
      angebot_nr: data.angebot_nr,
      datum: data.datum,
      modus: data.modus,
      hat_gemischte_diktion: data.hat_gemischte_diktion,
      hat_optionale_positionen: data.hat_optionale_positionen,
      regulaere_positionen: data.regulaere_positionen,
      optionale_positionen: data.optionale_positionen,
      summen: data.summen,
      optionale_summen: data.optionale_summen,
      warnings: data.warnings || [],
      kundendaten: kundendaten,
      betreff: data.betreff,
      sachbearbeiter: data.sachbearbeiter,
      baustelle: data.baustelle
    },
    mail_subject: mail_subject,
    mail_body: mail_body
  };

} else {
  // ─── LEISTUNG-MODUS: nur PDF-Vorschau + /preise-Hinweis ─────
  const betreffText = data.betreff || 'Diverse Arbeiten';
  const positionenAnzahl = (data.regulaere_positionen || []).length
    + (data.optionale_positionen || []).length;

  const captionRaw =
    '*Leistungsverzeichnis ' + escapeMd(angebotsnummer) + '*\n\n' +
    'Status: _Entwurf, ohne Preise_\n' +
    'Kunde: ' + escapeMd(kundenName) + '\n' +
    'Betreff: ' + escapeMd(betreffText) + '\n' +
    'Positionen: ' + positionenAnzahl + '\n\n' +
    'Tippe auf 📝 *Angebot bearbeiten* oder schicke `/preise ' +
    escapeMd(angebotsnummer) + '` als Text-Nachricht, um Preise zu diktieren.';

  caption = captionRaw.length > 1024
    ? captionRaw.substring(0, 990) + '\n\n[Caption gekürzt – siehe PDF]'
    : captionRaw;

  staticDataUpdate = null;
}

if (staticDataUpdate) {
  const staticData = $getWorkflowStaticData('global');
  const sessionKey = 'session_' + chat_id;
  staticData[sessionKey] = staticDataUpdate;
}

// FIX v8: Inline-Keyboard mit Bearbeiten-Button generieren.
// Telegram sendDocument erwartet reply_markup als JSON-STRING
// (nicht als Object) wenn der Request multipart/form-data ist.
const replyMarkup = JSON.stringify({
  inline_keyboard: [
    [
      { text: '📝 Angebot bearbeiten', callback_data: 'edit:' + angebotsnummer }
    ]
  ]
});

return [{
  json: {
    chat_id: chat_id,
    bot_token: bot_token,
    angebotsnummer: angebotsnummer,
    caption: caption,
    pdf_filename: 'Angebot_' + angebotsnummer + '.pdf',
    skip_send_workflow: !istPreisModus,
    modus: data.modus,
    reply_markup: replyMarkup
  },
  binary: docxBinary
}];

// ═══════════════════════════════════════════════════════════════
// Filename auf .pdf umstellen (Vorschau-Pfad) v3 - FIXED
// ═══════════════════════════════════════════════════════════════

const item = $input.first();

// FIX 1: Angebotsnummer direkt aus dem Input JSON holen, 
// da sie dort bereits vorhanden ist.
const angebotsnummer = item.json.angebotsnummer;

if (!angebotsnummer) {
  throw new Error('angebotsnummer fehlt in den Eingabedaten.');
}

if (!item.binary) {
  throw new Error('Kein Binary in der Eingabe. Gotenberg-Konvertierung fehlgeschlagen?');
}

const binaryKeys = Object.keys(item.binary);
if (binaryKeys.length === 0) {
  throw new Error('Binary-Objekt ist leer.');
}

const sourceKey = binaryKeys[0];
const sourceBinary = item.binary[sourceKey];

const pdfFilename = `Angebot_${angebotsnummer}.pdf`;

const newBinary = {
  ...sourceBinary,
  mimeType: 'application/pdf',
  fileName: pdfFilename,
  fileExtension: 'pdf'
};

return [{
  json: { ...item.json, pdf_filename: pdfFilename },
  binary: {
    // FIX 2: Den originalen Binary-Key (z.B. 'data') dynamisch beibehalten
    [sourceKey]: newBinary 
  }
}];

// ═══════════════════════════════════════════════════════════════
// Betreff-Generator Teil 1: Prep (Prompt-Builder) v2
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG ggü. v1:
//   Robuster gegen Stream-Verlust durch dazwischen-gehängte HTTP-
//   Status-Nodes (z.B. "Progress: Vorschau wird erstellt"). Wenn der
//   Input keine Validator-Felder hat, werden die Daten direkt vom
//   letzten Validator-Lauf via $('Validator + Summen') oder
//   $('Validator + Summen 2') geholt. Damit funktioniert Betreff-
//   Prep unabhängig davon, ob ein HTTP-Status-Node zwischen Validator
//   und Betreff-Prep gehängt wird oder nicht.
//
// Architektur (unverändert):
//   [Validator + Summen]    → [Progress: …] → [Betreff-Prep] → [IF]
//   [Validator + Summen 2]                  → [Betreff-Prep] → [IF]
//     true  → [OpenAI Node: Betreff-LLM] → [Betreff-Apply] → [Counter]
//     false → [Counter]
// ═══════════════════════════════════════════════════════════════

// ─── 0. Daten holen (mit Fallback auf Validator-Nodes) ──────────
let data = $input.first().json;

// Prüfen ob $input echte Validator-Felder enthält
function hasValidatorShape(d) {
  return d && (
    d.regulaere_positionen !== undefined ||
    d.optionale_positionen !== undefined ||
    d.aufgegriffen_positionen !== undefined ||
    d.kundendaten !== undefined
  );
}

if (!hasValidatorShape(data)) {
  // Erst-Diktat-Pfad: vom Validator + Summen direkt laden
  try {
    const vd = $('Validator + Summen').first()?.json;
    if (hasValidatorShape(vd)) data = vd;
  } catch (e) { /* Node nicht im aktuellen Run */ }

  // Aufgreifen-Pfad: vom Validator + Summen 2 direkt laden
  if (!hasValidatorShape(data)) {
    try {
      const vd2 = $('Validator + Summen 2').first()?.json;
      if (hasValidatorShape(vd2)) data = vd2;
    } catch (e) { /* Node nicht im aktuellen Run */ }
  }
}

// ─── 1. Aktuellen Betreff prüfen ────────────────────────────────
// Wenn er bereits einen sinnvollen Wert hat (≠ "Diverse Arbeiten"),
// nicht überschreiben — der Benutzer hat explizit etwas diktiert
// oder der Validator hat ein eindeutiges Gewerk erkannt.
const aktueller_betreff = data.betreff;
if (aktueller_betreff &&
    typeof aktueller_betreff === 'string' &&
    aktueller_betreff.trim() &&
    aktueller_betreff.trim().toLowerCase() !== 'diverse arbeiten') {
  return [{
    json: {
      ...data,
      needs_llm: false,
      betreff_quelle: 'unveraendert'
    }
  }];
}

// ─── 2. Positionen sammeln ──────────────────────────────────────
// Beide Pfade (Erst-Diktat und Aufgreifen) abdecken.
const positionen = [
  ...(data.regulaere_positionen || []),
  ...(data.optionale_positionen || []),
  ...(data.aufgegriffen_positionen || []),
  ...(data.positionen || [])
];

const uniquePositionen = [];
const seen = new Set();
for (const p of positionen) {
  if (!p || !p.position_nr) continue;
  const key = p.position_nr + '_' + (p.ist_optional ? '1' : '0');
  if (seen.has(key)) continue;
  seen.add(key);
  uniquePositionen.push(p);
}
uniquePositionen.sort((a, b) => a.position_nr - b.position_nr);

// ─── 3. Beschreibungen extrahieren ──────────────────────────────
const beschreibungen = uniquePositionen
  .filter(p => p.beschreibung_normalisiert || p.rohtext)
  .map(p => {
    const text = p.beschreibung_normalisiert || p.rohtext;
    const opt = p.ist_optional ? ' (optional)' : '';
    return `Position ${p.position_nr}${opt}: ${text}`;
  })
  .join('\n');

if (!beschreibungen.trim()) {
  return [{
    json: {
      ...data,
      needs_llm: false,
      betreff: 'Diverse Arbeiten',
      betreff_quelle: 'fallback_keine_positionen'
    }
  }];
}

// ─── 4. LLM-Prompts vorbereiten ─────────────────────────────────
const systemPrompt = `Du bist ein Baumeister-Assistent in Österreich.
Erzeuge aus den folgenden Leistungspositionen einen prägnanten Betreff für ein Bauangebot.

REGELN:
- Maximal 3-4 Wörter
- Im Baumeister-Stil: "Carport-Neubau", "Bad-Sanierung Obergeschoss", "Estricharbeiten Wohnzimmer", "Dachausbau", "Fassadensanierung"
- Wenn die Positionen wirklich diverse, nicht zusammenhängende Gewerke abdecken (z.B. Carport UND Bad UND Garten), antworte mit "Diverse Arbeiten"
- KEINE Anführungszeichen, KEIN abschließender Punkt, KEINE Erklärung
- NUR den Betreff, sonst nichts

Beispiele:
Input: "Position 1: Baustelleneinrichtung. Position 2: Fundamente für Carport. Position 3: Holzcarport liefern und aufstellen."
Output: Carport-Neubau

Input: "Position 1: Wandfliesen verlegen. Position 2: Bodenfliesen verlegen. Position 3: Sanitäranlagen montieren."
Output: Bad-Sanierung

Input: "Position 1: Estrich herstellen. Position 2: Parkett verlegen."
Output: Bodenarbeiten

Input: "Position 1: Estrich Wohnzimmer. Position 2: Bad-Demontage. Position 3: Carport streichen."
Output: Diverse Arbeiten`;

return [{
  json: {
    ...data,
    needs_llm: true,
    betreff_system_prompt: systemPrompt,
    betreff_user_prompt: beschreibungen
  }
}];

// ═══════════════════════════════════════════════════════════════
// Betreff-Generator Teil 2: Apply (LLM-Output verarbeiten)
// ═══════════════════════════════════════════════════════════════
// Architektur:
//   [Validator + Summen] → [Betreff-Prep] → [IF: needs_llm]
//     true  → [OpenAI Node: Betreff-LLM] → [Betreff-Apply] → [Counter]
//     false → [Counter]
//
// Zweck:
//   - Liest die LLM-Antwort vom OpenAI-Node davor
//   - Bereinigt Anführungszeichen, Trailing-Punkte etc.
//   - Validiert Länge (3-60 Zeichen)
//   - Bei ungültiger Antwort → Heuristik-Fallback
//   - Setzt finalen `betreff` + `betreff_quelle` und reicht
//     die Original-Validator-Daten weiter.
//
// WICHTIG:
//   Die Original-Validator-Daten werden über $('Betreff-Prep')
//   geholt, weil der OpenAI-Node das Item-JSON ggf. ersetzt.
//
// Output betreff_quelle:
//   'llm'                          → LLM-Antwort wurde übernommen
//   'fallback_llm_kein_output'     → OpenAI-Node lieferte keinen String
//   'fallback_llm_invalid_length'  → LLM-Antwort < 3 oder > 60 Zeichen
//   'heuristik'                    → Heuristik-Fallback aktiv
// ═══════════════════════════════════════════════════════════════

// ─── 1. Daten holen ─────────────────────────────────────────────
const llmItem = $input.first().json;
const data = $('Betreff-Prep').first().json; // Original-Validator-Daten

// ─── 2. LLM-Antwort extrahieren ─────────────────────────────────
// n8n Langchain OpenAI Node v2.1 legt die Antwort typischerweise
// in 'message.content' ab. Wir prüfen defensiv mehrere Felder,
// damit der Code auch bei zukünftigen n8n-Updates robust bleibt.
let llmResponse = null;
if (typeof llmItem.message?.content === 'string') {
  llmResponse = llmItem.message.content;
} else if (typeof llmItem.choices?.[0]?.message?.content === 'string') {
  llmResponse = llmItem.choices[0].message.content;
} else if (typeof llmItem.content === 'string') {
  llmResponse = llmItem.content;
} else if (typeof llmItem.response === 'string') {
  llmResponse = llmItem.response;
} else if (typeof llmItem.text === 'string') {
  llmResponse = llmItem.text;
} else if (typeof llmItem.output === 'string') {
  llmResponse = llmItem.output;
}

// ─── 3. Heuristik-Fallback-Funktion ─────────────────────────────
// Sucht das häufigste sinnvolle Substantiv in den Beschreibungen
// und hängt "-Neubau" oder "-Arbeiten" an.
function heuristik() {
  const stopWords = new Set([
    'und', 'der', 'die', 'das', 'ein', 'eine', 'einen', 'einer',
    'mit', 'für', 'in', 'im', 'am', 'auf', 'aus', 'bei', 'nach', 'von', 'zu',
    'liefern', 'montieren', 'herstellen', 'durchführen', 'erstellen',
    'sowie', 'inklusive', 'einschließlich', 'wieder', 'neue', 'alle',
    'Position', 'Stück', 'Quadratmeter', 'Kubikmeter', 'Laufmeter',
    'Meter', 'Pauschal', 'Euro', 'optional'
  ]);
  const positionen = [
    ...(data.regulaere_positionen || []),
    ...(data.optionale_positionen || []),
    ...(data.aufgegriffen_positionen || []),
    ...(data.positionen || [])
  ];
  const wordCounts = {};
  for (const p of positionen) {
    const text = p.beschreibung_normalisiert || p.rohtext || '';
    const words = text.match(/\b[A-ZÄÖÜ][a-zäöüß]{3,}\b/g) || [];
    for (const w of words) {
      if (stopWords.has(w) || stopWords.has(w.toLowerCase())) continue;
      wordCounts[w] = (wordCounts[w] || 0) + 1;
    }
  }
  const sorted = Object.entries(wordCounts).sort((a, b) => b[1] - a[1]);
  if (sorted.length === 0 || sorted[0][1] < 2) {
    return 'Diverse Arbeiten';
  }
  const top = sorted[0][0];
  const isNeubau = positionen.some(p =>
    /\b(neu|neubau|herstellen|aufstellen|errichten|anfertigen)/i
      .test(p.beschreibung_normalisiert || p.rohtext || '')
  );
  return top + (isNeubau ? '-Neubau' : '-Arbeiten');
}

// ─── 4. Kein verwertbarer LLM-Output → Heuristik ────────────────
if (!llmResponse || typeof llmResponse !== 'string' || !llmResponse.trim()) {
  // Diagnose-Info mitgeben, falls der OpenAI-Node-Output ein
  // unerwartetes Feld-Layout hat
  let rawDump = '';
  try {
    rawDump = JSON.stringify(llmItem).substring(0, 500);
  } catch (e) {
    rawDump = 'JSON-Serialisierung fehlgeschlagen: ' + e.message;
  }
  return [{
    json: {
      ...data,
      betreff: heuristik(),
      betreff_quelle: 'fallback_llm_kein_output',
      betreff_llm_raw_dump: rawDump
    }
  }];
}

// ─── 5. Bereinigung ─────────────────────────────────────────────
let llmBetreff = llmResponse
  .trim()
  .replace(/^["'`]+|["'`]+$/g, '')   // Anführungszeichen entfernen
  .replace(/[.!?]+$/, '')             // Trailing-Satzzeichen entfernen
  .replace(/^Betreff:?\s*/i, '')      // "Betreff:"-Prefix entfernen
  .replace(/^Output:?\s*/i, '')       // "Output:"-Prefix entfernen
  .replace(/\s+/g, ' ')               // Multi-Whitespace normalisieren
  .trim();

// ─── 6. Length-Validierung ──────────────────────────────────────
if (llmBetreff.length < 3 || llmBetreff.length > 60) {
  return [{
    json: {
      ...data,
      betreff: heuristik(),
      betreff_quelle: 'fallback_llm_invalid_length',
      betreff_llm_raw: llmResponse
    }
  }];
}

// ─── 7. Erfolg ──────────────────────────────────────────────────
return [{
  json: {
    ...data,
    betreff: llmBetreff,
    betreff_quelle: 'llm'
  }
}];

// ═══════════════════════════════════════════════════════════════
// Telegram Status (Senden-Pfad) v2
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG v2: helpers.httpRequest statt fetch() + Diagnose-Log.
// Siehe telegram_status_audio_v2.js für die ausführliche Begründung.
// ═══════════════════════════════════════════════════════════════

const STATUS_TEXT = '📧 Sende Angebot…';

const inputItem = $input.first();
const data = inputItem.json || {};

const chat_id = data.chat_id;
const bot_token = data.bot_token;

let durationMs = null;
let httpSuccess = false;
let httpError = null;

if (chat_id && bot_token) {
  const t0 = Date.now();
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${bot_token}/sendMessage`,
      body: { chat_id, text: STATUS_TEXT },
      json: true,
    });
    httpSuccess = true;
  } catch (e) {
    httpError = e.message;
    console.warn('[Status Senden] Telegram-Call fehlgeschlagen:', e.message);
  }
  durationMs = Date.now() - t0;
  console.log(`[Status Senden] sendMessage in ${durationMs}ms (success=${httpSuccess})`);
}

return [{
  json: {
    ...inputItem.json,
    _status_senden_diag: { durationMs, httpSuccess, httpError, ts: new Date().toISOString() }
  }
}];

// ═══════════════════════════════════════════════════════════════
// Telegram Status (Audio-Pfad) v2
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG v2: Wechsel von `fetch()` auf `this.helpers.httpRequest`.
// Grund: fetch() im n8n-Code-Node-Kontext lieferte nachvollziehbar
// verzögerte Telegram-Nachrichten — vermutlich weil n8n's Worker
// den nativen fetch-Promise nicht sauber blockierend abwartet.
// helpers.httpRequest ist n8n-nativ und garantiert sequenzielles
// Verhalten: erst wenn der HTTP-Call durch ist, läuft der Workflow
// weiter.
//
// Plus: Diagnose-Log mit Zeitstempeln. Im Execution Log siehst du
// danach genau, wie lang der Telegram-Call gedauert hat.
// ═══════════════════════════════════════════════════════════════

const STATUS_TEXT = '🎙️ Diktat empfangen. Verarbeite…';

const inputItem = $input.first();
const data = inputItem.json || {};

let chat_id = data.chat_id;
let bot_token = data.bot_token;
if (!chat_id || !bot_token) {
  try {
    const mr = $('Message Router').first().json;
    chat_id = chat_id || mr.chat_id;
    bot_token = bot_token || mr.bot_token;
  } catch (e) { /* ignore */ }
}

let durationMs = null;
let httpSuccess = false;
let httpError = null;

if (chat_id && bot_token) {
  const t0 = Date.now();
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${bot_token}/sendMessage`,
      body: { chat_id, text: STATUS_TEXT },
      json: true,
    });
    httpSuccess = true;
  } catch (e) {
    httpError = e.message;
    console.warn('[Status Audio] Telegram-Call fehlgeschlagen:', e.message);
  }
  durationMs = Date.now() - t0;
  console.log(`[Status Audio] sendMessage in ${durationMs}ms (success=${httpSuccess})`);
}

return [{
  json: {
    ...inputItem.json,
    _status_audio_diag: { durationMs, httpSuccess, httpError, ts: new Date().toISOString() }
  },
  ...(inputItem.binary ? { binary: inputItem.binary } : {})
}];

