// ═══════════════════════════════════════════════════════════════
// Diktat-Abbruch-Check
// ═══════════════════════════════════════════════════════════════
// Wird direkt nach "Whisper Transkription" ausgeführt. Prüft das
// Transkript gegen eine Liste eindeutiger Trigger-Phrasen. Bei Match:
//   - Aktive Session aus Static Data löschen (sauberer State)
//   - Item mit ist_abgebrochen=true durchreichen
// Sonst:
//   - Item mit ist_abgebrochen=false unverändert durchreichen
//
// Routing erfolgt im nachfolgenden IF-Node "Abbruch erkannt?".
//
// Trigger-Phrasen sind bewusst alle mit dem Wort "Diktat" (oder
// "alles") gepaart, damit Positionstexte wie "Position 5: Bei Bedarf
// abbrechen" KEINEN Abbruch auslösen.
// ═══════════════════════════════════════════════════════════════

const item = $input.first().json;
const transkript = String(item.text || '').toLowerCase();

const TRIGGER_PATTERNS = [
  /\bdiktat\s+abbrechen\b/,
  /\bdiktat\s+verwerfen\b/,
  /\bdiktat\s+stoppen\b/,
  /\bdiktat\s+löschen\b/,
  /\bdiktat\s+beenden\b/,
  /\bstopp\s+diktat\b/,
  /\babbruch\s+diktat\b/,
  /\bbitte\s+alles\s+abbrechen\b/,
];

let ist_abgebrochen = false;
let matched_phrase = null;

for (const pattern of TRIGGER_PATTERNS) {
  const match = transkript.match(pattern);
  if (match) {
    ist_abgebrochen = true;
    matched_phrase = match[0];
    break;
  }
}

// chat_id / bot_token aus Message Router holen (für nachfolgende Telegram-Nachricht)
let chat_id = null;
let bot_token = null;
try {
  const mr = $('Message Router').first().json;
  chat_id = mr.chat_id;
  bot_token = mr.bot_token;
} catch (e) { /* ignore */ }

// Bei Abbruch: Session aus Static Data räumen, falls eine offen war
if (ist_abgebrochen && chat_id) {
  try {
    const sd = $getWorkflowStaticData('global');
    const sessionKey = `session_${chat_id}`;
    if (sd[sessionKey]) {
      delete sd[sessionKey];
    }
  } catch (e) {
    console.warn('[Abbruch-Check] Session-Cleanup fehlgeschlagen:', e.message);
  }
}

return [{
  json: {
    ...item,
    ist_abgebrochen,
    matched_abbruch_phrase: matched_phrase,
    chat_id,
    bot_token,
  }
}];

// ═══════════════════════════════════════════════════════════════
// Telegram Preview senden v2 (Code-Node mit Inline-Buttons)
// ═══════════════════════════════════════════════════════════════
// Ersetzt den vorherigen HTTP-Request-Node. Drei Gründe:
//
//   1. reply_markup wird als JSON-Object zuverlässig serialisiert
//      (im HTTP-Node-bodyParameter-Modus gab es Probleme mit dem
//      n8n-Expression-Parser, der `=` als Literal beließ statt
//      als Expression-Marker zu interpretieren).
//
//   2. Input-Stream wird unverändert durchgereicht. HTTP-Request-
//      Nodes überschreiben sonst den Stream mit der API-Response.
//
//   3. Konsistent mit Telegram Erfolg v2 und den anderen Status-
//      Code-Nodes im Workflow.
// ═══════════════════════════════════════════════════════════════

const inputItem = $input.first().json;
const chat_id = inputItem.chat_id;
const bot_token = inputItem.bot_token;
const text = inputItem.preview_message;
const replyMarkupRaw = inputItem.reply_markup;

// reply_markup kann als String oder Object übergeben werden — beides handhaben
let reply_markup;
if (typeof replyMarkupRaw === 'string') {
  try {
    reply_markup = JSON.parse(replyMarkupRaw);
  } catch (e) {
    console.error('reply_markup ist kein gültiges JSON:', e.message);
    reply_markup = undefined;
  }
} else if (typeof replyMarkupRaw === 'object' && replyMarkupRaw !== null) {
  reply_markup = replyMarkupRaw;
}

const body = {
  chat_id,
  text,
  parse_mode: 'Markdown'
};
if (reply_markup) {
  body.reply_markup = reply_markup;
}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${bot_token}/sendMessage`,
    body,
    json: true
  });
} catch (e) {
  console.error('Telegram Preview senden fehlgeschlagen:', e.message);
  // trotzdem durchreichen
}

return [{ json: { ...inputItem } }];

// ═══════════════════════════════════════════════════════════════
// Telegram Erfolg v3 (Code-Node, OHNE Inline-Button)
// ═══════════════════════════════════════════════════════════════
// ÄNDERUNG ggü. v2:
//   Inline-Button "📝 Angebot bearbeiten" entfernt.
//
//   Grund: Telegram Erfolg läuft im DOCX-Generator-Branch parallel
//   zum SeaTable+PDF-Branch (Pipeline fortsetzen → beide Branches
//   gleichzeitig). Telegram Erfolg ist sofort da, das PDF (über
//   Komplettzusammenfassung1) kommt ~30s später wegen Gotenberg-
//   PDF-Conversion. Bei Button auf Telegram Erfolg würde der User
//   klicken bevor er das PDF überhaupt gesehen hat — schlechte UX.
//
//   Der Bearbeiten-Button bleibt auf Komplettzusammenfassung1 (die
//   Nachricht mit dem PDF) — dort ist er semantisch passend.
//
// CHANGELOG ggü. v1 (aus v2, unverändert):
//   - Ersetzt vorherigen HTTP-Request-Node
//   - Input-Stream wird durchgereicht
//   - Sendet via this.helpers.httpRequest
// ═══════════════════════════════════════════════════════════════

const inputItem = $input.first();
const docx = $('DOCX Generator').first().json;
const chat_id = $('Message Router').first().json.chat_id;
const bot_token = $('Message Router').first().json.bot_token;

const text = `✅ Angebot *${docx.angebot_nr}* für ${docx.kunden_name} erstellt und per Mail versendet.\n\n📋 ${docx.position_count} Positionen, Modus: ${docx.modus === 'preis' ? 'mit Preisen' : 'ohne Preise'}`;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${bot_token}/sendMessage`,
    body: {
      chat_id,
      text,
      parse_mode: 'Markdown'
    },
    json: true
  });
} catch (e) {
  console.error('Telegram Erfolg fehlgeschlagen:', e.message);
}

return [{ json: { ...inputItem.json } }];

// ═══════════════════════════════════════════════════════════════
// Telegram Bearbeiten-Button v1
// ═══════════════════════════════════════════════════════════════
// Schickt unmittelbar nach Telegram Komplettzusammenfassung1 eine
// kurze sendMessage-Nachricht mit dem Inline-Button "📝 Angebot
// bearbeiten".
//
// Warum separat von der PDF-Nachricht:
//   sendDocument mit multipart/form-data + reply_markup ist in
//   n8n 2.14 nicht zuverlässig umsetzbar. Der HTTP-Node hat einen
//   Expression-Parser-Bug beim `=` Präfix, und Code-Nodes haben
//   weder Zugriff auf `this.helpers.request` noch auf das
//   `form-data`-Package. sendMessage mit JSON-Body funktioniert
//   dagegen problemlos — daher die Aufteilung.
//
// Liest chat_id, bot_token, reply_markup aus dem Filename-PDF-
// setzen-Vorschau1-Node, weil der HTTP-Node davor den Stream mit
// der Telegram-API-Response überschrieben hat.
// ═══════════════════════════════════════════════════════════════

const sourceNode = 'Filename PDF setzen Vorschau1';
let source;
try {
  source = $(sourceNode).first().json;
} catch (e) {
  // Fallback: vorgelagerter Node
  source = $('Send-Session anlegen1').first().json;
}

const chat_id = source.chat_id;
const bot_token = source.bot_token;
const replyMarkupRaw = source.reply_markup;
const angebotsnummer = source.angebotsnummer || '';

// reply_markup parsen (kann String oder Object sein)
let reply_markup;
if (typeof replyMarkupRaw === 'string') {
  try {
    reply_markup = JSON.parse(replyMarkupRaw);
  } catch (e) {
    console.error('reply_markup ist kein gültiges JSON:', e.message);
  }
} else if (typeof replyMarkupRaw === 'object' && replyMarkupRaw !== null) {
  reply_markup = replyMarkupRaw;
}

// Wenn keine Button-Definition → einfach durchreichen, nichts senden
if (!reply_markup) {
  return [{ json: $input.first().json }];
}

const text = angebotsnummer
  ? `_Aktionen für Angebot ${angebotsnummer}:_`
  : '_Aktionen:_';

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${bot_token}/sendMessage`,
    body: {
      chat_id,
      text,
      parse_mode: 'Markdown',
      reply_markup
    },
    json: true
  });
} catch (e) {
  // nicht kritisch — PDF wurde bereits gesendet, nur der Button fehlt
  console.error('Bearbeiten-Button konnte nicht gesendet werden:', e.message);
}

return [{ json: $input.first().json }];
